import type { BankQuestion } from "@/lib/bank";

/** Marketing & Sales Management (Management & Commerce): 714 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-marketing-1","question":"The founder of a kitchen-appliance start-up says: \"Our mixer has the most powerful motor in the market. If we keep improving the engineering, customers will find us.\" Which marketing orientation does this reflect?","options":["Production concept","Product concept","Selling concept","Marketing concept"],"answer":1,"explanation":"The product concept assumes customers favour the best quality or most features and that improving the product is enough. The production concept focuses on cheap and widely available goods, the selling concept on pushing what is made, and the marketing concept starts from customer needs.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-2","question":"A retailer buys a shampoo bottle for ₹80 and sells it for ₹100. What is the retailer's margin on the selling price?","options":["80%","25%","20%","16%"],"answer":2,"explanation":"Margin on selling price = (100 − 80) / 100 = 20%. 25% is the markup on cost (20/80), a common mix-up.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-3","question":"Which sequence correctly describes the standard consumer buying-decision process?","options":["Awareness → interest → desire → action → loyalty","Information search → need recognition → purchase decision → evaluation of alternatives → post-purchase behaviour","Need recognition → evaluation of alternatives → information search → purchase decision → post-purchase behaviour","Need recognition → information search → evaluation of alternatives → purchase decision → post-purchase behaviour"],"answer":3,"explanation":"The five-stage model runs from need recognition through search, evaluation and purchase to post-purchase behaviour. The last option is the AIDA response model used for communication, not the buying process.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-4","question":"A distributor prices all products at a 25% markup on cost. What margin on selling price does this give?","options":["25%","33.3%","20%","18%"],"answer":2,"explanation":"Margin = markup / (1 + markup) = 0.25 / 1.25 = 20%. Markup is on cost; margin is on selling price, so the margin figure is always smaller.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-5","question":"A typewriter manufacturer kept defining its business as \"making the best typewriters\" while customers moved to computers for document writing. The failure is best described as:","options":["Cognitive dissonance","Marketing myopia","Cannibalisation","Brand dilution"],"answer":1,"explanation":"Marketing myopia is defining a business by its current product instead of the customer need it serves (here, producing documents). The firm misses substitutes that meet the same need.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-6","question":"A cola brand creates a loyalty scheme only for customers who buy more than 20 bottles a month. Which segmentation base is it using?","options":["Behavioural (usage rate)","Psychographic","Demographic","Geographic"],"answer":0,"explanation":"Segmenting by how much a customer buys (heavy, medium, light users) is behavioural segmentation on usage rate.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-7","question":"Assertion (A): A segment of 2,000 rare-coin collectors scattered across the country, with no common media or outlet, may be a poor target even if each spends heavily.\nReason (R): For a segment to be useful it must be accessible — the firm must be able to reach and serve it effectively.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"A segment must be measurable, substantial, accessible, differentiable and actionable. A high-value but unreachable group fails the accessibility test, which is exactly why A holds.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-8","question":"Shoppers frequently switch between biscuit brands just to try something new, even though they are happy with their last pack. The category is low involvement and brands differ noticeably. This is:","options":["Complex buying behaviour","Dissonance-reducing buying behaviour","Habitual buying behaviour","Variety-seeking buying behaviour"],"answer":3,"explanation":"Low involvement with significant brand differences produces variety-seeking behaviour. Market leaders respond by dominating shelf space and running reminder advertising; challengers use deals and samples to invite switching.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-9","question":"A customer buys an expensive air conditioner after comparing a few brands she felt were broadly similar. A week later she worries she chose wrongly. What should the marketer prioritise?","options":["Post-purchase reassurance: follow-up calls, warranty reminders and reinforcing communication","Deeper price discounts for new buyers","Launching more variants to widen choice","Reducing advertising since the sale is complete"],"answer":0,"explanation":"High involvement with few perceived brand differences leads to dissonance-reducing behaviour. Post-purchase communication that confirms the choice reduces the doubt (cognitive dissonance) and protects word of mouth.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-10","question":"A biscuit pack has an MRP of ₹50. The retailer earns 20% margin on its selling price and the distributor earns 10% margin on its own selling price. At what price does the company sell to the distributor (ignore taxes)?","options":["₹35","₹36","₹37.50","₹40"],"answer":1,"explanation":"Retailer buys at 50 × 0.8 = ₹40, which is the distributor's selling price. Distributor buys at 40 × 0.9 = ₹36. Adding margins (50 × 0.7 = ₹35) is the classic error because each margin is on a different base.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-11","question":"A brand cuts its price by 10% and unit sales rise by 25%. What happens to sales revenue?","options":["It rises by 15%","It rises by 2.5%","It rises by 12.5%","It falls by 10%"],"answer":2,"explanation":"New revenue = 0.9 × 1.25 = 1.125 of the old, a 12.5% rise. Simply subtracting percentages (25 − 10 = 15%) ignores that the two changes multiply. Elasticity here is −2.5, so demand is elastic and a price cut raises revenue.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-12","question":"An edtech landing page gets 20,000 visitors in a month. 5% sign up as leads, 30% of leads are qualified by the sales team, and 20% of qualified leads buy. How many customers does the funnel produce?","options":["300","60","1,100","600"],"answer":1,"explanation":"20,000 × 0.05 = 1,000 leads → × 0.30 = 300 qualified → × 0.20 = 60 customers. Funnel conversion rates multiply stage by stage.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-13","question":"A B2B sales manager needs 90 closed deals next quarter. Historically 40% of leads become meetings, 50% of meetings become proposals and 25% of proposals close. How many leads must the team generate?","options":["900","1,200","2,250","1,800"],"answer":3,"explanation":"Overall conversion = 0.40 × 0.50 × 0.25 = 5%. Leads needed = 90 / 0.05 = 1,800. Dividing by only one stage rate understates the requirement.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-14","question":"A campaign spends ₹30,000, gets 6,00,000 impressions, 4,800 clicks and 120 purchases. What is the cost per acquisition (CPA)?","options":["₹6.25","₹50","₹250","₹2,500"],"answer":2,"explanation":"CPA = spend / conversions = 30,000 / 120 = ₹250. ₹6.25 is the CPC (30,000 / 4,800) and ₹50 is the CPM (30,000 / 6,00,000 × 1,000).","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-15","question":"A display campaign costs ₹36,000 for 12,00,000 impressions with a click-through rate of 0.4%. What is the cost per click?","options":["₹3.00","₹0.75","₹30.00","₹7.50"],"answer":3,"explanation":"Clicks = 12,00,000 × 0.004 = 4,800. CPC = 36,000 / 4,800 = ₹7.50. ₹30 is the CPM (cost per thousand impressions), not the CPC.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-16","question":"A D2C brand spends ₹2 lakh on ads that generate ₹7 lakh of revenue. Its gross margin is 25%. Which statement is correct?","options":["ROAS is 3.5x, but the campaign loses ₹25,000 after ad spend","ROAS is 3.5x and the campaign earns ₹5 lakh profit","ROAS is 2.5x and the campaign earns ₹1.75 lakh profit","ROAS is 3.5x and the campaign earns ₹1.75 lakh profit"],"answer":0,"explanation":"ROAS = 7 / 2 = 3.5x. Gross profit on the sales = 7 × 0.25 = ₹1.75 lakh, which is less than the ₹2 lakh spent, so the campaign loses ₹25,000. ROAS measures revenue per rupee of spend, not profit.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-17","question":"A company's gross margin is 40%. What is the minimum ROAS at which ad spend just pays for itself (before other costs)?","options":["1.4x","2.5x","4.0x","0.4x"],"answer":1,"explanation":"Break-even ROAS = 1 / gross margin = 1 / 0.40 = 2.5x. At 2.5x, each ₹1 of spend brings ₹2.50 of revenue and ₹1 of gross profit, exactly covering the spend.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-18","question":"In an NPS survey of 500 customers, 260 give scores of 9–10, 140 give 7–8 and 100 give 0–6. What is the Net Promoter Score?","options":["52","72","32","24"],"answer":2,"explanation":"Promoters = 260/500 = 52%; detractors = 100/500 = 20%; NPS = 52 − 20 = 32. Passives count in the base but not in the score.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-19","question":"A survey of 200 customers has 90 promoters, 70 passives and 40 detractors. If service fixes convert 20 of the detractors into passives, by how many points does the NPS rise?","options":["10","20","5","15"],"answer":0,"explanation":"Before: (90 − 40)/200 = 25. After: (90 − 20)/200 = 35. The rise is 10 points. Moving a detractor to passive lifts NPS by half as much as moving one to promoter.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-20","question":"A subscription app earns ₹600 per user per month at a 50% gross margin. Monthly churn is 4%. Using the simple formula, what is the customer lifetime value (gross-margin basis)?","options":["₹15,000","₹7,500","₹12,000","₹300"],"answer":1,"explanation":"Average lifetime = 1/0.04 = 25 months. LTV = 600 × 0.5 × 25 = ₹7,500. ₹15,000 uses revenue instead of margin.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-21","question":"A SaaS firm spends ₹4,500 to acquire a customer who contributes ₹300 of gross margin per month. Monthly churn is 5%. Which assessment is correct?","options":["LTV:CAC is about 0.7 and payback is 15 months — every customer loses money","LTV:CAC is about 3 and payback is 15 months — unit economics are healthy","LTV:CAC is about 1.3 and payback is 20 months — unit economics look weak","LTV:CAC is about 1.3 and payback is 15 months — unit economics look weak"],"answer":3,"explanation":"LTV = 300 / 0.05 = ₹6,000, so LTV:CAC = 6,000 / 4,500 ≈ 1.33. Payback = 4,500 / 300 = 15 months. Against the common 3:1 benchmark this is weak, though still above 1.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-22","question":"A streaming service starts the quarter with 1,000 subscribers, adds 200 new subscribers during the quarter and ends with 1,050. What is the churn rate for the quarter?","options":["5%","19%","15%","20%"],"answer":2,"explanation":"Customers retained from the start = 1,050 − 200 = 850, so retention = 85% and churn = 15%. The net growth of 5% hides the loss of 150 original subscribers.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-23","question":"A firm launches a patented medical gadget. Early buyers are hospitals that care more about capability than price, and the factory can make only limited units in the first year. Which pricing strategy fits best?","options":["Market-penetration pricing","Market-skimming pricing","Loss-leader pricing","Everyday low pricing"],"answer":1,"explanation":"Skimming works when early buyers are price-insensitive, competitors are blocked (patent) and capacity is limited — high prices ration supply and recover R&D before lowering prices for later segments.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-24","question":"A messaging app's value rises as more people join, and its target market is very price-sensitive. Which pricing approach is most appropriate at launch?","options":["Penetration (even free) pricing, to build the user base fast","Prestige pricing, to signal quality","Skimming, to recover development cost quickly","Cost-plus pricing at a high markup"],"answer":0,"explanation":"Network effects plus elastic demand favour penetration pricing: a large base quickly increases value for every user and raises barriers for rivals.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-25","question":"Match each product range with the segmentation base it uses.\nA. A cream made only for humid coastal regions\nB. A range for working women aged 25–40\nC. A range for 'health-obsessed fitness enthusiasts'\nD. Special gift packs for festival buyers\n1. Behavioural (occasion)  2. Geographic  3. Psychographic  4. Demographic","options":["A-2, B-4, C-1, D-3","A-2, B-3, C-4, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-3, D-1"],"answer":3,"explanation":"Region = geographic; age and occupation = demographic; lifestyle and values = psychographic; buying occasion (festivals) = behavioural.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-26","question":"Consider these statements about perceptual (positioning) maps:\nI. A gap on the map always signals an unmet demand worth entering.\nII. Maps should be built from customer perceptions, not engineering specifications.\nIII. The attributes chosen for the axes decide which gaps appear.\nWhich are correct?","options":["I, II and III","I and II only","II and III only","III only"],"answer":2,"explanation":"II and III are correct. A gap may exist because no customer wants that combination (for example, low price with ultra-premium design), so statement I is false; demand must be tested before entering.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-27","question":"A smartwatch brand has won the innovators and early adopters as defined in Rogers' diffusion model. What share of eventual adopters has it reached?","options":["2.5%","13.5%","16%","50%"],"answer":2,"explanation":"Innovators (2.5%) + early adopters (13.5%) = 16%. The early majority (34%) is next; crossing from early adopters to the pragmatic early majority is often the hardest step.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-28","question":"Assertion (A): Penetration pricing is a poor choice when a firm cannot expand capacity in the short run.\nReason (R): Low prices create demand that capacity cannot meet, so the firm sacrifices margin on volume it has to ration anyway.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Penetration pricing earns its return through volume. With fixed capacity the extra demand cannot be served, so the firm gives up margin without gaining volume — R explains A.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-29","question":"A product costs ₹120 per unit (all variable) and sells at ₹150. Management cuts the price by 10%. By what percentage must unit sales rise to keep total contribution unchanged?","options":["10%","25%","50%","100%"],"answer":3,"explanation":"Contribution per unit falls from ₹30 to ₹135 − ₹120 = ₹15. To keep total contribution the same, volume must double: a 100% increase. A small price cut on a thin margin needs a huge volume gain.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-30","question":"An advertisement for a home-security system shows a family sleeping peacefully while the system guards the house. Which level of Maslow's hierarchy does it appeal to?","options":["Physiological","Esteem","Social (belonging)","Safety"],"answer":3,"explanation":"Protection from danger and threats is the safety need. Marketers align the message with the need the product satisfies.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-31","question":"In which stage of the product life cycle do sales usually peak, growth slows and competitors fight mainly on price and promotion?","options":["Introduction","Maturity","Growth","Decline"],"answer":1,"explanation":"Maturity is the longest stage: most potential buyers already own the product, sales level off and competition shifts to price, promotion and small differentiation.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-32","question":"Services marketing extends the traditional 4P mix to 7P. Which of these is one of the three added elements?","options":["Price","Promotion","People","Place"],"answer":2,"explanation":"The extra three are people, process and physical evidence. Price, place and promotion are part of the original 4P.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-33","question":"A TV maker offers free installation, a three-year extended warranty and a home demo with every set. At which product level do these benefits sit?","options":["Core benefit","Augmented product","Expected product","Basic product"],"answer":1,"explanation":"The augmented product adds services and benefits beyond what buyers normally expect, helping the brand stand apart from competitors.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-34","question":"A firm is launching a product into a large market where buyers are unaware of the category, highly price-sensitive, competitors could enter soon, and unit costs fall sharply with volume. Which introduction strategy fits?","options":["Rapid skimming (high price, heavy promotion)","Slow skimming (high price, low promotion)","Slow penetration (low price, low promotion)","Rapid penetration (low price, heavy promotion)"],"answer":3,"explanation":"Unaware buyers need heavy promotion; price sensitivity, scale economies and the threat of entry call for a low price. Together that is rapid penetration. Slow penetration suits a market that already knows the category.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-35","question":"A mature baking-soda brand starts advertising its use as a fridge deodoriser and a cleaning agent. Which maturity-stage strategy is this?","options":["Product modification","Marketing-mix modification","Market modification (new uses and higher usage)","Harvesting"],"answer":2,"explanation":"Market modification grows volume by finding new users or increasing usage — including promoting new uses for the unchanged product. Product modification would change the product itself.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-36","question":"A company cuts all promotion and R&D for a declining product while keeping it on shelves to collect cash for as long as possible. This is:","options":["Divesting","Rejuvenation","Repositioning","Harvesting"],"answer":3,"explanation":"Harvesting reduces costs gradually while sales continue, boosting short-term cash flow. Divesting means selling or dropping the product altogether.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-37","question":"A toothpaste brand that sells well in India starts selling the same product in East African markets. In Ansoff's matrix, this is:","options":["Market development","Market penetration","Product development","Diversification"],"answer":0,"explanation":"Existing product, new market = market development. Product development would be a new product for existing customers.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-38","question":"A dairy firm launches a range of flavoured yoghurts to the same households that already buy its milk. In Ansoff's matrix this is:","options":["Market penetration","Product development","Market development","Diversification"],"answer":1,"explanation":"A new product for existing customers is product development.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-39","question":"Why is diversification usually considered the riskiest of Ansoff's four growth strategies?","options":["It needs the largest advertising budget","It always involves an acquisition","Both the product and the market are new to the firm, so it has little experience in either","It reduces the firm's existing market share"],"answer":2,"explanation":"Diversification combines a new product with a new market, so the firm cannot rely on its existing knowledge of customers or of the product.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-40","question":"A chocolate brand adds a new orange flavour to its bar range, and separately uses the same brand name to launch an ice-cream range. These are, respectively:","options":["Line extension and brand (category) extension","Brand extension and line extension","Co-branding and line extension","Line extension and multibranding"],"answer":0,"explanation":"A new flavour, size or variant within the same category is a line extension. Using the brand in a new category (ice cream) is a brand or category extension.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-41","question":"Which brand architecture best limits the risk that one product's failure or scandal damages the company's other products, though it is costlier to build?","options":["Branded house (one master brand on everything)","House of brands (separate stand-alone brands)","Endorsed brands","Sub-brands under a master brand"],"answer":1,"explanation":"In a house of brands each brand stands alone, so trouble in one does not spill over to the others. The cost is that every brand needs its own marketing investment.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-42","question":"Consider these statements about brand extensions:\nI. A good fit between the parent brand and the new category improves acceptance.\nII. An extension can never hurt the parent brand if it is in a different category.\nIII. Successful extensions can lower launch costs because awareness already exists.\nWhich are correct?","options":["II and III only","I, II and III","I and II only","I and III only"],"answer":3,"explanation":"I and III are correct. II is false: a poor or failed extension in another category can still dilute the parent brand's associations.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-43","question":"In Keller's customer-based brand equity pyramid, which block sits at the top?","options":["Brand salience","Brand performance","Brand resonance","Brand judgements"],"answer":2,"explanation":"The pyramid rises from salience (identity) to performance and imagery (meaning), then judgements and feelings (response) and finally resonance — an intense, active loyalty relationship.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-44","question":"A home-automation kit is adopted slowly: buyers find it difficult to set up and cannot try it before paying. Which two Rogers adoption characteristics explain this, and what is the fitting remedy?","options":["Relative advantage and compatibility — cut the price","Complexity and trialability — simplify set-up and offer free trials or demos","Observability and compatibility — increase advertising","Relative advantage and observability — add features"],"answer":1,"explanation":"High complexity and low trialability slow adoption. Plug-and-play installation, demos and free trials attack both directly.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-45","question":"A new shampoo variant sells 50,000 units; 40% of those buyers would otherwise have bought the brand's existing variant. Contribution is ₹25 per unit on the new variant and ₹20 per unit on the existing one. What is the net incremental contribution?","options":["₹8.5 lakh","₹12.5 lakh","₹7.5 lakh","₹10.5 lakh"],"answer":0,"explanation":"Gross gain = 50,000 × 25 = ₹12.5 lakh. Lost sales of the old variant = 20,000 × ₹20 = ₹4 lakh. Net = ₹8.5 lakh. Valuing the lost units at ₹25 (giving ₹7.5 lakh) or ignoring cannibalisation (₹12.5 lakh) are the usual errors.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-46","question":"In which product life cycle stage are profits typically negative or very low and the promotion-to-sales ratio at its highest?","options":["Decline","Growth","Maturity","Introduction"],"answer":3,"explanation":"At introduction sales are small and the firm spends heavily to build awareness, distribution and trial, so profits are low or negative.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-47","question":"A novelty toy becomes a craze for a few months and then sales collapse almost as quickly as they rose. Its life cycle pattern is that of a:","options":["Style","Fashion","Fad","Scalloped (repeated) cycle"],"answer":2,"explanation":"Fads rise quickly, are adopted with great zeal, peak early and decline fast. Styles last for generations, and fashions pass through slower, regular cycles.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-48","question":"In the BCG matrix, a product with a high relative market share in a low-growth market is a:","options":["Star","Question mark","Dog","Cash cow"],"answer":3,"explanation":"A cash cow generates more cash than it needs; firms usually 'milk' it to fund stars and selected question marks.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-49","question":"A brand holds 15% share in a market growing at 18% a year; the leader holds 30%. Using the BCG convention (high growth above about 10%, relative share above 1.0 is high), how is the brand classified?","options":["Question mark","Star","Cash cow","Dog"],"answer":0,"explanation":"Relative market share = 15 / 30 = 0.5 (low) in a high-growth market, so the brand is a question mark that needs investment to become a star or should be divested.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-50","question":"A company sells three product lines: soaps (4 brands), shampoos (3 brands) and toothpastes (2 brands). What are the width and length of its product mix?","options":["Width 9, length 3","Width 3, length 9","Width 3, length 3","Width 4, length 9"],"answer":1,"explanation":"Width = number of product lines (3). Length = total number of items/brands across lines (4 + 3 + 2 = 9). Depth would be the variants of each brand.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-51","question":"Assertion (A): In the maturity stage, many FMCG firms shift budget from advertising toward trade and consumer sales promotions.\nReason (R): In maturity most buyers already know the category and brands, so switching is driven largely by deals and availability.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"With awareness already high, the marginal rupee works harder as a deal or display that triggers switching than as more awareness advertising — R explains A.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-52","question":"A robotics start-up has won tech enthusiasts but sales have stalled before reaching pragmatic mainstream buyers. Which approach best helps it cross this 'chasm'?","options":["Focus on one niche of pragmatic buyers and give them a complete, proven solution with peer references","Cut prices across all segments at once","Add more advanced features to impress enthusiasts","Shift all spending to mass-media brand advertising"],"answer":0,"explanation":"Mainstream (early majority) buyers want proven, complete solutions and references from people like them. Dominating one niche first creates those references; more features appeal only to enthusiasts.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-53","question":"In a store test, shoppers pay ₹60 for a branded ghee pack and ₹48 for an otherwise identical unbranded pack. What price premium does the brand command?","options":["20%","12%","25%","80%"],"answer":2,"explanation":"Price premium = (60 − 48) / 48 = 25% over the unbranded product. 20% divides by the branded price instead.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-54","question":"A laptop maker displays the logo of its processor supplier on every machine and in its advertising. This is an example of:","options":["Private labelling","Ingredient branding","Line extension","Multibranding"],"answer":1,"explanation":"Ingredient branding promotes a component brand inside the final product, so the host product borrows the component's credibility.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-55","question":"Match each PLC stage with its typical marketing objective.\nA. Introduction  B. Growth  C. Maturity  D. Decline\n1. Reduce spending and harvest, or divest\n2. Build awareness and trial\n3. Maximise share: add features, models and channels\n4. Defend share and extend life by modifying market, product or mix","options":["A-2, B-3, C-1, D-4","A-2, B-4, C-3, D-1","A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1"],"answer":3,"explanation":"Introduction builds awareness and trial, growth maximises share, maturity defends share and extends life, and decline cuts costs and harvests or exits.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-56","question":"Which of these statements about the product life cycle are correct?\nI. Every product follows the same S-shaped curve.\nII. Marketing actions can extend the maturity stage.\nIII. A life cycle can be drawn for a category, a product form or a single brand.\nIV. The PLC reliably predicts how long each stage will last.","options":["II and III only","I, II and III only","II, III and IV only","I and IV only"],"answer":0,"explanation":"II and III are correct. Shapes vary widely (fads, styles, scalloped cycles), and the PLC describes patterns after the fact rather than forecasting exact stage lengths.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-57","question":"A water-purifier category has a potential of 10 lakh households and adoption follows Rogers' adopter categories. Once the entire early majority has adopted, how many households have not yet adopted?","options":["3.4 lakh","8.4 lakh","1.6 lakh","5 lakh"],"answer":3,"explanation":"Innovators 2.5% + early adopters 13.5% + early majority 34% = 50% adopted, so 50% (5 lakh households) — the late majority and laggards — remain.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-58","question":"Assertion (A): A failed extension in a distant category can weaken the parent brand.\nReason (R): Consumers update their beliefs about a brand using information from every product that carries its name.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because associations are shared across products with the same name, a bad experience with the extension can feed back to the parent — R explains A.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-59","question":"A premium watch brand launches a much cheaper line under the same brand name to reach mass buyers. What is the biggest marketing risk of this downward stretch?","options":["Retailers will refuse to stock the premium range","The cheaper line may cannibalise premium sales and dilute the brand's exclusive image","Production costs of the premium line will rise","It will reduce the brand's awareness among mass buyers"],"answer":1,"explanation":"Downward line stretching can pull existing buyers to the cheaper line and weaken the prestige that justified premium prices. Many firms use a separate or sub-brand to limit this.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-60","question":"A brand prices its earphones at ₹499 instead of ₹500 because buyers tend to read it as 'four hundred and something'. This is:","options":["Prestige pricing","Cost-plus pricing","Charm (odd) pricing, a form of psychological pricing","Captive-product pricing"],"answer":2,"explanation":"Charm or odd pricing ends prices just below a round figure so the price feels noticeably lower. It is a psychological pricing tactic.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-61","question":"A manufacturer's unit cost is ₹200 and it adds a standard 30% markup on cost. What is its selling price?","options":["₹230","₹270","₹285.71","₹260"],"answer":3,"explanation":"Cost-plus price = 200 × 1.30 = ₹260. ₹285.71 would give a 30% margin on the selling price (200 / 0.70), which is a different rule.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-62","question":"A retailer wants a 40% margin on its selling price. What markup on cost must it apply?","options":["40%","60%","66.7%","28.6%"],"answer":2,"explanation":"Markup = margin / (1 − margin) = 0.40 / 0.60 = 66.7%. Example: cost ₹60, price ₹100 gives a ₹40 profit — 40% of price but 66.7% of cost.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-63","question":"A firm has fixed costs of ₹6 lakh. Its product sells for ₹250 with a variable cost of ₹150 per unit. What is the break-even volume?","options":["2,400 units","4,000 units","10,000 units","6,000 units"],"answer":3,"explanation":"Break-even units = fixed cost / unit contribution = 6,00,000 / (250 − 150) = 6,000 units. 2,400 divides by the price instead of the contribution.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-64","question":"Demand for a commuter bus pass has a price elasticity of −0.5. If the fare rises by 10%, roughly what happens to revenue?","options":["It falls by about 5%","It rises by about 10%","It rises by about 4.5%","It falls by about 15%"],"answer":2,"explanation":"Quantity falls about 5% (−0.5 × 10%). Revenue = 1.10 × 0.95 = 1.045, a rise of about 4.5%. With inelastic demand, a price rise increases revenue.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-65","question":"A cinema sells popcorn: small ₹150, medium ₹270, large ₹290. Few people buy the medium, but large sales are high. The medium tub's main role is to:","options":["Act as a decoy that makes the large tub look like a bargain","Serve the most price-sensitive buyers","Reduce wastage of popcorn","Act as a loss leader to draw people into the cinema"],"answer":0,"explanation":"The medium is priced close to the large so that the large appears to offer far more for only ₹20 extra. This is the decoy effect.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-66","question":"A luxury perfume is deliberately priced at a high, round ₹10,000, though costs would allow a far lower price. This strategy is:","options":["Going-rate pricing","Penetration pricing","Charm pricing","Prestige pricing"],"answer":3,"explanation":"Prestige pricing uses a high price as a signal of quality and status; for such goods a lower price can actually reduce demand. Round figures reinforce the premium image.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-67","question":"A printer is sold close to cost, while the replacement ink cartridges carry very high margins. This is:","options":["Product-bundle pricing","Optional-product pricing","Captive-product pricing","By-product pricing"],"answer":2,"explanation":"Captive-product pricing prices the main product low and earns profit on the supplies that must be used with it (cartridges, razor blades, coffee pods).","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-68","question":"A firm's unit cost is ₹16, it has invested ₹10 lakh and wants a 20% return on investment. It expects to sell 50,000 units. What is the target-return price?","options":["₹20","₹19.20","₹36","₹18"],"answer":0,"explanation":"Target-return price = unit cost + (ROI × investment) / units = 16 + (0.20 × 10,00,000) / 50,000 = 16 + 4 = ₹20. ₹19.20 applies 20% to the unit cost instead.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-69","question":"A trader's cost is ₹120 and she wants a 25% margin on the selling price. What price must she set?","options":["₹150","₹170","₹145","₹160"],"answer":3,"explanation":"Price = cost / (1 − margin) = 120 / 0.75 = ₹160 (profit ₹40 is 25% of ₹160). ₹150 is a 25% markup on cost, which is only a 20% margin.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-70","question":"Fixed costs are ₹4,00,000, the price is ₹80 and variable cost is ₹48 per unit. How many units must be sold to earn a profit of ₹2,40,000?","options":["20,000","12,500","8,000","13,333"],"answer":0,"explanation":"Units = (fixed cost + target profit) / unit contribution = (4,00,000 + 2,40,000) / 32 = 20,000. 12,500 is only the break-even volume.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-71","question":"A company's fixed costs are ₹9 lakh and its contribution margin ratio is 30%. What sales revenue does it need to break even?","options":["₹2.7 lakh","₹12.9 lakh","₹30 lakh","₹27 lakh"],"answer":2,"explanation":"Break-even revenue = fixed cost / CM ratio = 9 / 0.30 = ₹30 lakh. Multiplying instead of dividing gives ₹2.7 lakh.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-72","question":"A company sells a pack to its distributor at ₹72. The distributor earns 10% on its own selling price, and the retailer earns 20% on the MRP. What MRP should be printed (ignore taxes)?","options":["₹93.60","₹100","₹97.20","₹102.86"],"answer":1,"explanation":"Distributor's selling price = 72 / 0.9 = ₹80. MRP = 80 / 0.8 = ₹100. Adding 10% and 20% on cost (72 × 1.1 × 1.2 = ₹95.04) or adding margins together (72 × 1.3 = ₹93.60) are the usual errors.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-73","question":"An MRP of ₹200 is shared along the chain: the retailer earns 15% on MRP, the wholesaler 8% on its selling price and the super-stockist 4% on its selling price. What does the company realise per unit (ignore taxes)?","options":["₹146.00","₹150.14","₹154.00","₹156.40"],"answer":1,"explanation":"Retailer buys at 200 × 0.85 = ₹170; wholesaler buys at 170 × 0.92 = ₹156.40; super-stockist buys at 156.40 × 0.96 = ₹150.14. Subtracting 27% of MRP (₹146) is wrong because each margin is on a different base.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-74","question":"When a store raises the price of a juice from ₹40 to ₹50, weekly sales fall from 1,000 to 800 packs. Using the midpoint (arc) method, the price elasticity of demand is:","options":["−0.8","−1.0 (unit elastic)","−1.25","−0.2"],"answer":1,"explanation":"%ΔQ = −200 / 900 = −22.2%; %ΔP = 10 / 45 = 22.2%. Elasticity = −1.0, so revenue barely changes (₹40,000 both before and after). Using the starting values gives −0.8, which overstates inelasticity.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-75","question":"A firm faces a constant price elasticity of demand of −3 and a marginal cost of ₹40. Using the profit-maximising markup rule P = MC × E / (E + 1), what price should it charge?","options":["₹53.33","₹60","₹120","₹80"],"answer":1,"explanation":"P = 40 × (−3) / (−3 + 1) = 40 × 1.5 = ₹60. The more elastic the demand, the smaller the optimal markup over marginal cost.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-76","question":"A product sells at ₹100 with a variable cost of ₹60; current volume is 10,000 units. If the price is cut by 5%, by roughly what percentage must volume rise to keep total contribution unchanged?","options":["5%","14.3%","12.5%","8.3%"],"answer":1,"explanation":"Contribution per unit falls from ₹40 to ₹35. Required volume = 10,000 × 40 / 35 ≈ 11,429, a rise of about 14.3%. Small price cuts need much larger volume gains when margins are thin.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-77","question":"A product sells at ₹100 with a variable cost of ₹60 and current volume of 8,000 units. If the price is raised by 10%, by how much can volume fall before total contribution drops below today's level?","options":["10%","16.7%","20%","25%"],"answer":2,"explanation":"Contribution per unit rises from ₹40 to ₹50. Break-even volume = 8,000 × 40 / 50 = 6,400, a 20% fall. Any smaller loss in volume makes the price rise profitable.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-78","question":"Consider these statements:\nI. Skimming suits markets where early buyers are relatively insensitive to price.\nII. Penetration suits markets where unit costs fall sharply with volume.\nIII. Skimming discourages competitors from entering.\nWhich are correct?","options":["I and III only","I, II and III","II and III only","I and II only"],"answer":3,"explanation":"I and II are correct. III is false: the high margins of skimming tend to attract competitors; it is penetration pricing that discourages entry.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-79","question":"An online store shows a jacket as 'MRP ₹1,999 — now ₹1,299'. The struck-out MRP mainly works as:","options":["An external reference price that makes the offer look like a gain","A cost-plus price signal","A captive-product price","A going-rate price"],"answer":0,"explanation":"Showing a higher reference price lets buyers judge the current price as a saving. This framing is a common psychological pricing tool.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-80","question":"A firm wants to charge students a lower price than other buyers for the same software. Which conditions must hold for this segmented pricing to work?\nI. The segments differ in price sensitivity.\nII. Low-price buyers cannot easily resell to high-price buyers.\nIII. The cost of segmenting and policing the market is less than the extra revenue.\nIV. Every segment must pay above the firm's average total cost.","options":["I and II only","I, II and III only","I, II, III and IV","II and IV only"],"answer":1,"explanation":"Segmented pricing needs different elasticities, no easy arbitrage and benefits greater than costs. IV is not required — a low-price segment only needs to cover its variable cost and add some contribution.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-81","question":"Assertion (A): If demand for a product is price-inelastic, a moderate price increase raises total revenue.\nReason (R): With inelastic demand, the percentage fall in quantity is smaller than the percentage rise in price.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Revenue = price × quantity. If |E| < 1, quantity falls proportionally less than price rises, so revenue increases — R explains A directly.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-82","question":"Two customers value a streaming service (X) and a music app (Y) as follows: Customer 1 — X ₹500, Y ₹300; Customer 2 — X ₹300, Y ₹500. Each product has zero marginal cost. Compared with the best separate prices, how much more revenue does a bundle priced at ₹800 earn?","options":["₹400","₹200","₹600","₹0"],"answer":0,"explanation":"Separately, the best is ₹300 per product (both buy both): 4 × 300 = ₹1,200 (pricing at ₹500 gives only ₹1,000). The bundle at ₹800 is bought by both: ₹1,600. Gain = ₹400. Bundling works because the valuations are negatively correlated.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-83","question":"A 'Buy 2, Get 1 Free' offer is equivalent to what percentage discount on the three units?","options":["66.7%","50%","25%","33.3%"],"answer":3,"explanation":"The customer pays for 2 units and gets 3, so the discount is 1/3 ≈ 33.3% of the total value. 50% compares the free unit with the units paid for.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-84","question":"A wholesaler's list price is ₹1,000. A retailer gets a 20% trade discount and then a 5% cash discount for paying early. How much does the retailer pay?","options":["₹750","₹800","₹760","₹950"],"answer":2,"explanation":"After the trade discount: 1,000 × 0.80 = ₹800. After the cash discount: 800 × 0.95 = ₹760. Adding the discounts (25%, giving ₹750) is wrong because they apply in sequence.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-85","question":"A product costs the manufacturer ₹50. The manufacturer adds a 40% markup on cost, the wholesaler 20% on its cost and the retailer 25% on its cost. What is the retail price?","options":["₹92.50","₹110","₹100","₹105"],"answer":3,"explanation":"50 × 1.40 = ₹70 → × 1.20 = ₹84 → × 1.25 = ₹105. Adding the markups (85% on ₹50 = ₹92.50) ignores compounding.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-86","question":"A company plans an MRP of ₹100. The retailer needs 20% on MRP and the distributor 8% on its own selling price. If the company's unit cost is ₹55, what margin does the company earn on its own selling price?","options":["About 33.8%","About 25.3%","About 18.6%","About 17%"],"answer":1,"explanation":"Company's selling price = 100 × 0.80 × 0.92 = ₹73.60. Margin = (73.60 − 55) / 73.60 ≈ 25.3%. 33.8% is the markup on cost (18.60 / 55).","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-87","question":"A software firm's tool saves a client ₹10 lakh a year, and it sets the annual fee at ₹3 lakh regardless of its own cost to serve. This is:","options":["Cost-plus pricing","Going-rate pricing","Value-based pricing","Penetration pricing"],"answer":2,"explanation":"Value-based pricing starts from the value the customer perceives (here, the savings) and sets a price below it, rather than adding a markup to cost.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-88","question":"A supermarket keeps prices consistently low all year and runs very few temporary promotions. This is called:","options":["Everyday low pricing (EDLP)","High–low pricing","Skimming","Loss-leader pricing"],"answer":0,"explanation":"EDLP keeps prices steadily low, saving promotion costs and building trust. High–low pricing uses higher regular prices with frequent deep promotions.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-89","question":"A pickle maker sells only through its own website and delivers straight to consumers. What kind of channel is this?","options":["Three-level channel","One-level channel","Two-level channel","Zero-level (direct) channel"],"answer":3,"explanation":"A zero-level channel has no intermediaries: the manufacturer sells directly to the consumer. Each intermediary (retailer, wholesaler, agent) adds one level.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-90","question":"A new drink brand runs heavy TV and social-media ads so that consumers ask shopkeepers for it by name. This is primarily a:","options":["Push strategy","Trade-promotion strategy","Pull strategy","Personal-selling strategy"],"answer":2,"explanation":"A pull strategy builds consumer demand that 'pulls' the product through the channel. A push strategy uses trade incentives and the sales force to push the product through intermediaries.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-91","question":"Which type of distribution suits a low-priced convenience product such as salt or matchboxes?","options":["Intensive distribution","Selective distribution","Exclusive distribution","Direct distribution only"],"answer":0,"explanation":"Convenience goods are bought frequently with little effort, so they must be available in as many outlets as possible — intensive distribution.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-92","question":"A premium car brand appoints only one dealer in each city and does not let dealers sell competing brands. This is:","options":["Intensive distribution","Exclusive distribution","Selective distribution","Multichannel distribution"],"answer":1,"explanation":"Exclusive distribution gives a single dealer the rights in a territory, often with exclusive-dealing terms. It supports service quality and premium image.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-93","question":"An appliance maker starts selling on its own website at prices lower than those its dealers charge. Dealers protest. This is best described as:","options":["Horizontal channel conflict","Channel cooperation","Vertical integration","Multichannel conflict"],"answer":3,"explanation":"Multichannel conflict arises when a producer uses two or more channels that compete for the same buyers. Horizontal conflict is between members at the same level, such as two dealers of the same brand.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-94","question":"A restaurant chain grows by signing franchise agreements under which independent owners use its brand, menu and systems. Which vertical marketing system is this?","options":["Corporate VMS","Administered VMS","Contractual VMS","Horizontal marketing system"],"answer":2,"explanation":"Franchising links independent firms through contracts, so it is a contractual VMS. A corporate VMS uses common ownership; an administered VMS relies on the size and power of a dominant member.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-95","question":"Which promotion tool is usually seen by audiences as the most credible because the message does not appear to be paid for by the company?","options":["Advertising","Public relations and publicity","Sales promotion","Direct mail"],"answer":1,"explanation":"News stories and features carry more credibility than ads because they appear to come from an independent source. The trade-off is less control over the message.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-96","question":"A brand's TV ads promise 'luxury', its social posts push deep discounts and in-store displays emphasise 'family value'. Customers are confused. What does the brand need?","options":["Integrated marketing communications (IMC)","A bigger media budget","More sales-promotion schemes","A shift to a pure push strategy"],"answer":0,"explanation":"IMC coordinates all communication tools so they carry one clear, consistent message and positioning.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-97","question":"A firm has 1,000 'A' accounts needing 24 calls a year and 2,000 'B' accounts needing 12 calls a year. Each sales rep can make 1,200 calls a year. Using the workload approach, how many reps are needed?","options":["20","30","60","40"],"answer":3,"explanation":"Total calls = 1,000 × 24 + 2,000 × 12 = 48,000. Reps = 48,000 / 1,200 = 40.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-98","question":"A rep's quarterly quota is ₹50 lakh. She earns a fixed salary plus an incentive of 2% on sales above 80% of quota. She sells ₹55 lakh in the quarter. What is her incentive?","options":["₹10,000","₹1,10,000","₹30,000","₹1,00,000"],"answer":2,"explanation":"The threshold is 80% × 50 = ₹40 lakh. Incentive = 2% × (55 − 40) lakh = ₹30,000. Paying 2% on all sales gives ₹1.1 lakh, and paying only on sales above quota gives ₹10,000.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-99","question":"Which of these is NOT a sound principle of sales-territory design?","options":["Territories should be roughly balanced in workload and sales potential","Territories should be easy to cover with minimal travel time","Territory boundaries should make performance easy to measure","Every territory should get the same revenue target regardless of its potential"],"answer":3,"explanation":"Targets should reflect each territory's potential; identical targets for unequal territories feel unfair and demotivate reps. The other three are standard design aims.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-100","question":"A company sells three very different technical product lines — industrial pumps, lab instruments and software — each needing deep product knowledge. Which sales-force structure fits best?","options":["Product structure","Territorial structure","Customer (market) structure","Pure inside-sales structure"],"answer":0,"explanation":"When products are numerous, complex and unrelated, a product-based sales force lets reps specialise. A territorial structure works best for simple, similar products.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-101","question":"A distributor invests ₹10 lakh in stock and receivables, sells ₹1.2 crore a year at a 5% gross margin and spends ₹3.6 lakh on operating costs. What is its return on investment?","options":["60%","24%","36%","12%"],"answer":1,"explanation":"Gross margin = 5% × 1.2 crore = ₹6 lakh. Net = 6 − 3.6 = ₹2.4 lakh. ROI = 2.4 / 10 = 24%. 60% ignores operating costs.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-102","question":"A distributor sells ₹96 lakh a year at a 4% gross margin on sales. Its inventory turns 12 times a year (measured at cost). What is its gross margin return on inventory investment (GMROI)?","options":["4%","48%","50%","12%"],"answer":2,"explanation":"Gross margin = ₹3.84 lakh; cost of goods = ₹92.16 lakh; average inventory = 92.16 / 12 = ₹7.68 lakh. GMROI = 3.84 / 7.68 = 0.5, or 50%. Fast turns make a thin margin attractive; using sales instead of cost (96/12 = 8) gives 48%.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-103","question":"A media plan reaches 60% of the target audience with an average frequency of 4. What are its gross rating points (GRPs)?","options":["240","64","150","24"],"answer":0,"explanation":"GRP = reach (%) × average frequency = 60 × 4 = 240.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-104","question":"A magazine ad costs ₹4.5 lakh. The magazine has 15 lakh readers, of whom 40% belong to the brand's target group. What is the cost per thousand target readers?","options":["₹300","₹750","₹1,125","₹30"],"answer":1,"explanation":"Target readers = 15,00,000 × 0.40 = 6,00,000. Cost per thousand = 4,50,000 / 600 = ₹750. ₹300 uses all readers rather than the target group.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-105","question":"Why is the percentage-of-sales method of setting the promotion budget often criticised?","options":["It needs data that firms rarely have","It ignores the firm's own costs","It always produces budgets larger than competitors'","It treats sales as the cause of promotion rather than its result, so budgets shrink just when sales need support"],"answer":3,"explanation":"Budgets tied to current sales fall when sales fall — exactly when promotion might be most needed. The objective-and-task method, which costs out the tasks needed to reach set objectives, is considered more logical.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-106","question":"A biscuit company pays retailers an extra allowance for placing its packs on the end-of-aisle display. This is a:","options":["Consumer promotion","Public-relations activity","Trade promotion","Personal-selling activity"],"answer":2,"explanation":"Display and merchandising allowances are aimed at channel members, so they are trade promotions. Consumer promotions (coupons, free samples) target end users.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-107","question":"Assertion (A): Personal selling is usually the most effective promotion tool at the later stages of buying, such as building conviction and closing the sale.\nReason (R): Personal selling allows two-way interaction, so the salesperson can answer objections and adapt the offer on the spot.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Advertising is efficient for awareness, but conviction and action benefit from direct interaction, which is what R describes.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-108","question":"Match each promotion tool with its description.\nA. Advertising  B. Sales promotion  C. Public relations  D. Personal selling\n1. Short-term incentives to encourage purchase\n2. Paid, non-personal presentation by an identified sponsor\n3. Building goodwill and favourable publicity\n4. Face-to-face presentation to make sales and build relationships","options":["A-2, B-3, C-1, D-4","A-1, B-2, C-3, D-4","A-2, B-1, C-4, D-3","A-2, B-1, C-3, D-4"],"answer":3,"explanation":"Advertising is paid non-personal communication, sales promotion gives short-term incentives, PR builds goodwill and personal selling is face to face.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-109","question":"Goods move from manufacturer to wholesaler to retailer to consumer. How many levels does this channel have?","options":["One","Two","Three","Four"],"answer":1,"explanation":"Channel levels are counted by the number of intermediaries: wholesaler and retailer make it a two-level channel.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-110","question":"A firm can sell through a distributor who takes 15% of sales, or build its own sales network costing ₹20 lakh a year fixed plus 5% of sales. Above what annual sales level does the own network become cheaper?","options":["₹1 crore","₹1.33 crore","₹2 crore","₹4 crore"],"answer":2,"explanation":"Indifference point: 0.15S = 20,00,000 + 0.05S → 0.10S = 20 lakh → S = ₹2 crore. Above this, the lower variable cost of the own network outweighs its fixed cost.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-111","question":"A field rep costs ₹9 lakh a year and makes 1,000 calls. One call in ten produces an order; the average order is ₹30,000 at a 20% gross margin. Which statement is correct?","options":["Each call costs ₹900 and generates ₹600 of gross margin, so the calls lose money","Each call costs ₹900 and generates ₹3,000 of gross margin, so the calls are profitable","Each call costs ₹90 and generates ₹600 of gross margin, so the calls are profitable","Each call costs ₹900 and generates ₹6,000 of gross margin, so the calls are profitable"],"answer":0,"explanation":"Cost per call = 9,00,000 / 1,000 = ₹900. Expected margin per call = 0.1 × 30,000 × 0.20 = ₹600. Calls lose ₹300 each, so the firm should raise the hit rate, order size or use cheaper channels (inside sales) for these accounts.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-112","question":"Consider these statements:\nI. A push strategy relies mainly on trade margins, trade promotions and the sales force.\nII. A pull strategy relies mainly on consumer advertising and consumer promotions.\nIII. An FMCG firm should use either push or pull, never both together.\nWhich are correct?","options":["I, II and III","I and II only","I and III only","II only"],"answer":1,"explanation":"I and II are correct. III is false: most FMCG firms combine both, using pull to build demand and push to secure shelf space and availability.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-113","question":"A sales manager sets each rep a target of 60 customer visits and 15 product demonstrations a month. What kind of quota is this?","options":["Activity quota","Profit quota","Sales-volume quota","Expense quota"],"answer":0,"explanation":"Activity quotas target behaviours (calls, demos, new accounts) rather than results. They are useful when the sales cycle is long or results lag effort.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-114","question":"Two dealers of the same motorcycle brand in one city keep undercutting each other's prices and poaching each other's customers. This is:","options":["Vertical channel conflict","Channel integration","Multichannel conflict","Horizontal channel conflict"],"answer":3,"explanation":"Horizontal conflict is between members at the same level of the channel. Vertical conflict is between levels, such as dealer versus manufacturer.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-115","question":"Consider these statements about media planning:\nI. Gross rating points equal reach multiplied by average frequency.\nII. New brands and complex messages usually need higher frequency.\nIII. Doubling reach will double sales.\nWhich are correct?","options":["I, II and III","I and II only","II and III only","I only"],"answer":1,"explanation":"I and II are correct. III is false: response to advertising shows diminishing returns and depends on message, product and competition, so sales do not rise proportionally with reach.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-116","question":"A sales team has 120 open opportunities with an average deal size of ₹2 lakh, a 25% win rate and an average sales cycle of 60 days. What is its sales velocity (expected revenue per day)?","options":["₹0.25 lakh","₹4 lakh","₹1 lakh","₹60 lakh"],"answer":2,"explanation":"Sales velocity = opportunities × deal size × win rate / cycle length = 120 × 2 × 0.25 / 60 = ₹1 lakh per day. Raising any of the first three or shortening the cycle increases velocity.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-117","question":"A search ad is shown 50,000 times and clicked 1,000 times. What is its click-through rate?","options":["0.5%","2%","5%","20%"],"answer":1,"explanation":"CTR = clicks / impressions = 1,000 / 50,000 = 2%.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-118","question":"Which activity aims to improve a website's position in unpaid (organic) search results?","options":["Display retargeting","Pay-per-click advertising","Search engine optimisation (SEO)","Affiliate marketing"],"answer":2,"explanation":"SEO improves content, structure and links so pages rank higher organically. Pay-per-click buys paid placements on the results page.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-119","question":"An online store gets 2,500 visitors in a day and 75 of them place orders. What is the conversion rate?","options":["0.3%","3%","7.5%","33%"],"answer":1,"explanation":"Conversion rate = orders / visitors = 75 / 2,500 = 3%.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-120","question":"A video campaign costs ₹12,000 for 8,00,000 impressions. What is its CPM?","options":["₹1.50","₹66.67","₹150","₹15"],"answer":3,"explanation":"CPM = spend / impressions × 1,000 = 12,000 / 8,00,000 × 1,000 = ₹15 per thousand impressions.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-121","question":"In a quarter a company spends ₹6 lakh on marketing and ₹4 lakh on its sales team, and wins 500 new customers. What is its customer acquisition cost?","options":["₹2,000","₹1,200","₹800","₹20,000"],"answer":0,"explanation":"CAC = total sales and marketing spend / new customers = 10,00,000 / 500 = ₹2,000. Using marketing spend alone (₹1,200) understates it.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-122","question":"A website records 4,000 sessions, of which 1,800 view only one page before leaving. What is the bounce rate?","options":["18%","55%","45%","22.5%"],"answer":2,"explanation":"Bounce rate = single-page sessions / total sessions = 1,800 / 4,000 = 45%.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-123","question":"A shopper looks at running shoes on a brand's site but leaves without buying. Over the next week she sees ads for those same shoes on other websites. This is:","options":["Native advertising","Search engine optimisation","Influencer marketing","Retargeting (remarketing)"],"answer":3,"explanation":"Retargeting shows ads to people who have already interacted with the brand, reminding them to complete the purchase.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-124","question":"A customer posts an unprompted video praising a brand's mixer, and it is shared widely. In the paid–owned–earned framework this is:","options":["Earned media","Owned media","Paid media","Shared paid media"],"answer":0,"explanation":"Earned media is exposure the brand did not pay for or control — reviews, shares, word of mouth and press coverage. Owned media is the brand's own website, app or social handles.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-125","question":"A campaign's average cost per click is ₹12 and 4% of clicks convert into purchases. What is the cost per acquisition?","options":["₹48","₹120","₹300","₹3"],"answer":2,"explanation":"CPA = CPC / conversion rate = 12 / 0.04 = ₹300. ₹48 multiplies the CPC by 4 instead of dividing by 4%.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-126","question":"A marketer wants 500 sign-ups from a search campaign. The expected CPC is ₹8 and the click-to-sign-up rate is 2.5%. What budget is required?","options":["₹1 lakh","₹1.6 lakh","₹4,000","₹16,000"],"answer":1,"explanation":"Clicks needed = 500 / 0.025 = 20,000. Budget = 20,000 × ₹8 = ₹1.6 lakh.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-127","question":"An online store's average order value is ₹1,500 and its campaign CPA is ₹500. What ROAS does the campaign deliver?","options":["0.33x","2x","1,000x","3x"],"answer":3,"explanation":"ROAS = revenue / spend. Each ₹500 of spend brings one order worth ₹1,500, so ROAS = 1,500 / 500 = 3x.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-128","question":"Campaign A spends ₹50,000 and generates ₹2 lakh revenue; Campaign B spends ₹20,000 and generates ₹1 lakh. Gross margin is 40% on both. Which statement is correct?","options":["B has the higher ROAS and earns more profit after ad spend","A has the higher ROAS and earns more profit after ad spend","B has the higher ROAS, but A earns more profit after ad spend","Both have the same ROAS"],"answer":2,"explanation":"ROAS: A = 4x, B = 5x. Profit after ads: A = 80,000 − 50,000 = ₹30,000; B = 40,000 − 20,000 = ₹20,000. Higher efficiency does not always mean higher absolute profit.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-129","question":"An email is sent to 40,000 subscribers. 25% open it, 8% of those who open click through, and 5% of those who click buy. How many orders does it produce?","options":["40","400","80","2,000"],"answer":0,"explanation":"Opens = 10,000; clicks = 800; orders = 40. Each rate applies to the previous stage, not to the full list.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-130","question":"A customer yields an annual margin of ₹1,000, the annual retention rate is 80% and the discount rate is 10%. Using LTV = m × r / (1 + i − r), where margins start one year after acquisition, what is the customer lifetime value?","options":["₹4,000","₹5,000","₹8,000","₹2,666.67"],"answer":3,"explanation":"LTV = 1,000 × 0.8 / (1 + 0.1 − 0.8) = 800 / 0.3 ≈ ₹2,666.67. Ignoring discounting and retention lag (1,000 / 0.2 = ₹5,000) overstates value.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-131","question":"A subscription costs ₹500 a month with a 60% gross margin. If CAC is ₹3,600, how many months does it take to recover the acquisition cost?","options":["12 months","7.2 months","6 months","18 months"],"answer":0,"explanation":"Monthly gross margin = 500 × 0.6 = ₹300. Payback = 3,600 / 300 = 12 months. Using revenue instead of margin gives 7.2 months.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-132","question":"A mobile app has a constant monthly churn of 5%. Roughly what share of a cohort is still subscribed after 12 months?","options":["40%","95%","60%","54%"],"answer":3,"explanation":"Retention compounds: 0.95¹² ≈ 0.54, so about 54% remain. Subtracting 12 × 5% = 60% (leaving 40%) treats churn as linear.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-133","question":"1,000 users join an app in January. Each month, 90% of the previous month's active users stay active. How many are active at the end of April (three months later)?","options":["700","729","810","900"],"answer":1,"explanation":"1,000 × 0.9 × 0.9 × 0.9 = 729. Subtracting 10% of the original each month (700) ignores compounding.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-134","question":"A SaaS cohort starts the year at ₹10 lakh of monthly recurring revenue. During the year existing customers add ₹1.5 lakh through upgrades, downgrades remove ₹0.5 lakh and cancellations remove ₹1 lakh. What are the net and gross revenue retention?","options":["NRR 115%, GRR 85%","NRR 100%, GRR 85%","NRR 100%, GRR 90%","NRR 85%, GRR 100%"],"answer":1,"explanation":"NRR = (10 + 1.5 − 0.5 − 1) / 10 = 100%. GRR excludes expansion: (10 − 0.5 − 1) / 10 = 85%. GRR can never exceed 100%.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-135","question":"A brand uses last-click attribution for all its digital spend. What is the most likely distortion?","options":["Every channel gets equal credit","Search ads get too little credit","Upper-funnel channels such as video and display get too little credit","Offline sales get too much credit"],"answer":2,"explanation":"Last-click gives all credit to the final touchpoint (often branded search or retargeting), so channels that created awareness earlier in the journey look less effective than they are.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-136","question":"In an A/B test, Page A converts 60 of 2,000 visitors and Page B converts 78 of 2,000 visitors. What is B's relative lift in conversion rate over A?","options":["0.9%","23.1%","30%","18%"],"answer":2,"explanation":"A = 3.0%, B = 3.9%. Relative lift = (3.9 − 3.0) / 3.0 = 30%. 0.9 percentage points is the absolute difference; 23.1% divides by B instead of A.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-137","question":"A campaign spends ₹2 lakh and the platform reports attribute ₹10 lakh of sales to it. A holdout test shows that 60% of those sales would have happened anyway. What is the incremental ROAS?","options":["5x","2x","3x","1.2x"],"answer":1,"explanation":"Incremental revenue = 40% × 10 lakh = ₹4 lakh. Incremental ROAS = 4 / 2 = 2x. The reported 5x includes sales the ads did not cause.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-138","question":"A brand's main goal for a new campaign is to build awareness among as many people in its target audience as possible. Which buying model fits best?","options":["Cost per mille (CPM)","Cost per acquisition (CPA)","Cost per click (CPC)","Revenue share"],"answer":0,"explanation":"Awareness campaigns pay for exposure, so CPM (cost per thousand impressions) fits. CPC and CPA suit performance goals such as traffic and conversions.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-139","question":"An ad network sells clicks at ₹5 each and the ad's click-through rate is 1.2%. What is the effective CPM (cost per thousand impressions)?","options":["₹6","₹4.17","₹600","₹60"],"answer":3,"explanation":"Per 1,000 impressions there are 12 clicks, costing 12 × ₹5 = ₹60. eCPM = CPC × CTR × 1,000.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-140","question":"A referral app starts with 1,000 users. Each user sends 5 invites on average and 15% of invites convert. If this viral loop repeats indefinitely, how many users will the app eventually have from this seed?","options":["1,750","3,750","4,000","7,500"],"answer":2,"explanation":"Viral coefficient K = 5 × 0.15 = 0.75. Total = 1,000 / (1 − K) = 4,000 (a geometric series 1,000 + 750 + 562.5 + …). With K below 1 growth stops; 1,750 counts only the first round.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-141","question":"On a shopping site 1,200 carts are created in a day, but only 360 lead to completed orders. What is the cart-abandonment rate?","options":["30%","36%","3.3%","70%"],"answer":3,"explanation":"Abandonment = 1 − completed / created = 1 − 360 / 1,200 = 70%.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-142","question":"Consider these statements about customer acquisition economics:\nI. A 'blended' CAC that includes organic sign-ups understates the cost of paid acquisition.\nII. An LTV:CAC ratio above 1 guarantees the business is profitable.\nIII. A long CAC payback period raises cash needs even when the LTV:CAC ratio is healthy.\nWhich are correct?","options":["I and III only","I, II and III","II and III only","I only"],"answer":0,"explanation":"I and III are correct. II is false: LTV:CAC just above 1 may not cover fixed costs, overheads and the time value of money.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-143","question":"An online order averages ₹2,000 at a 45% gross margin. Shipping and payment charges cost ₹200 per order and the CPA is ₹500. What is the contribution per order after acquisition cost?","options":["₹400","₹200","₹700","₹900"],"answer":1,"explanation":"Gross margin = ₹900; minus ₹200 fulfilment and ₹500 CPA leaves ₹200. Ignoring fulfilment (₹400) or CPA (₹700) are the typical slips.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-144","question":"Assertion (A): An ad with a high click-through rate but a very low conversion rate may be attracting the wrong audience or sending people to a weak landing page.\nReason (R): CTR reflects interest in the ad, while conversion depends on audience fit and the post-click experience.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Clicks show the ad is appealing; conversions show whether those people want the product and whether the page delivers. R explains why the two can diverge.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-145","question":"Respondents are asked to rank five tea brands from 1 (most preferred) to 5 (least preferred). What type of scale is this?","options":["Nominal","Interval","Ordinal","Ratio"],"answer":2,"explanation":"Ranks show order but not the size of the gap between positions, so the scale is ordinal.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-146","question":"A hotel room that stays empty tonight cannot be sold again tomorrow. Which service characteristic does this illustrate?","options":["Intangibility","Inseparability","Variability","Perishability"],"answer":3,"explanation":"Services cannot be stored for later sale, so unused capacity is lost — perishability. Hotels and airlines manage it through pricing and reservations.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-147","question":"A brand manager runs her own survey of 800 households to understand snack habits. The data collected is:","options":["Secondary data","Census data","Syndicated data","Primary data"],"answer":3,"explanation":"Primary data is collected fresh for the specific problem at hand. Secondary data already exists, collected earlier for another purpose.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-148","question":"A researcher divides customers into metro, Tier-2 and Tier-3 groups and then draws a random sample from each group in proportion to its size. This is:","options":["Stratified random sampling","Cluster sampling","Quota sampling","Convenience sampling"],"answer":0,"explanation":"Stratified sampling splits the population into homogeneous strata and samples randomly within each, improving precision. Cluster sampling instead selects whole groups at random.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-149","question":"An interviewer at a mall is told to interview any 50 men and any 50 women who agree to stop. This is:","options":["Stratified random sampling","Systematic sampling","Quota sampling","Simple random sampling"],"answer":2,"explanation":"Quota sampling fixes the number from each group but leaves the choice of individuals to the interviewer, so it is a non-probability method — unlike stratified random sampling.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-150","question":"In a bank survey, customers rate how knowledgeable and courteous staff are and whether they inspire trust and confidence. Which SERVQUAL dimension is this?","options":["Reliability","Tangibles","Empathy","Assurance"],"answer":3,"explanation":"Assurance covers knowledge, courtesy and the ability to convey trust and confidence. Reliability is performing the promised service dependably and accurately.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-151","question":"An FMCG company launches its shampoo in ₹2 single-use sachets for village markets. Which element of the rural '4A' framework does this mainly address?","options":["Affordability","Availability","Acceptability","Awareness"],"answer":0,"explanation":"Small unit packs lower the cash outlay per purchase, matching irregular rural incomes — affordability.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-152","question":"A food-delivery firm's managers believe customers mainly want the lowest price, but research shows they care most about delivery speed. In the services gaps model this is:","options":["Gap 3 — the delivery (performance) gap","Gap 2 — the standards (design) gap","Gap 1 — the listening (knowledge) gap","Gap 4 — the communication gap"],"answer":2,"explanation":"Gap 1 is the difference between what customers expect and what management thinks they expect, usually caused by poor research or listening.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-153","question":"A grocery app's ads promise delivery in 15 minutes, but its operations average 40 minutes. Which provider gap does this represent?","options":["Gap 4 — the communication gap","Gap 2 — the standards gap","Gap 3 — the delivery gap","Gap 1 — the listening gap"],"answer":0,"explanation":"Gap 4 is the difference between the service delivered and what external communications promise. Over-promising raises expectations that operations cannot meet.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-154","question":"A hospital has clear written standards for patient discharge within two hours, but understaffed and poorly trained teams routinely miss them. Which gap is this?","options":["Gap 1 — the listening gap","Gap 3 — the delivery (performance) gap","Gap 2 — the standards gap","Gap 5 — the customer gap"],"answer":1,"explanation":"Gap 3 arises when the service delivered does not meet the standards that exist — often because of people, technology or role conflicts.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-155","question":"A hotel's management knows guests want check-in within five minutes, but it has set no specific service standards or processes for front-desk staff. Which gap is this?","options":["Gap 1 — the listening gap","Gap 3 — the delivery gap","Gap 2 — the standards (design) gap","Gap 4 — the communication gap"],"answer":2,"explanation":"Gap 2 is the failure to translate correct knowledge of customer expectations into service designs and standards.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-156","question":"A population has three strata of 12,000, 6,000 and 2,000 customers. With proportional allocation, how many of a 400-person sample come from the smallest stratum?","options":["100","133","20","40"],"answer":3,"explanation":"The smallest stratum is 2,000 / 20,000 = 10% of the population, so it gets 10% of 400 = 40. Equal allocation (133 each) would ignore stratum size.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-157","question":"A researcher wants a systematic sample of 250 from a customer list of 5,000. What sampling interval should she use?","options":["10","20","25","50"],"answer":1,"explanation":"Interval k = population / sample = 5,000 / 250 = 20; she picks a random start between 1 and 20 and then every 20th name.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-158","question":"A survey of 400 randomly chosen customers finds that 50% prefer a new pack design. What is the approximate margin of error at 95% confidence?","options":["±2.5%","±9.8%","±4.9%","±1.2%"],"answer":2,"explanation":"Margin of error = 1.96 × √(0.5 × 0.5 / 400) = 1.96 × 0.025 ≈ 0.049, or ±4.9 percentage points.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-159","question":"A brand wants to estimate a proportion within ±3 percentage points at 95% confidence and has no prior estimate (assume p = 0.5). What minimum sample size is needed?","options":["534","1,068","1,111","267"],"answer":1,"explanation":"n = 1.96² × 0.25 / 0.03² = 1,067.1, rounded up to 1,068. Using z = 2 gives 1,111, and a ±6% margin would need only about 267.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-160","question":"Which statement is valid for a ratio-scale variable but not for an interval-scale variable?","options":["It is meaningful to say one value is twice another","Differences between values are meaningful","The values can be ordered","The mean can be calculated"],"answer":0,"explanation":"Only a ratio scale has a true zero, so ratios are meaningful (₹40,000 income is twice ₹20,000). Temperature in °C is interval: 40°C is not 'twice as hot' as 20°C.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-161","question":"A questionnaire asks customers to rank delivery speed as 'very poor, poor, average, good, very good', treated strictly as an ordinal scale. Which measure of central tendency is most appropriate?","options":["Arithmetic mean","Median","Geometric mean","Harmonic mean"],"answer":1,"explanation":"For strictly ordinal data, the median (or mode) is appropriate because the distances between categories are not known to be equal.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-162","question":"Match each research objective with the most suitable design.\nA. Find out why young buyers are avoiding the brand — no clear hypotheses yet\nB. Measure the share of households that own a microwave\nC. Test whether a new shelf display increases sales\n1. Causal (experimental) research\n2. Exploratory research (focus groups, depth interviews)\n3. Descriptive research (survey)","options":["A-1, B-3, C-2","A-3, B-2, C-1","A-2, B-1, C-3","A-2, B-3, C-1"],"answer":3,"explanation":"Exploratory research generates insights and hypotheses, descriptive research measures 'how many', and causal research tests cause and effect through controlled experiments.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-163","question":"A customer-satisfaction scale gives the same scores when the same people are tested twice, but it actually measures how much they like the advertising rather than the product. The scale is:","options":["Reliable but not valid","Valid but not reliable","Both reliable and valid","Neither reliable nor valid"],"answer":0,"explanation":"Reliability means consistent results; validity means measuring what you intend to measure. A consistent scale aimed at the wrong construct is reliable but not valid.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-164","question":"Consider these statements about rural marketing in India:\nI. Weekly markets (haats) and fairs (melas) are useful contact and sampling points.\nII. Word of mouth and local opinion leaders strongly influence rural purchases.\nIII. Rural demand is largely unaffected by the monsoon and harvest.\nWhich are correct?","options":["II and III only","I, II and III","I and II only","I only"],"answer":2,"explanation":"I and II are correct. III is false: rural incomes depend heavily on agriculture, so demand swings with the monsoon and harvest season.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-165","question":"Assertion (A): Airlines change fares frequently and often discount unsold seats close to departure.\nReason (R): A seat that flies empty cannot be stored and sold on a later flight.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because service capacity is perishable, airlines use yield management to fill seats at whatever price covers more than the near-zero cost of carrying one more passenger. R explains A.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-166","question":"A SERVQUAL study gives these mean scores (7-point scale): Reliability — expectation 6.5, perception 5.2; Responsiveness — expectation 6.0, perception 5.8; Tangibles — expectation 5.0, perception 5.6. Which dimension should management prioritise?","options":["Tangibles, because it has the largest gap","Reliability, because it has the largest negative gap","Responsiveness, because it has the smallest gap","None, since the average gap is positive"],"answer":1,"explanation":"Gap = perception − expectation: reliability −1.3, responsiveness −0.2, tangibles +0.6. Reliability has the largest shortfall. The tangibles gap is positive (exceeding expectations), and the average gap is negative.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-167","question":"Using the SERVQUAL gaps reliability −1.3, responsiveness −0.2 and tangibles +0.6, with importance weights 0.40, 0.35 and 0.25 respectively, what is the weighted overall service-quality gap?","options":["−0.30","−0.44","−0.74","−0.52"],"answer":1,"explanation":"Weighted gap = 0.40 × (−1.3) + 0.35 × (−0.2) + 0.25 × 0.6 = −0.52 − 0.07 + 0.15 = −0.44. The unweighted mean is −0.30; treating the tangibles gap as negative gives −0.74.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-168","question":"Young buyers start using a protein bar after a fitness influencer they admire recommends it, hoping to be seen like her. The influencer acts as:","options":["A membership group","A family influence","A dissociative group","An aspirational reference group / opinion leader"],"answer":3,"explanation":"An aspirational group is one the person wishes to belong to; opinion leaders within it shape choices. Dissociative groups are those people want to avoid.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-169","question":"A customer has decided to buy a particular laptop next week, but then learns her bonus has been cancelled and postpones the purchase. Which factor came between her purchase intention and purchase decision?","options":["Unexpected situational factors","Attitudes of others","Cognitive dissonance","Selective retention"],"answer":0,"explanation":"Between intention and decision, the attitudes of others and unexpected situational factors (such as a drop in income) can change the outcome.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-170","question":"A company stocks a central rural town with a distributor, who then sends vans on fixed routes to supply shops in surrounding villages. This distribution approach is called:","options":["Zero-level distribution","Exclusive distribution","Hub-and-spoke distribution","Reverse logistics"],"answer":2,"explanation":"In hub-and-spoke distribution, a hub (town distributor) serves many spokes (villages), making it economical to reach scattered, low-volume outlets.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-171","question":"A restaurant chain invites diners to rate their meal through an optional online form. Most replies come from very happy or very angry customers. The main problem with using this data to estimate average satisfaction is:","options":["Interviewer bias","Self-selection (non-response) bias","Sampling frame duplication","Acquiescence bias"],"answer":1,"explanation":"People with strong feelings are more likely to respond, so the sample is not representative of all diners. This self-selection or non-response bias distorts the average.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-172","question":"A researcher randomly chooses 20 villages from a district and then surveys every household in those 20 villages. This is:","options":["Stratified sampling","Snowball sampling","Quota sampling","Cluster sampling"],"answer":3,"explanation":"Cluster sampling picks whole groups at random and studies all (or many) units within them. It is cheaper for dispersed populations but usually less precise than stratified sampling.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-173","question":"A soft-drink company cuts sugar across its range and adds clear calorie labels, accepting some short-term loss of sales, because it wants to protect consumers' long-term health. Which concept guides it?","options":["Selling concept","Production concept","Societal marketing concept","Product concept"],"answer":2,"explanation":"The societal marketing concept balances customer wants, company profit and the long-term wellbeing of consumers and society.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-174","question":"A brand's annual sales are ₹45 crore in a category worth ₹300 crore. What is its market share?","options":["6.7%","15%","45%","25%"],"answer":1,"explanation":"Market share = brand sales / total market sales = 45 / 300 = 15%.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-175","question":"A new smartphone matches rivals on camera quality and offers twice their battery life. In positioning terms, battery life is its:","options":["Point of parity","Category membership","Frame of reference","Point of difference"],"answer":3,"explanation":"Points of difference are attributes on which the brand is clearly superior and which customers value; points of parity, like the camera here, simply neutralise rivals' advantages.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-176","question":"A small firm makes tools only for left-handed craftspeople and serves that group alone. Which targeting strategy is this?","options":["Undifferentiated marketing","Differentiated marketing","Concentrated (niche) marketing","Mass customisation"],"answer":2,"explanation":"Concentrated marketing serves one segment deeply, which suits firms with limited resources. Differentiated marketing would design separate offers for several segments.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-177","question":"A target region has 2 crore households; 30% own a car, 25% of car owners buy car-care products, and each such buyer spends ₹1,200 a year. What is the annual market size for car-care products?","options":["₹72 crore","₹720 crore","₹240 crore","₹180 crore"],"answer":3,"explanation":"2 crore × 0.30 × 0.25 = 15 lakh buying households; × ₹1,200 = ₹180 crore. Skipping the 25% filter gives ₹720 crore.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-178","question":"A household spends ₹10,000 a month on groceries, of which ₹3,000 is spent at one supermarket. What is that supermarket's share of wallet for this household?","options":["30%","3%","70%","33%"],"answer":0,"explanation":"Share of wallet = spend with the firm / total category spend = 3,000 / 10,000 = 30%. It measures how much of a customer's category spending a firm captures.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-179","question":"Monthly sales for the last three months were 120, 135 and 150 units. What is the three-month simple moving-average forecast for next month?","options":["150","135","165","142.5"],"answer":1,"explanation":"Moving average = (120 + 135 + 150) / 3 = 135. Note that a simple moving average lags a rising trend; extending the trend would suggest 165.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-180","question":"A firm uses exponential smoothing with α = 0.3. Its forecast for March was 200 units and actual March sales were 240. What is the forecast for April?","options":["240","228","212","220"],"answer":2,"explanation":"New forecast = old forecast + α × (actual − old forecast) = 200 + 0.3 × 40 = 212. Using 0.7 as the weight on the error gives 228.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-181","question":"A new snack targets 50 lakh households. 60% become aware of it, 30% of aware households try it, and 40% of triers buy it again. How many households become repeat buyers?","options":["3.6 lakh","9 lakh","6 lakh","12 lakh"],"answer":0,"explanation":"Aware = 30 lakh; triers = 9 lakh; repeaters = 9 × 0.40 = 3.6 lakh. Each rate applies to the previous stage.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-182","question":"A firm scores two segments out of 10 on size, growth and competitive intensity (higher = less competition), with weights 0.5, 0.3 and 0.2. Segment X scores 8, 6, 4; Segment Y scores 5, 9, 8. Which segment is more attractive?","options":["X, with a weighted score of 6.6 versus 6.8","Y, with a weighted score of 6.8 versus 6.6","X, because it is the largest","Both are equally attractive at 6.0"],"answer":1,"explanation":"X = 0.5×8 + 0.3×6 + 0.2×4 = 6.6. Y = 0.5×5 + 0.3×9 + 0.2×8 = 6.8. Y wins despite being smaller. An unweighted average gives 6.0 for X and 7.3 for Y, so weights matter.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-183","question":"In the positioning statement \"For busy young professionals, FreshBox is the meal kit that gets dinner on the table in 15 minutes, because every ingredient comes pre-cut\", which part is the frame of reference?","options":["Busy young professionals","Every ingredient comes pre-cut","Dinner in 15 minutes","The meal kit"],"answer":3,"explanation":"The frame of reference tells customers which category the brand competes in (meal kits). The target is busy young professionals, the point of difference is speed, and the pre-cut ingredients are the reason to believe.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-184","question":"A hotel chain trains and rewards all employees — from housekeeping to finance — so they understand and deliver the brand's promise. In holistic marketing, this is:","options":["Integrated marketing","Relationship marketing","Internal marketing","Performance marketing"],"answer":2,"explanation":"Internal marketing ensures everyone in the organisation embraces marketing principles, especially those who deliver the service. It is one of the four components of holistic marketing.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-185","question":"Which purchase is most likely to involve extensive problem solving by the buyer?","options":["A regular brand of toothpaste","A first-time purchase of a car","A newspaper","A packet of salt"],"answer":1,"explanation":"Extensive problem solving occurs for expensive, infrequent, risky purchases where the buyer has little experience — such as a first car. The others are routine, low-involvement purchases.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-186","question":"A retailer has 10,000 customers and an annual profit of ₹1 crore. The top 2,000 customers contribute ₹70 lakh of that profit. If 10% of these top customers leave, about how much profit is lost?","options":["₹7 lakh","₹1 lakh","₹10 lakh","₹70 lakh"],"answer":0,"explanation":"Profit per top customer = 70 lakh / 2,000 = ₹3,500. Losing 200 of them costs 200 × 3,500 = ₹7 lakh. Using average profit per customer (₹1,000) would suggest only ₹2 lakh.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-187","question":"A 2,500 sq ft store makes annual sales of ₹1.5 crore. What are its sales per square foot?","options":["₹600","₹1,667","₹60,000","₹6,000"],"answer":3,"explanation":"Sales per sq ft = 1,50,00,000 / 2,500 = ₹6,000 a year — a standard measure of retail space productivity.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-188","question":"A distributor's annual cost of goods sold is ₹60 lakh and its average inventory at cost is ₹5 lakh. Roughly how many days of inventory does it hold (365-day year)?","options":["About 12 days","About 60 days","About 30.4 days","About 8.3 days"],"answer":2,"explanation":"Inventory turnover = 60 / 5 = 12 times a year. Days of inventory = 365 / 12 ≈ 30.4 days.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-189","question":"A biscuit maker reduces pack weight in very small steps over two years so that buyers do not notice, while keeping the price the same. Which consumer-behaviour idea is it relying on?","options":["Cognitive dissonance","Operant conditioning","Selective retention","The just-noticeable difference (Weber's law)"],"answer":3,"explanation":"Weber's law says the smallest change people notice is proportional to the starting level. Changes kept below this just-noticeable difference go largely unnoticed.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-190","question":"A loyal customer reads a negative review of her favourite brand and dismisses it as written by a competitor. This is an example of:","options":["Selective distortion","Selective attention","Selective retention","Subliminal perception"],"answer":0,"explanation":"Selective distortion is interpreting information so that it fits existing beliefs. Selective attention is screening out information; selective retention is remembering only what supports beliefs.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-191","question":"A brand pairs its jingle with cheerful family scenes in every ad until the jingle alone makes viewers feel happy. Which learning process is being used?","options":["Operant conditioning","Classical conditioning","Cognitive learning","Vicarious learning"],"answer":1,"explanation":"Classical conditioning links a neutral stimulus (the jingle) with one that already produces a response (happy scenes) until the neutral stimulus triggers the response alone. Operant conditioning uses rewards for behaviour.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-192","question":"Consider these statements about brand positioning:\nI. Points of parity can be category points of parity or competitive points of parity.\nII. A point of difference should be relevant, distinctive and believable to the target.\nIII. Adding more points of difference always strengthens the positioning.\nWhich are correct?","options":["II and III only","I, II and III","I and II only","I only"],"answer":2,"explanation":"I and II are correct. III is false: too many claims blur the positioning and reduce believability; strong brands focus on a few clear PODs.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-193","question":"Assertion (A): A brand that tries to be seen as both the cheapest and the most premium option risks confused positioning.\nReason (R): Positioning requires trade-offs so that the brand occupies a clear and distinctive place in the target customer's mind.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Effective positioning chooses what the brand will and will not stand for. Contradictory claims leave customers unsure, which is exactly what R explains.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-194","question":"Match each business philosophy with the statement that best represents it.\nA. Production concept  B. Selling concept  C. Marketing concept  D. Societal marketing concept\n1. \"We must persuade people to buy what we make.\"\n2. \"Make it cheap and available everywhere.\"\n3. \"Find out what customers need and satisfy it better than rivals.\"\n4. \"Meet customer needs while protecting long-term consumer and social wellbeing.\"","options":["A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-2, B-1, C-4, D-3","A-2, B-3, C-1, D-4"],"answer":1,"explanation":"Production focuses on efficiency and availability, selling on aggressive persuasion, marketing on customer needs, and societal marketing adds long-term welfare.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-195","question":"An online store has 10,000 visitors a month; 4% add to cart, 50% of those reach checkout and 80% of those pay. Option X raises add-to-cart to 5%; Option Y raises the checkout rate to 60%. Which gives more orders, and by how much?","options":["X, by 8 orders a month","Y, by 8 orders a month","X, by 40 orders a month","Both add the same number of orders"],"answer":0,"explanation":"Today: 10,000 × 0.04 × 0.5 × 0.8 = 160. X: 10,000 × 0.05 × 0.5 × 0.8 = 200. Y: 10,000 × 0.04 × 0.6 × 0.8 = 192. X beats Y by 8 orders; 40 is X's gain over today.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-196","question":"A territory accounts for 8% of national market potential according to the company's buying-power index. If the national sales target is ₹50 crore, what quota should the territory get under a potential-based approach?","options":["₹0.4 crore","₹8 crore","₹6.25 crore","₹4 crore"],"answer":3,"explanation":"Potential-based quota = territory share of potential × national target = 0.08 × 50 = ₹4 crore.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-197","question":"A company has 50 sales reps and annual attrition of 30%. Replacing each rep (hiring, training and lost sales) costs about ₹2 lakh. What is the annual cost of sales-force turnover?","options":["₹30 lakh","₹15 lakh","₹100 lakh","₹60 lakh"],"answer":0,"explanation":"Reps leaving = 50 × 0.30 = 15. Cost = 15 × ₹2 lakh = ₹30 lakh a year.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-198","question":"One industrial customer provides 25% of a supplier's revenue, buys across many product lines and has complex service needs at several plants. What is the most suitable way to manage it?","options":["Treat it like any other account in the territory","Move it to an inside-sales team to cut costs","Serve it only through distributors","Assign a key account manager backed by a cross-functional team"],"answer":3,"explanation":"Key account management gives large, complex, strategic customers a dedicated manager who coordinates sales, service, supply and pricing across the supplier's functions.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-199","question":"A cereal brand puts a free plastic spoon inside each family pack. This consumer promotion is called a:","options":["Price-off pack","Premium","Rebate","Patronage reward"],"answer":1,"explanation":"A premium is an item offered free or at low cost as an incentive to buy. A price-off pack reduces the price printed on the pack.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-200","question":"A brand of outdoor gear uses mountains, harsh weather and tough-looking adventurers in all its communication. On Aaker's brand-personality dimensions, it is building:","options":["Sincerity","Sophistication","Ruggedness","Competence"],"answer":2,"explanation":"Aaker's five dimensions are sincerity, excitement, competence, sophistication and ruggedness. Toughness and the outdoors map onto ruggedness.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-201","question":"A detergent category has 80 lakh target households in a region. In the past year, 20 lakh of them bought the category at least once. What is the category's household penetration?","options":["25%","20%","75%","4%"],"answer":0,"explanation":"Penetration = households that bought at least once / target households = 20 / 80 = 25%. It measures how widely the category is used, not how much each buyer purchases.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-202","question":"A brand's shampoo line comes in 4 variants (anti-dandruff, smooth, volume, herbal), and each variant is sold in 3 pack sizes. What is the depth of this shampoo line?","options":["4","12","3","7"],"answer":1,"explanation":"Depth counts the versions offered of a product: 4 variants × 3 sizes = 12 distinct items. Width and length describe the number of lines and brands, not the versions within one product.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-203","question":"A hospital reorders the same disposable gloves from its approved supplier every month through an automatic system, without reviewing alternatives. Which buying situation is this?","options":["Modified rebuy","New task","Straight rebuy","Systems buying"],"answer":2,"explanation":"A routine reorder from an existing supplier with no re-evaluation is a straight rebuy. A modified rebuy reopens specifications, price or supplier; a new task is a first-time purchase.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-204","question":"A conjoint study for laptops gives these part-worths: Brand A 0.8, Brand B 0.2; price ₹50,000 1.0, price ₹60,000 0.3; battery 10 hours 0.7, battery 6 hours 0.0. Which profile has the highest total utility?","options":["Brand A, ₹60,000, 10-hour battery","Brand A, ₹50,000, 6-hour battery","Brand A, ₹60,000, 6-hour battery","Brand B, ₹50,000, 10-hour battery"],"answer":3,"explanation":"Add the part-worths: B/₹50k/10h = 0.2 + 1.0 + 0.7 = 1.9; A/₹60k/10h = 1.8; A/₹50k/6h = 1.8; A/₹60k/6h = 1.1. The weaker brand wins because it carries the better price and battery levels.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-205","question":"In a conjoint study, the range of part-worths (best level minus worst level) is 1.2 for price, 0.6 for brand and 0.2 for warranty. What is the relative importance of price?","options":["60%","30%","40%","20%"],"answer":0,"explanation":"Relative importance = attribute range / sum of all ranges = 1.2 / 2.0 = 60%. Brand is 30% and warranty 10%.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-206","question":"During a month-long off-invoice discount, a large retailer buys three months' worth of stock and sells most of it later at the regular shelf price. This practice is called:","options":["Diverting","Forward buying","Slotting","Cannibalisation"],"answer":1,"explanation":"Forward buying is stocking up during a trade deal to sell later at normal prices. Diverting is reselling deal-priced stock into regions where the deal does not apply; slotting fees are paid for shelf space.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-207","question":"A store received 800 units of a winter jacket for the season and sold 600 of them by the end of the season. What is its sell-through rate?","options":["133%","25%","75%","60%"],"answer":2,"explanation":"Sell-through = units sold / units received = 600 / 800 = 75%. The remaining 25% is unsold stock that may need markdowns.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-208","question":"A supplier changes its relationship with a large customer from one salesperson dealing with one buyer to multiple contacts — its logistics, quality and finance teams each talk directly to their counterparts at the customer. In key-account management, this shift is from a:","options":["Diamond structure to a bow-tie structure","Push strategy to a pull strategy","Transactional channel to a franchise channel","Bow-tie structure to a diamond structure"],"answer":3,"explanation":"In a bow-tie, all contact flows through the salesperson and the buyer, like the knot of a tie. In a diamond, functions on both sides connect directly, with the key-account manager coordinating, which deepens the relationship.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-209","question":"A snack brand's funnel shows: 80% of target consumers are aware of it, 48% would consider it, 24% have tried it and 6% buy it regularly. Which conversion step is weakest?","options":["Trial to regular purchase","Awareness to consideration","Consideration to trial","Target consumers to awareness"],"answer":0,"explanation":"Conversion ratios: awareness → consideration 48/80 = 60%; consideration → trial 24/48 = 50%; trial → regular 6/24 = 25%. The leak is after trial, which points to product experience or repeat-purchase issues rather than awareness.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-210","question":"A manufacturer offers retailers ₹20 off per case for one month. Sales during the month are 15,000 cases against a normal 10,000. Contribution before the discount is ₹100 per case. Ignoring forward buying, what is the promotion's net effect on contribution?","options":["₹5 lakh gain","₹2 lakh gain","₹4 lakh gain","₹1 lakh loss"],"answer":1,"explanation":"Extra 5,000 cases earn ₹80 each = ₹4 lakh. But the 10,000 cases that would have sold anyway now earn ₹20 less = ₹2 lakh given away. Net gain = ₹4 lakh − ₹2 lakh = ₹2 lakh.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-211","question":"A store has annual sales of ₹1.2 crore at a 25% gross margin and holds average inventory of ₹12 lakh at cost. What is its gross margin return on inventory investment (GMROI)?","options":["10","7.5","2.5","0.4"],"answer":2,"explanation":"Gross margin = 25% of ₹1.2 crore = ₹30 lakh. GMROI = gross margin / average inventory at cost = 30 / 12 = 2.5, meaning each rupee in stock returns ₹2.5 of margin a year. 7.5 is inventory turns (COGS ₹90 lakh / ₹12 lakh).","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-212","question":"A brand is bought by 30% of category buyers. Its buyers give it 40% of their category purchases, and they buy 1.25 times as much of the category as the average category buyer. What is the brand's volume market share?","options":["12%","37.5%","9.6%","15%"],"answer":3,"explanation":"Share = penetration × share of requirements × heaviness index = 0.30 × 0.40 × 1.25 = 15%. Ignoring the heaviness factor gives 12%.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-213","question":"Consider these statements about the B2B buying centre:\nI. Its size usually grows when the purchase is a new task rather than a straight rebuy.\nII. A gatekeeper controls the flow of information to other members.\nIII. The user of a product is always the person who makes the final decision.\nIV. Technical staff who write specifications act as influencers.\nWhich are correct?","options":["I, II and IV only","I and III only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"New, risky purchases draw in more people; gatekeepers filter information; specification writers influence. Users (such as operators) often have little say in the final choice, so III is false.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-214","question":"A region has 1 crore households. 40% of them buy the category, and each buying household purchases 12 packs a year on average. A brand sells 60 lakh packs a year. What is its volume market share?","options":["6%","12.5%","15%","5%"],"answer":1,"explanation":"Category volume = 1 crore × 40% × 12 = 4.8 crore packs. Share = 60 lakh / 480 lakh = 12.5%. Dividing by all households (6%) mixes up households with packs.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-215","question":"Firm A is weighing a price cut. If its rival does not respond, A's profit rises from ₹50 lakh to ₹70 lakh; if the rival matches, A's profit falls to ₹40 lakh. A estimates a 60% chance the rival will match. What is A's expected profit if it cuts the price?","options":["₹58 lakh","₹55 lakh","₹52 lakh","₹40 lakh"],"answer":2,"explanation":"Expected profit = 0.4 × 70 + 0.6 × 40 = 28 + 24 = ₹52 lakh, only slightly above the ₹50 lakh of holding price. ₹58 lakh comes from swapping the probabilities.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-216","question":"A personal-care company has three lines: hair care with 3 brands of 4 variants each, skin care with 2 brands of 5 variants each, and oral care with 1 brand of 3 variants. What are the length and average depth of its product mix?","options":["Length 25, average depth 3","Length 3, average depth about 8.3","Length 6, average depth about 8.3","Length 6, average depth about 4.2"],"answer":3,"explanation":"Length = total brands = 3 + 2 + 1 = 6. Total variants = 12 + 10 + 3 = 25, so average depth per brand = 25 / 6 ≈ 4.2. Width (number of lines) is 3; 8.3 wrongly averages variants per line.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-217","question":"A challenger mouthwash runs ads saying it \"kills as many germs as the leading brand at two-thirds of the price\". In positioning terms, the ad is:","options":["Claiming parity on efficacy and a point of difference on price","Claiming a point of difference on efficacy and parity on price","Building only a category point of parity","Building a premium-price positioning"],"answer":0,"explanation":"\"As many germs as the leader\" neutralises the leader's advantage — a point of parity. The lower price is what sets the challenger apart — its point of difference.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-218","question":"Firm A will gain ₹20 lakh of profit from a price cut if its rival ignores it, and lose ₹10 lakh if the rival matches (relative to not cutting). Above what probability of the rival matching does the price cut have a negative expected value?","options":["50%","66.7%","33.3%","60%"],"answer":1,"explanation":"Expected gain = 20(1 − p) − 10p = 20 − 30p. This is zero at p = 2/3, so above about 66.7% the cut is expected to lose money. 33.3% is the break-even chance of being ignored, not matched.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-219","question":"A ₹20-per-case trade deal lifts a month's sales from a normal 10,000 cases to 15,000. Contribution before the discount is ₹100 per case. Later analysis shows 2,000 of the extra cases were forward-bought and would otherwise have sold the next month at full price. What is the promotion's true net effect on contribution?","options":["₹2 lakh gain","₹1.6 lakh gain","About zero — it just breaks even","₹40,000 loss"],"answer":2,"explanation":"Genuinely new volume is only 3,000 cases, earning ₹80 each = ₹2.4 lakh. The discount is given away on 12,000 cases that would have sold at full price anyway (10,000 baseline + 2,000 pulled forward) = ₹2.4 lakh. The net is zero.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-220","question":"In a smartphone conjoint study, price ₹40,000 has a part-worth of 1.5 and price ₹50,000 has 0.5. A 2-year warranty scores 0.6 against 0.2 for a 1-year warranty. Assuming utility is linear in price, how much is the average respondent willing to pay for the extra year of warranty?","options":["₹6,000","₹2,000","₹10,000","₹4,000"],"answer":3,"explanation":"₹10,000 of price is worth 1.0 utility, so 1 util ≈ ₹10,000. The warranty upgrade adds 0.4 util, worth 0.4 × ₹10,000 = ₹4,000.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-221","question":"An app cohort starts with 1,000 users. Active users are 600 after month 1, 480 after month 2 and 432 after month 3. If month-on-month retention from month 3 onward stays at the month 2 → 3 rate, about how many users remain after month 5?","options":["350","389","315","259"],"answer":0,"explanation":"Month 2 → 3 retention = 432 / 480 = 90%. After month 5: 432 × 0.9 × 0.9 ≈ 350. 389 is the month-4 figure; the flattening curve is typical as low-intent users drop out early.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-222","question":"An online grocer has an average order value (AOV) of ₹800 and a 30% gross margin. Per order it pays ₹70 for fulfilment, ₹50 for last-mile delivery and ₹80 of marketing, plus a payment fee of 2% of order value. If only AOV changes, at what AOV does contribution after marketing become zero?","options":["About ₹667","About ₹714","About ₹800","About ₹625"],"answer":1,"explanation":"Contribution = 0.30A − 0.02A − (70 + 50 + 80) = 0.28A − 200. Setting it to zero gives A = 200 / 0.28 ≈ ₹714. At ₹800 the order earns only ₹24, so basket size is critical to these economics.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-223","question":"Assertion (A): A grocery category with a thin gross margin can still deliver a high GMROI.\nReason (R): GMROI ignores how fast inventory turns over.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"GMROI = gross margin % × (sales / average inventory at cost), so fast turnover can make up for a thin margin — A is true. R is false: turnover is built into the measure.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-224","question":"Match each buying-centre role with the person in an industrial pump purchase.\nA. User  B. Influencer  C. Decider  D. Gatekeeper\n1. Plant engineer who writes the technical specifications\n2. Purchase assistant who decides which supplier brochures reach the team\n3. Operator who will run the pump every day\n4. Managing director who signs off the final supplier","options":["A-1, B-3, C-4, D-2","A-3, B-2, C-4, D-1","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2"],"answer":3,"explanation":"Operators use the product, engineers influence through specifications, the MD decides, and whoever filters information to the group is the gatekeeper.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-225","question":"A shirt tagged at ₹1,000 is marked down to ₹750 at the end of the season. What is the markdown as a percentage of the original price?","options":["25%","33.3%","75%","20%"],"answer":0,"explanation":"Markdown % = (1,000 − 750) / 1,000 = 25%. 33.3% divides the cut by the new price instead of the original one.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-226","question":"A budget airline offers no free meals, no seat choice and tight baggage limits, but charges far less than full-service carriers. Which value proposition is this?","options":["More for more","Less for much less","More for the same","Same for less"],"answer":1,"explanation":"Giving up features in exchange for a much lower price is a 'less for much less' proposition. 'More for more' is premium positioning; 'same for less' matches rivals' benefits at a lower price.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-227","question":"A store's book inventory at retail value is ₹50 lakh, but the physical count shows only ₹48.5 lakh. Its annual sales are ₹2 crore. What is shrinkage as a percentage of sales?","options":["3%","1.5%","0.75%","0.3%"],"answer":2,"explanation":"Shrinkage = ₹50 lakh − ₹48.5 lakh = ₹1.5 lakh, from theft, damage or recording errors. As a share of sales: 1.5 / 200 = 0.75%. 3% wrongly divides by the inventory value.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-228","question":"A brand distributes 10 lakh coupons worth ₹20 each. 3% are redeemed, retailers get ₹2 handling per redeemed coupon, and printing and distribution cost ₹1 lakh. What is the total cost of the coupon drop?","options":["₹6.6 lakh","₹6.0 lakh","₹3.1 lakh","₹7.6 lakh"],"answer":3,"explanation":"Redemptions = 3% × 10 lakh = 30,000. Cost per redemption = ₹20 + ₹2 = ₹22, so ₹6.6 lakh. Add ₹1 lakh of printing and distribution: ₹7.6 lakh in total.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-229","question":"A store's annual sales are ₹60 lakh at retail prices, and its average inventory valued at retail prices is ₹10 lakh. What is its stock turnover?","options":["6 times a year","10 times a year","60 times a year","0.17 times a year"],"answer":0,"explanation":"Turnover = sales / average inventory, both at retail value = 60 / 10 = 6. Measures must be on the same basis — retail with retail or cost with cost.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-230","question":"A supplier is choosing which customers to treat as key accounts. Which criterion is LEAST relevant?","options":["Current and potential revenue","The customer's office being closest to the supplier's head office","Strategic fit and willingness to collaborate","Profitability after cost-to-serve"],"answer":1,"explanation":"Key accounts are picked for their value, potential, strategic fit and profitability, because KAM needs dedicated, costly resources. Being near head office says nothing about value.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-231","question":"A juice brand has awareness similar to its rivals, but far fewer aware consumers would consider buying it. What does this most likely indicate?","options":["It needs more mass-media reach to raise awareness","Its distribution is too wide","A weak or irrelevant brand image among aware consumers — more reach alone will not help","Its repeat-purchase rate is too high"],"answer":2,"explanation":"If people know the brand but do not shortlist it, the problem lies in perceptions — relevance, image or perceived quality. Spending more to make people aware fixes the wrong stage.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-232","question":"A marketplace records gross merchandise value (GMV) of ₹10 crore in a quarter. 20% of it is cancelled or returned, and the marketplace earns a 15% commission on net GMV. What is its commission revenue?","options":["₹1.5 crore","₹0.3 crore","₹8.5 crore","₹1.2 crore"],"answer":3,"explanation":"Net GMV = ₹10 crore × 80% = ₹8 crore. Commission = 15% × ₹8 crore = ₹1.2 crore. Taking 15% of gross GMV (₹1.5 crore) overstates revenue.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-233","question":"A January cohort of 2,000 users has 900 still active in month 3. A February cohort of 2,500 users has 1,000 active in month 3. Which statement is correct?","options":["The January cohort retains better (45% vs 40%), although February has more active users","February retains better because it has more active users","Both cohorts retain 45%","January retains better (50% vs 40%)"],"answer":0,"explanation":"Retention = active / starting users: January 900 / 2,000 = 45%; February 1,000 / 2,500 = 40%. A bigger cohort can hide weaker retention, which is why cohort tables use percentages.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-234","question":"Two rival brands each choose a high or low price. Profits (₹ crore, A first): both high (10, 10); A high and B low (2, 14); A low and B high (14, 2); both low (5, 5). If they decide independently in a single round, what is the likely outcome?","options":["Both price high and earn 10 each","Both price low and earn 5 each","A prices high and B prices low","There is no stable outcome"],"answer":1,"explanation":"Whatever the rival does, pricing low pays more (14 > 10 and 5 > 2), so low is each firm's dominant strategy. Both end at (5, 5) even though (10, 10) was available — a prisoner's dilemma that explains price wars.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-235","question":"A brand normally sells 400 units a week in a store. A feature-and-display promotion lifts sales to 1,000 units in the promotion week, and sales fall to 300 units in each of the next two weeks as shoppers use up stock. What is the net incremental volume?","options":["600 units","800 units","400 units","200 units"],"answer":2,"explanation":"Promotion-week lift = 1,000 − 400 = 600. The post-promotion dip costs 2 × 100 = 200 units. Net incremental = 600 − 200 = 400 units.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-236","question":"Category A sells ₹30 lakh a year from 500 sq ft at a 30% gross margin. Category B sells ₹20 lakh from 250 sq ft at a 25% gross margin. On gross margin per square foot, which category earns its space better?","options":["A — because its total sales are higher","A — ₹1,800 against ₹1,250 per sq ft","B — ₹8,000 against ₹6,000 per sq ft of gross margin","B — ₹2,000 against ₹1,800 per sq ft"],"answer":3,"explanation":"A: ₹9 lakh margin / 500 = ₹1,800 per sq ft. B: ₹5 lakh / 250 = ₹2,000 per sq ft. ₹8,000 and ₹6,000 are sales per sq ft, not margin.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-237","question":"A category's value = households × penetration × purchase frequency × spend per trip. Over a year, penetration rises from 30% to 33%, frequency stays at 6 trips and spend per trip rises from ₹150 to ₹160, with households unchanged. By how much does category value grow?","options":["About 17.3%","About 16.7%","10%","About 6.7%"],"answer":0,"explanation":"Growth factor = (33/30) × (160/150) = 1.10 × 1.0667 = 1.1733, so about 17.3%. Simply adding the two increases (10% + 6.7%) misses the compounding.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-238","question":"A key account brings ₹5 crore of revenue at a 20% gross margin. Serving it costs a dedicated team of ₹30 lakh, special logistics of ₹20 lakh and ₹15 lakh a year for extended credit. What is the account's profit as a percentage of its revenue?","options":["20%","7%","10%","13%"],"answer":1,"explanation":"Gross margin = ₹1 crore. Profit after cost-to-serve = 100 − 30 − 20 − 15 = ₹35 lakh, which is 35 / 500 = 7% of revenue. A big account can look attractive on gross margin but much less so after cost-to-serve.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-239","question":"A premium juice brand faces a new rival selling a similar product at 30% less. Management wants to defend share without weakening the premium image or starting a price war. Which response fits best?","options":["Cut the flagship brand's price by 30%","Withdraw from the segment immediately","Launch a lower-priced fighter brand under a different name","Double the flagship's price to signal quality"],"answer":2,"explanation":"A separately branded fighter takes on the rival at its price point and shields the flagship's positioning. A direct price cut damages premium perceptions and invites retaliation. The risk is that the fighter takes sales from the flagship, so it needs clear separation.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-240","question":"Consider these statements about product-mix decisions:\nI. Adding a new product line increases the width of the mix.\nII. Stretching a line upward adds higher-priced items.\nIII. Line filling adds items within the line's present price range.\nIV. Increasing depth always reduces cannibalisation.\nWhich are correct?","options":["I and IV only","II, III and IV only","I, II, III and IV","I, II and III only"],"answer":3,"explanation":"I–III are standard definitions. IV is false: more variants within a line usually increase the risk that items take sales from one another.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-241","question":"A meal-kit company keeps 75% of its active customers each month, and each active customer orders once a month. On average, how many orders does an acquired customer place over their lifetime?","options":["4","3","1.33","7.5"],"answer":0,"explanation":"With a constant monthly retention r, expected orders = 1 + r + r² + … = 1 / (1 − r) = 1 / 0.25 = 4. Equivalently, average lifetime = 1 / churn = 1 / 0.25 = 4 months.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-242","question":"An e-commerce brand earns ₹150 of contribution on every order and spends ₹500 to acquire a customer. 80% of active customers place another order the following month. On which order does cumulative contribution per acquired customer first exceed the acquisition cost?","options":["4th order","5th order","3rd order","Never — it cannot recover the cost"],"answer":1,"explanation":"Expected contribution per order: 150, 120, 96, 76.8, 61.4. Running totals: 150, 270, 366, 442.8, 504.2, so the cost is first covered on the 5th order. The lifetime ceiling is 150 / 0.2 = ₹750.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-243","question":"A brand sells 1,000 units a week at ₹100 with a variable cost of ₹60. Its own-price elasticity is −3 if the rival does not react and −1 if the rival matches. It considers a 10% price cut. Which statement is correct?","options":["Contribution rises to ₹42,000 if the rival ignores the cut","Contribution is unchanged if the rival ignores the cut","Contribution falls either way — to ₹39,000 if the rival ignores the cut and ₹33,000 if it matches, from ₹40,000","Because demand is elastic, the cut must raise contribution"],"answer":2,"explanation":"At ₹90 the unit margin drops from ₹40 to ₹30. Unmatched: volume +30% to 1,300 → ₹39,000. Matched: +10% to 1,100 → ₹33,000. Elastic demand raises revenue, but the thinner margin still lowers contribution.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-244","question":"Each period, Brand A keeps 80% of its buyers and loses 20% to Brand B, while B keeps 90% of its buyers and loses 10% to A. If these switching rates stay constant, what share will A hold in the long run?","options":["38%","40%","50%","33.3%"],"answer":3,"explanation":"At equilibrium A gains as many as it loses: 0.20a = 0.10(1 − a), so a = 1/3 ≈ 33.3%. 38% is only the next-period share if A started at 40%.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-245","question":"Assertion (A): A store can post high sales per square foot and still be unprofitable.\nReason (R): Sales per square foot is a measure of how productively selling space is used.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true. A store can still lose money through thin margins, high rent or heavy costs, which sales per square foot ignores. R only defines the metric; it does not explain why profit can be low.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-246","question":"Match each retail metric with its formula.\nA. GMROI  B. Sell-through  C. Inventory turnover (at cost)  D. Shrinkage %\n1. Units sold / units received\n2. Gross margin / average inventory at cost\n3. (Book inventory − physical inventory) / sales\n4. Cost of goods sold / average inventory at cost","options":["A-2, B-1, C-4, D-3","A-4, B-1, C-2, D-3","A-2, B-3, C-4, D-1","A-2, B-1, C-3, D-4"],"answer":0,"explanation":"GMROI relates margin to stock investment; sell-through compares units sold with units received; turnover uses COGS over average stock at cost; shrinkage is the stock gap expressed against sales.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-247","question":"An online store's average order is ₹1,000 at a 40% gross margin, with ₹150 of shipping and handling per order. It plans a 10% discount on every order. By how much must order numbers rise to keep total contribution unchanged?","options":["10%","25%","About 66.7%","40%"],"answer":2,"explanation":"Before: 400 − 150 = ₹250 per order. After: revenue ₹900, cost of goods ₹600, so 900 − 600 − 150 = ₹150. Orders must rise by 250 / 150 − 1 ≈ 66.7%. A 10% discount takes 40% of the contribution per order.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-248","question":"A manufacturer funds ₹10 off per unit, but retailers pass only ₹6 of it to shoppers, cutting the shelf price from ₹100 to ₹94. Price elasticity is −2.5. Baseline sales are 20,000 units a month and the manufacturer's contribution is ₹30 a unit before the allowance. What is the promotion's effect on the manufacturer's monthly contribution?","options":["₹2.5 lakh loss","₹0.9 lakh gain","₹4.6 lakh gain","₹1.4 lakh loss"],"answer":3,"explanation":"A 6% shelf-price cut × 2.5 = 15% more volume: 23,000 units. The manufacturer earns ₹30 − ₹10 = ₹20 on each: ₹4.6 lakh, against ₹6 lakh at baseline — a ₹1.4 lakh loss. Weak pass-through limits the lift while the manufacturer pays the full allowance.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-249","question":"Consider these statements about conjoint analysis:\nI. An attribute's relative importance depends on the range of levels tested.\nII. Part-worths can be used to simulate preference shares for new product profiles.\nIII. Adding a very high price level to the design can raise price's measured importance.\nIV. Respondents must rate each attribute separately, in isolation from the others.\nWhich are correct?","options":["I, II and III only","I and IV only","II and III only","I, II, III and IV"],"answer":0,"explanation":"Importance is computed from part-worth ranges, so widening a range (III) raises it, and part-worths feed market simulators. IV is wrong: conjoint asks for trade-offs between whole profiles, then works backwards to the value of each attribute.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-250","question":"In a store's breakfast-cereal aisle there are 60 facings in total, and 12 of them belong to one brand. What is that brand's share of shelf?","options":["12%","20%","25%","5%"],"answer":1,"explanation":"Share of shelf = brand facings / total category facings = 12 / 60 = 20%. Brands often compare it with their market share to judge whether they have fair visibility.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-251","question":"A malted health drink long sold as a children's nutrition product is now advertised to working adults as an everyday protein drink, with the same name and recipe. This is an example of:","options":["Line filling","Co-branding","Repositioning","Rebranding with a new name"],"answer":2,"explanation":"Changing the target and the frame in which a brand is seen, while keeping the product and name, is repositioning.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-252","question":"A brand is bought by 15% of the 2 crore households in its market. It wants to reach 20% penetration. How many additional buying households does it need?","options":["5 lakh","40 lakh","30 lakh","10 lakh"],"answer":3,"explanation":"The target rises by 5 percentage points: 5% × 2 crore = 10 lakh more households. 40 lakh is the total at 20%, not the increase.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-253","question":"A large retailer asks the leading supplier in the hair-care category to analyse shopper data and recommend the assortment and shelf layout for the whole category, including rival brands. The supplier is acting as a:","options":["Category captain","Channel captain","Rack jobber","Gatekeeper"],"answer":0,"explanation":"A category captain is a supplier trusted to advise on the whole category. A channel captain is the most powerful member leading a channel; a rack jobber stocks and maintains its own racks inside stores.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-254","question":"A store gets 2,000 visitors a day. 15% of them buy, and the average transaction value is ₹600. What are its daily sales?","options":["₹12 lakh","₹1.8 lakh","₹3 lakh","₹90,000"],"answer":1,"explanation":"Sales = footfall × conversion × average transaction value = 2,000 × 0.15 × 600 = ₹1,80,000. Each of the three levers can be managed separately.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-255","question":"A city metro authority wants one contractor to design, supply, install and maintain its entire ticketing system, instead of buying gates, software and servicing separately. This is:","options":["Straight rebuy","Reciprocal buying","Systems buying","Value analysis"],"answer":2,"explanation":"Buying a complete solution from a single supplier is systems buying (or solution buying). Sellers respond with systems selling — bundling hardware, software and service.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-256","question":"A shopper buys the same toothpaste every month only because it is the one stocked at her nearby shop. She feels no particular attachment to it and would switch if another brand were on offer. Her loyalty is best described as:","options":["True loyalty","Latent loyalty","Negative loyalty","Spurious loyalty"],"answer":3,"explanation":"High repeat buying with a weak attitude is spurious loyalty: it rests on convenience or habit and breaks easily. True loyalty combines strong attitude and repeat buying; latent loyalty is a strong attitude without matching purchases.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-257","question":"An online seller ships 1,000 cash-on-delivery orders. 25% are refused at the door and return to origin, and each refused order costs ₹120 in two-way shipping. What is the return-to-origin cost on these orders?","options":["₹30,000","₹1,20,000","₹15,000","₹25,000"],"answer":0,"explanation":"Refused orders = 25% × 1,000 = 250. Cost = 250 × ₹120 = ₹30,000. High COD refusal rates are why sellers push prepaid payments.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-258","question":"In a conjoint simulator, four respondents' total utilities for three products are: R1 — P 2.1, Q 1.8, R 1.0; R2 — P 1.2, Q 1.9, R 1.5; R3 — P 1.7, Q 1.6, R 2.2; R4 — P 2.4, Q 1.1, R 1.3. Under the first-choice rule (each respondent picks their highest utility), what is P's preference share?","options":["25%","50%","33.3%","75%"],"answer":1,"explanation":"P is the top choice for R1 and R4; Q wins R2 and R wins R3. So P gets 2 of 4 = 50%, Q 25% and R 25%.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-259","question":"A brand holds 20% of a ₹500 crore category. Next year the category grows 10% while the brand's sales grow 5%. What is its new market share?","options":["15%","21%","About 19.1%","20%"],"answer":2,"explanation":"Brand sales = ₹100 crore × 1.05 = ₹105 crore; category = ₹550 crore. Share = 105 / 550 ≈ 19.1%. A brand growing slower than its category loses share.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-260","question":"A market of 10,000 units sells at ₹100, and the leader's variable cost is ₹50. The leader holds 60% share. A challenger cuts its price by 10%. If the leader matches, it keeps 60% share at ₹90; if it does not match, its share falls to 50% at ₹100. Which choice gives the leader more contribution?","options":["Matching — ₹2.4 lakh against ₹2 lakh","Matching — by ₹50,000","Both give ₹3 lakh","Not matching — ₹2.5 lakh against ₹2.4 lakh"],"answer":3,"explanation":"Match: 6,000 units × ₹40 = ₹2.4 lakh. Hold price: 5,000 units × ₹50 = ₹2.5 lakh. Here the margin protected by holding price outweighs the lost share, though the long-term effect of lower share also matters.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-261","question":"A buyer plans end-of-month stock of ₹40 lakh, sales of ₹25 lakh and markdowns of ₹5 lakh for the month. Stock at the start of the month is ₹45 lakh and ₹10 lakh is already on order. What is the open-to-buy?","options":["₹15 lakh","₹25 lakh","₹35 lakh","₹5 lakh"],"answer":0,"explanation":"Open-to-buy = planned end stock + planned sales + planned markdowns − beginning stock − stock on order = 40 + 25 + 5 − 45 − 10 = ₹15 lakh still available to buy.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-262","question":"Consider these statements:\nI. A brand can gain market share while its sales fall, if the category shrinks faster.\nII. A relative market share above 1 means the brand is the category leader.\nIII. A brand's household penetration can rise while its volume share falls.\nIV. Share of wallet and market share always move in the same direction.\nWhich are correct?","options":["I and IV only","I, II and III only","II and III only","I, II, III and IV"],"answer":1,"explanation":"I: share is relative to the category. II: relative share compares the brand with its largest rival, so above 1 means it leads. III: new light buyers can join while heavy buyers cut back. IV is false — wallet share is measured per customer and can move independently of overall share.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-263","question":"A D2C brand spends ₹10 lakh on paid ads in a month and gains 2,000 new customers, of whom 800 came through organic channels unrelated to the ads. What is its paid customer acquisition cost?","options":["₹500","₹1,250","About ₹833","About ₹417"],"answer":2,"explanation":"Paid CAC = paid spend / paid customers = ₹10 lakh / 1,200 ≈ ₹833. The blended figure of ₹500 hides the true cost of buying customers through ads.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-264","question":"A trade promotion generates 12,000 incremental units at ₹50 contribution each. It costs ₹2 lakh in allowances, ₹1.5 lakh in display fees and ₹0.5 lakh in administration. What is its return on investment?","options":["150%","33.3%","66.7%","50%"],"answer":3,"explanation":"Incremental contribution = 12,000 × 50 = ₹6 lakh. Cost = ₹4 lakh. ROI = (6 − 4) / 4 = 50%. 150% compares gross contribution with cost without netting the cost out.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-265","question":"Brand X: 90% aware, 45% consider, 30% tried, 15% buy regularly. Brand Y: 60% aware, 36% consider, 27% tried, 18% buy regularly. Which reading is correct?","options":["Y converts better at every stage; X's lead rests only on awareness","X converts better at every stage","Both convert equally from trial to regular use","X has more regular buyers than Y"],"answer":0,"explanation":"Y: 60% → consider, 75% → trial, 67% → regular. X: 50%, 67%, 50%. Y ends with more regular buyers (18% vs 15%) despite lower awareness, so X needs to fix conversion, not reach.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-266","question":"A brand targets 20% volume share of its category. Its buyers give it 40% of their category purchases and buy only 0.8 times the category quantity of an average category buyer. What penetration among category buyers does it need?","options":["50%","62.5%","32%","80%"],"answer":1,"explanation":"Share = penetration × share of requirements × heaviness, so penetration = 0.20 / (0.40 × 0.8) = 62.5%. Ignoring that its buyers are lighter than average gives 50%.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-267","question":"An online apparel brand's average order is ₹2,000 at a 40% gross margin. Each shipment costs ₹100 forward, and a return costs another ₹100 in reverse logistics; returned items are restocked and earn no margin. If the return rate falls from 25% to 15%, by how much does the expected contribution per shipped order rise?","options":["₹80","₹70","₹90","₹100"],"answer":2,"explanation":"A kept order earns 800 − 100 = ₹700; a returned one loses ₹200. At 25% returns: 0.75 × 700 − 0.25 × 200 = ₹475. At 15%: 0.85 × 700 − 0.15 × 200 = ₹565. Gain = ₹90 per shipped order.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-268","question":"A cohort table shows active users as a share of each starting cohort: January — M1 50%, M2 40%, M3 36%; February — M1 55%, M2 46%; March — M1 60%.\nI. Month-1 retention is improving across cohorts.\nII. January's retention from M2 to M3 is 90%.\nIII. February's retention from M1 to M2 is lower than January's.\nIV. March's month-3 figure cannot be observed yet.\nWhich are correct?","options":["I, II and III only","II and III only","I, II, III and IV","I, II and IV only"],"answer":3,"explanation":"M1 rises 50 → 55 → 60%. January M2 → M3 = 36 / 40 = 90%. February M1 → M2 = 46 / 55 ≈ 84%, which beats January's 40 / 50 = 80%, so III is false. Later cohorts have shorter histories, so March's M3 is not yet known.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-269","question":"Assertion (A): Adding more variants to a product line always lowers unit costs through scale.\nReason (R): Each extra variant adds complexity in production, inventory and shelf management.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"R is true and in fact argues against A: more variants split volume and add changeovers, stock-keeping and shelf costs, so unit costs often rise. A is false.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-270","question":"Match each trade-promotion form with its description.\nA. Off-invoice allowance  B. Bill-back allowance  C. Slotting allowance  D. Cooperative advertising\n1. Paid after the retailer proves it ran the agreed feature or display\n2. A fee to list a new product on the retailer's shelves\n3. A deduction from the invoice price on purchases made during the deal period\n4. The manufacturer shares the cost of the retailer's local ads featuring its brand","options":["A-3, B-1, C-2, D-4","A-1, B-3, C-2, D-4","A-3, B-2, C-1, D-4","A-3, B-1, C-4, D-2"],"answer":0,"explanation":"Off-invoice deals cut the price at once, which is why they invite forward buying. Bill-backs are paid only after proof of performance. Slotting fees buy listing, and co-op advertising shares local media costs.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-271","question":"A market of 20,000 units sells at ₹200; the leader's variable cost is ₹120 and it holds 50% share. A challenger cuts its price by 10%. If the leader matches (to ₹180), it keeps 50% share. How many share points can the leader lose by holding its price before matching becomes the better choice?","options":["10 points","12.5 points","25 points","5 points"],"answer":1,"explanation":"Matching earns 10,000 × ₹60 = ₹6 lakh. Holding price earns s × 20,000 × ₹80, which equals ₹6 lakh at s = 37.5%. So the leader can lose up to 12.5 points before matching pays more.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-272","question":"On a perceptual map (quality, value), a segment's ideal point is (8, 6). Brands sit at P (7, 5), Q (9, 8), R (8, 3) and S (8, 4.5). The segment cares twice as much about quality, so distance = √[2 × (quality gap)² + (value gap)²]. Which brand is closest to the ideal?","options":["P","Q","S","R"],"answer":2,"explanation":"Weighted distances: S = 1.5; P = √(2 + 1) ≈ 1.73; Q = √(2 + 4) ≈ 2.45; R = 3. Unweighted, P (1.41) would edge S (1.5), so the importance weighting changes the answer.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-273","question":"A family deciding how to spend a Saturday evening considers a new film at a cinema, a dinner at a restaurant or a board-game café. For the cinema chain, the restaurant represents which level of competition in Kotler's framework?","options":["Brand competition","Industry competition","Form competition","Generic competition"],"answer":3,"explanation":"Generic competition is between all firms competing for the same consumer spending or need, here 'entertainment for an evening out'. Brand competition would be another cinema chain; industry competition, any film exhibitor.","difficulty":"very-hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-274","question":"A biscuit challenger avoids the leader's strongholds in metros and instead pushes hard in small towns and rural markets that the leader has served weakly. In Kotler's terms, which attack strategy is this?","options":["Frontal attack","Flank attack","Encirclement attack","Guerrilla attack"],"answer":1,"explanation":"A flank attack targets geographic or segment gaps where the leader is weak. A frontal attack matches the leader on its own ground; encirclement launches a broad offensive on many fronts at once.","difficulty":"hard","source":"FMCG MT · Sales MT · MBA placement"},
  {"id":"mgmt-marketing-275","question":"Instead of fighting the market leader in feature phones, a challenger skips the category and puts all its resources into the next generation of smartphones, where the leader is not yet present. This is a:","options":["Bypass attack","Flank attack","Frontal attack","Mobile defence"],"answer":0,"explanation":"A bypass attack sidesteps the competitor entirely, for example by leapfrogging to a new technology or diversifying into unrelated markets. Mobile defence is a leader's move, not a challenger's attack.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-276","question":"A premium detergent leader sees a low-priced entrant gaining share among price-sensitive households. It launches its own low-priced 'fighter brand' aimed only at that segment, leaving its main brand's price unchanged. In Kotler's defence strategies, this is closest to:","options":["Position defence","Contraction defence","Flank defence","Counteroffensive defence"],"answer":2,"explanation":"A flank defence protects a weak side of the leader's position, often with a fighter brand in an exposed segment. Position defence fortifies the existing brand; contraction defence withdraws from weak markets.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-277","question":"A market follower copies the leader's product and packaging closely but adapts it for local tastes, sometimes improving on it, and sells in different markets from the leader. Which follower strategy is this?","options":["Counterfeiter","Cloner","Adapter","Imitator"],"answer":2,"explanation":"Kotler's adapter takes the leader's product and adapts or improves it, often for different markets, and may grow into a challenger. A cloner copies the product and packaging almost exactly with slight variations.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-278","question":"A company tries to be both the lowest-cost producer and the most differentiated, premium-priced brand in its category, but achieves neither and earns below-average returns. In Porter's terms, it is:","options":["Pursuing a focus strategy","Stuck in the middle","A cost leader","A differentiator"],"answer":1,"explanation":"Porter warned that firms which fail to commit to cost leadership, differentiation or focus become 'stuck in the middle', with no clear competitive advantage.","difficulty":"moderate","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-279","question":"In an industry, the product is standardised, there are dozens of suppliers, and buyers are a few large retail chains that can switch suppliers at almost no cost. In Porter's five-forces terms, what is the likely effect?","options":["High buyer power, squeezing suppliers' margins","High supplier power, raising input costs","Low rivalry among existing firms","High barriers to entry"],"answer":0,"explanation":"Concentrated buyers, standard products and low switching costs give buyers strong bargaining power over the many sellers, pressing prices and margins down.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-280","question":"A regional snack maker has weak distribution in modern trade (a weakness) but sees fast growth in quick-commerce apps (an opportunity). It signs an exclusive listing deal with a quick-commerce platform. In a TOWS matrix, this is which type of strategy?","options":["SO (strength–opportunity)","ST (strength–threat)","WT (weakness–threat)","WO (weakness–opportunity)"],"answer":3,"explanation":"A WO strategy uses an external opportunity to overcome an internal weakness. SO strategies use strengths to exploit opportunities; WT strategies minimise weaknesses and avoid threats.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-281","question":"A business buyer compares two suppliers (figures in ₹'000). Supplier A: product benefit 35, service 8, personnel 4, image 3; costs — price 30, time 3, energy 1, psychological 1. Supplier B: product benefit 30, service 10, personnel 5, image 3; costs — price 27, time 2, energy 2, psychological 1. Using customer-perceived value = total benefit − total cost, which supplier offers more value and by how much?","options":["A, by ₹2,000","Equal value","B, by ₹1,000","B, by ₹3,000"],"answer":2,"explanation":"A: benefits 50 − costs 35 = 15. B: benefits 48 − costs 32 = 16, so B wins by ₹1,000. Comparing only price (B cheaper by ₹3,000) or only benefits (A ahead by ₹2,000) gives the wrong picture.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-282","question":"A new airline plans to drop meals and lounges (eliminate), cut seat pitch slightly (reduce), offer more frequent short-haul flights (raise) and introduce app-based self-check-in with no queues (create). Which framework is it using?","options":["Ansoff matrix","BCG matrix","The ERRC grid from Blue Ocean Strategy","Porter's five forces"],"answer":2,"explanation":"The eliminate–reduce–raise–create grid is the Blue Ocean tool for redrawing the industry's value curve to create uncontested market space.","difficulty":"moderate","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-283","question":"A pet-food start-up estimates 1.2 crore pet-owning households spending ₹6,000 a year each on pet food. Only 25% of them are in metros reachable by its online delivery, and it expects to win 5% of that reachable market in three years. What are its TAM, SAM and SOM?","options":["TAM ₹7,200 crore; SAM ₹1,800 crore; SOM ₹90 crore","TAM ₹7,200 crore; SAM ₹1,800 crore; SOM ₹360 crore","TAM ₹1,800 crore; SAM ₹90 crore; SOM ₹4.5 crore","TAM ₹7,200 crore; SAM ₹360 crore; SOM ₹90 crore"],"answer":0,"explanation":"TAM = 1.2 crore × ₹6,000 = ₹7,200 crore; SAM = 25% of that = ₹1,800 crore; SOM = 5% of SAM = ₹90 crore. Taking 5% of TAM instead gives ₹360 crore.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-284","question":"A category grows 6% in volume and the average price per unit rises 4%. By how much does the category's value (sales revenue) grow?","options":["10%","10.24%","2%","24%"],"answer":1,"explanation":"Value growth = (1.06 × 1.04) − 1 = 10.24%. Simply adding the two gives 10%, which misses the cross-effect of the price rise on the extra volume.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-285","question":"A smartphone brand offers the camera and display of premium rivals at the price of mid-range phones. Which of Kotler's winning value propositions does this represent?","options":["More for more","More for less","Same for less","More for the same"],"answer":3,"explanation":"Matching premium benefits at the price competitors charge for less is 'more for the same'. 'More for less' would need a price below the mid-range level, and 'more for more' charges a premium.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-286","question":"Consider these elements of the business environment for a packaged-foods firm:\nI. A new law on front-of-pack nutrition labels\nII. Its distributors and modern-trade partners\nIII. A rising share of working women in cities\nIV. Its competitors' pricing moves\nWhich are part of the macro-environment rather than the micro-environment?","options":["I and III only","II and IV only","I, III and IV only","I only"],"answer":0,"explanation":"Legal and demographic or social forces (I and III) are macro-environment factors affecting all firms. Intermediaries and competitors (II and IV) are actors close to the firm, so they belong to the micro-environment.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-287","question":"The GE–McKinsey nine-cell matrix evaluates each business unit on which two dimensions?","options":["Market growth rate and relative market share","Industry attractiveness and business-unit strength (competitive position)","Product and market newness","Price and quality"],"answer":1,"explanation":"GE–McKinsey uses composite measures of industry attractiveness and business strength, each built from several factors. Market growth and relative share are the BCG matrix's two single measures.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-288","question":"In the Indian paint industry, a few national brands compete on wide distribution, heavy advertising and broad product ranges, while many regional firms compete mainly on price in a few states. The national brands form a:","options":["Market segment","Value network","Strategic group","Buying centre"],"answer":2,"explanation":"A strategic group is a set of firms in an industry following similar strategies in a target market. Rivalry is most intense within a group, and mobility barriers separate groups.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-289","question":"Why do market leaders usually gain the most when the total size of their category expands, for example through new users or new uses?","options":["Because new users always prefer challengers","Because the leader captures the largest share of any growth in category sales","Because category growth reduces the leader's costs to zero","Because category growth always lowers prices"],"answer":1,"explanation":"With the highest share, the leader gets the biggest absolute slice of any increase in category demand, so expanding the total market is a classic leader strategy.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-290","question":"Holistic marketing has four broad components. A company that tracks marketing's financial returns and also weighs the legal, ethical and environmental effects of its campaigns is practising which component?","options":["Relationship marketing","Integrated marketing","Internal marketing","Performance marketing"],"answer":3,"explanation":"In Kotler's holistic marketing, performance marketing covers both financial accountability and social responsibility. Internal marketing is about getting employees to embrace marketing principles.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-291","question":"Match each of Kotler's leader defence strategies with its description.\nA. Pre-emptive defence  B. Mobile defence  C. Contraction defence  D. Counteroffensive\n1. Withdrawing from weaker markets to concentrate on stronger ones\n2. Attacking the competitor before it can attack\n3. Broadening or diversifying into new territories to secure future positions\n4. Hitting back at the attacker's own core market after being attacked","options":["A-2, B-3, C-1, D-4","A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Pre-emptive defence strikes first; mobile defence extends into new markets; contraction (strategic withdrawal) gives up weak territories; a counteroffensive responds by attacking the challenger where it is vulnerable.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-292","question":"A small brand of orthopaedic footwear serves only people with diabetes-related foot problems and sells mainly through doctors' recommendations. Which competitive role and specialisation does it represent?","options":["Market challenger; product-feature specialist","Market follower; geographic specialist","Market nicher; end-use (customer-type) specialist","Market leader; full-line specialist"],"answer":2,"explanation":"A nicher serves a small, well-defined segment that bigger firms neglect. Specialising in one type of end user is one of Kotler's niche roles.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-293","question":"Assertion (A): A guerrilla attack is usually chosen by a smaller, less-funded challenger.\nReason (R): Guerrilla attacks rely on small, intermittent moves such as selective price cuts and intense local promotions that harass the leader without a costly full-scale battle.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Guerrilla warfare suits weaker challengers because it avoids head-on confrontation, using cheap, scattered attacks to demoralise the leader and gain small footholds.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-294","question":"A market-leading tea brand faces a frontal attack from a well-funded entrant matching its price, quality and advertising. As a rule of thumb from military-style marketing, how much greater resource does a frontal attacker usually need for success?","options":["About equal resources suffice","A clear resource advantage, often cited as around three to one","Fewer resources, if the attacker is more agile","Resources do not matter in a frontal attack"],"answer":1,"explanation":"In a pure frontal attack the side with greater resources tends to win, and a large advantage, often quoted as three to one, is suggested against a well-entrenched leader. That is why most challengers prefer flank or bypass attacks.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-295","question":"A consulting team compares five competing brands on 'price', 'perceived quality' and 'distribution reach' and notices that three of them cluster closely on all three. Which conclusion is most appropriate?","options":["The clustered brands face the most intense rivalry with one another and may need to differentiate","The clustered brands face no competition","The other two brands must exit the market","Clustering means all five brands are in the same strategic group"],"answer":0,"explanation":"Firms with similar strategies compete most directly, so a tight cluster signals intense head-to-head rivalry and a need to differentiate. The two outliers form different groups.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-296","question":"Which of these would most likely LOWER the threat of new entrants into a packaged-water market?","options":["Low capital needed to set up a bottling plant","Weak brand loyalty among consumers","Easy access to retail shelves","Strong economies of scale and established brands that control most distribution"],"answer":3,"explanation":"Scale economies, brand loyalty and control of distribution channels are entry barriers. The other three make entry easier.","difficulty":"moderate","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-297","question":"Consider these statements about competitive moves:\nI. A market leader often benefits from 'new uses' campaigns more than a small challenger does.\nII. Flank attacks usually require more resources than frontal attacks.\nIII. Market followers often earn reasonable profits by avoiding the cost of pioneering.\nWhich are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":1,"explanation":"Leaders capture most of any category expansion, and followers save the cost of developing and educating the market. Flank attacks usually need fewer resources than frontal ones, so II is false.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-298","question":"An FMCG firm maps its value chain. Into which primary activity do warehousing finished goods, managing the distributor network's order processing and scheduling delivery vans to retailers fall?","options":["Inbound logistics","Operations","Marketing and sales","Outbound logistics"],"answer":3,"explanation":"Outbound logistics covers storing finished goods and getting them to buyers: warehousing, order processing and delivery. Inbound logistics handles incoming raw materials; marketing and sales covers activities that persuade buyers to purchase.","difficulty":"moderate","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-299","question":"An industrial-lubricants firm segments business customers by first looking at industry and company size, then at the technology they use, then at how they buy (centralised or decentralised purchasing), then at urgency of orders, and finally at the risk attitudes of individual buyers. Which approach is this?","options":["The VALS framework","Benefit segmentation","Bonoma and Shapiro's nested approach","Geodemographic clustering"],"answer":2,"explanation":"Bonoma and Shapiro's nested approach moves from broad demographics to operating variables, purchasing approaches, situational factors and finally personal characteristics of buyers.","difficulty":"very-hard","source":"FMCG MT · Sales MT · MBA placement"},
  {"id":"mgmt-marketing-300","question":"A toothpaste maker finds that one group of buyers mainly wants decay prevention, another wants whiter teeth, a third wants fresh breath and a fourth looks for the lowest price, and it designs a variant for each. Which segmentation basis is it using?","options":["Demographic","Benefit","Psychographic","Geographic"],"answer":1,"explanation":"Grouping buyers by the main benefit they seek from the product is benefit segmentation, a behavioural basis. The groups are defined by what they want, not by who they are.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-301","question":"Segment A has 10 lakh units of annual demand; the firm expects a 10% share at ₹20 contribution per unit, and serving it needs ₹5 lakh of fixed marketing cost. Segment B has 4 lakh units; the firm expects 15% share at ₹60 contribution, with ₹20 lakh of fixed cost. Which segment yields more profit, and by how much?","options":["Segment A, by ₹1 lakh","Segment B, by ₹16 lakh","Segment A, by ₹16 lakh","Segment B, by ₹1 lakh"],"answer":3,"explanation":"A: 1 lakh units × ₹20 = ₹20 lakh − ₹5 lakh = ₹15 lakh. B: 60,000 × ₹60 = ₹36 lakh − ₹20 lakh = ₹16 lakh. B wins by ₹1 lakh; ignoring fixed costs exaggerates the gap to ₹16 lakh.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-302","question":"A premium cookware brand has successfully launched an affordable range, but mass-market buyers still believe all its products are too expensive for them. Which positioning error is this?","options":["Overpositioning","Underpositioning","Confused positioning","Doubtful positioning"],"answer":0,"explanation":"Overpositioning gives buyers too narrow an image of the brand, so they overlook offerings that would suit them. Underpositioning leaves buyers with only a vague idea of the brand.","difficulty":"very-hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-303","question":"A new juice brand runs generic 'tasty and healthy' ads. Research shows consumers have only a vague idea of what it stands for and do not see anything special about it. Which positioning error is this?","options":["Overpositioning","Confused positioning","Underpositioning","Doubtful positioning"],"answer":2,"explanation":"Underpositioning means buyers have only a vague idea of the brand and see nothing distinctive. Confused positioning comes from too many or frequently changing claims.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-304","question":"A new bottled cold coffee positions itself as 'the energy kick of an energy drink, without the chemicals'. What has the brand chosen as its competitive frame of reference?","options":["Hot coffee brands only","Energy drinks","Bottled water","Fruit juices"],"answer":1,"explanation":"The frame of reference tells consumers which category and competitors to compare the brand with. By borrowing energy drinks' benefit and claiming an advantage over them, the brand puts itself against energy drinks.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-305","question":"In laddering interviews, a consumer says she buys a particular shampoo because it has natural ingredients, which means it is gentle on her hair, which makes her feel she is taking good care of herself, which matters because she values self-respect. What does this chain illustrate?","options":["A perceptual map","A conjoint utility","A buying centre","A means–end chain linking attributes to benefits to personal values"],"answer":3,"explanation":"Laddering uncovers means–end chains: concrete attributes lead to functional and emotional benefits, which link to deeper values. Positioning can then be built at the level that matters most.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-306","question":"A microscope maker sells its microscopes to universities, government labs and corporate R&D centres; another firm sells microscopes, oscilloscopes and chemical reagents only to university labs. In Abell's patterns of target market selection, these are respectively:","options":["Market specialisation and product specialisation","Product specialisation and market specialisation","Selective specialisation and full market coverage","Single-segment concentration and selective specialisation"],"answer":1,"explanation":"Product specialisation sells one product to several segments; market specialisation sells many products to one customer group. Selective specialisation serves several unrelated attractive segments.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-307","question":"A small-car brand advertises itself as 'the first car for young professionals' and shows recent graduates in all its ads. Which positioning approach is this?","options":["Positioning by user","Positioning by competitor","Positioning by price–quality","Positioning by product class"],"answer":0,"explanation":"Associating the brand with a particular type of user is positioning by user. Positioning by competitor would compare it explicitly with a rival.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-308","question":"Keller describes a brand mantra as a short three-to-five-word phrase capturing the brand's essence. Which three components does he say it usually combines?","options":["Price, product and place","Awareness, image and loyalty","Emotional modifier, descriptive modifier and brand function","Target, frame of reference and point of difference"],"answer":2,"explanation":"Keller's mantra structure is emotional modifier + descriptive modifier + brand function, as in 'authentic athletic performance'. Target, frame and POD are elements of a positioning statement.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-309","question":"A new detergent's main point of difference is its very low price, but consumers tend to infer that a very cheap detergent must clean poorly. According to Keller, what must the brand do?","options":["Raise its price to the category average","Establish a point of parity on cleaning performance to counter the negative inference","Drop the low-price claim entirely","Advertise only on price"],"answer":1,"explanation":"Low price and quality are negatively correlated in consumers' minds, so a correlational point of parity on cleaning is needed to make the low-price POD credible. This is the classic 'straddling negatively correlated attributes' problem.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-310","question":"Category buyers fall into two groups: 20% are heavy users who buy 10 packs a year and 80% are light users who buy 2 packs a year. What share of category volume do the heavy users account for?","options":["20%","50%","About 55.6%","About 83.3%"],"answer":2,"explanation":"Heavy-user volume = 20 × 10 = 200; light-user volume = 80 × 2 = 160; share = 200 / 360 ≈ 55.6%. Comparing per-person purchases (10 vs 2) gives 83.3%, which ignores how many people are in each group.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-311","question":"A footwear brand lets customers design their own sneakers online, choosing colours, materials and initials, and then produces each pair to order at near mass-production cost. This is:","options":["Mass customisation","Undifferentiated marketing","Concentrated marketing","Benefit segmentation"],"answer":0,"explanation":"Mass customisation prepares individually designed products on a mass basis. It is the extreme form of micromarketing at the individual level.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-312","question":"In which situation is undifferentiated (mass) marketing most likely to be appropriate?","options":["A new product category with very different customer needs","A firm with limited resources entering a big market","A product like iodised salt where consumer needs are largely similar and differentiation is hard","A luxury brand serving the very rich"],"answer":2,"explanation":"Undifferentiated marketing suits homogeneous needs and commodity-like products. A resource-poor firm is better off with concentrated marketing; heterogeneous needs call for differentiated marketing.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-313","question":"A bank scores customers 1–5 on Recency, Frequency and Monetary value. Customer P scores R5, F1, M1 (a new customer with one small purchase); Q scores R1, F5, M5 (used to buy often and a lot, but not for a year); S scores R4, F4, M4. Which customer is the best target for a 'win-back' campaign?","options":["P","S","All three equally","Q"],"answer":3,"explanation":"Q was a high-frequency, high-value customer who has gone quiet, the classic win-back target. P is new and needs nurturing; S is active and valuable, so retention or upselling suits S better.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-314","question":"A researcher wants to group 2,000 survey respondents into segments whose members are similar to one another and different from other groups across 15 attitude scores. Which technique is most suitable?","options":["Cluster analysis","Regression analysis","Factor analysis alone","Conjoint analysis"],"answer":0,"explanation":"Cluster analysis groups respondents by similarity. Factor analysis groups variables into underlying dimensions, often as a step before clustering; conjoint estimates part-worths of attributes.","difficulty":"moderate","source":"Consulting · MBA placement"},
  {"id":"mgmt-marketing-315","question":"A snack brand's sales jump during cricket matches, festivals and late-night study sessions, and it designs pack sizes and ads around these moments. Which segmentation basis is it using?","options":["Psychographic","Occasion","Demographic","Usage rate"],"answer":1,"explanation":"Occasion segmentation groups buyers by when they need, buy or use the product. It is a behavioural basis, distinct from lifestyle or demographics.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-316","question":"A brand tries to be seen as both 'the most premium' and 'great value', two attributes consumers often see as opposites. Which strategy does Keller suggest for credibly holding both?","options":["Choosing only one and abandoning the other","Separating the attributes through different marketing campaigns, linking to entities such as a credible endorser, or redefining the relationship so consumers see them as compatible","Cutting price below all rivals","Dropping all communication about quality"],"answer":1,"explanation":"Keller lists separating the attributes, leveraging secondary associations (people, ingredients, endorsers) and reframing the relationship as ways to straddle negatively correlated attributes. Abandoning one is an option, but not the only one.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-317","question":"The VALS framework classifies US consumers along two dimensions. What are they?","options":["Income and age","Usage rate and loyalty status","Geography and family life-cycle stage","Primary motivation (ideals, achievement or self-expression) and resources"],"answer":3,"explanation":"VALS combines primary motivation, whether ideals, achievement or self-expression, with the level of resources (income, education, energy, self-confidence) to form its segments.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-318","question":"A coffee chain changes its store formats, menus and promotions neighbourhood by neighbourhood, based on local customer data. This is an example of:","options":["Undifferentiated marketing","Concentrated marketing","Mass customisation","Local marketing (micromarketing)"],"answer":3,"explanation":"Local marketing tailors offers to the needs of local customer groups, a form of micromarketing. Mass customisation goes further, to the individual.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-319","question":"Consider these statements about segmentation:\nI. Lifestyle (AIO: activities, interests, opinions) is a psychographic basis.\nII. Loyalty status and user status are behavioural bases.\nIII. Income and family life-cycle stage are psychographic bases.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"AIO is psychographic, and loyalty and user status are behavioural. Income and family life-cycle stage are demographic variables, so III is wrong.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-320","question":"A health-drink brand is trying to persuade consumers that it is a 'snack replacement' rather than a 'beverage'. Why might this repositioning be risky, according to positioning theory?","options":["Changing the frame of reference changes the competitors and points of parity it must match, and it may lose its existing category associations","Repositioning never affects sales","Brands cannot change their frame of reference","It will automatically lower the price"],"answer":0,"explanation":"Moving to a new frame of reference means meeting new category points of parity (here, being filling like a snack) while giving up established associations. Done badly, the brand ends up belonging to neither category.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-321","question":"A company's cluster analysis finds a segment that is large and profitable, but the firm has no channel through which it can reach these customers and no media that reliably reach them. Which criterion of effective segmentation does this segment fail?","options":["Measurable","Substantial","Accessible","Differentiable"],"answer":2,"explanation":"A segment must be reachable and serviceable to be useful; size and profitability make it substantial, but without channels or media it is not accessible.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-322","question":"Assertion (A): Two people of the same age, income and city can respond very differently to the same ad.\nReason (R): Psychographic factors such as lifestyle, personality and values vary within demographic groups and shape responses.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Demographics alone often fail to predict behaviour because values and lifestyles differ among demographically identical people, which is why psychographic segmentation exists.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-323","question":"A positioning map of hair-oil brands uses 'price' and 'natural ingredients' as axes and shows an empty quadrant for low-priced, highly natural oils. What is the most appropriate next step before launching into that gap?","options":["Launch immediately, because a gap always means unmet demand","Check that enough consumers actually want that combination and that it is feasible to deliver profitably","Abandon the map, since maps are unreliable","Price the new oil above all competitors"],"answer":1,"explanation":"A gap may be empty because few want that combination or because it cannot be made profitably. Research must confirm a demand in the gap and a viable cost structure before launch.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-324","question":"A brand defines the target segment for its new protein bar as 'urban gym-goers aged 22–35 who track their macros', describes the brand as 'the cleanest protein bar' and cites its six-ingredient recipe as the reason to believe. Which element of a positioning statement is the 'six-ingredient recipe'?","options":["Target market","Frame of reference","Point of difference","Reason to believe (support for the point of difference)"],"answer":3,"explanation":"A full positioning statement names the target, the frame of reference, the point of difference ('cleanest protein bar') and the reason to believe that supports it, here the short ingredient list.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-325","question":"A consumer rates two snack brands using Fishbein's model, attitude = Σ(belief × evaluation). Evaluations: taste +3, value for money +2, high calories −2. Beliefs (1–7): Brand X — taste 6, value 4, high calories 6; Brand Y — taste 4, value 6, high calories 2. Which brand does she prefer, and with what scores?","options":["X, 38 vs 28","Y, 20 vs 14","X, 14 vs 20","They are tied"],"answer":1,"explanation":"X = 6×3 + 4×2 + 6×(−2) = 14; Y = 4×3 + 6×2 + 2×(−2) = 20, so Y wins. Ignoring the negative evaluation of calories gives X 38 vs Y 28, the trap.","difficulty":"very-hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-326","question":"Three laptops are scored 1–10 on battery (weight 0.40), value for money (0.35) and weight/portability (0.25): A — 9, 5, 8; B — 6, 7, 7; C — 9, 6, 3. Which laptop is chosen under a weighted compensatory rule, a lexicographic rule (battery first, then value) and a conjunctive rule requiring at least 6 on every attribute?","options":["A, A, B","B, C, B","A, C, A","A, C, B"],"answer":3,"explanation":"Weighted scores: A 7.35, B 6.6, C 6.45, so A wins. Lexicographic: A and C tie on battery, and C wins on value. Conjunctive: only B clears 6 on everything. The same data give three different choices.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-327","question":"Research shows that shoppers just notice a ₹5 rise on a ₹50 pack of biscuits. If Weber's law holds, roughly what price rise would shoppers just notice on a ₹200 jar of the same brand's cookies?","options":["₹5","₹10","₹20","₹40"],"answer":2,"explanation":"Weber's law: the just noticeable difference is a constant fraction of the base, here 5/50 = 10%. On ₹200 that is ₹20. Assuming a constant rupee amount (₹5) ignores the law.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-328","question":"In the FCB (Foote, Cone and Belding) grid, products such as jewellery, perfume and fashion apparel fall in the high-involvement, 'feeling' quadrant. Which response sequence does the grid suggest for them?","options":["Learn → feel → do","Feel → learn → do","Do → learn → feel","Do → feel → learn"],"answer":1,"explanation":"For high-involvement feeling products, emotions come first, then information, then purchase (feel–learn–do). High-involvement thinking products, like cars, follow learn–feel–do.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-329","question":"A shopper hesitates to buy a bold new jacket because she worries her friends will laugh at it. Which type of perceived risk is she facing?","options":["Social risk","Functional risk","Financial risk","Physical risk"],"answer":0,"explanation":"Social risk is the fear that a purchase will lead to embarrassment or disapproval from others. Functional risk is about the product not performing as expected.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-330","question":"A low-involvement chewing-gum brand uses a popular film star, catchy music and bright colours in a 15-second ad with almost no product information. According to the elaboration likelihood model, which route to persuasion is it relying on?","options":["The central route, because consumers will think carefully about the arguments","The peripheral route, because low involvement means people respond to cues like celebrities and music","Both routes equally","Neither route; it relies on price"],"answer":1,"explanation":"When motivation or ability to process is low, persuasion works through peripheral cues such as source attractiveness and music. Strong arguments matter more on the central route, for high-involvement decisions.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-331","question":"A software firm finds that users who have had its premium features free for 30 days are much more willing to pay for them than users who were only shown a demo. Which behavioural effect most directly explains this?","options":["Anchoring","Choice overload","Endowment effect","Halo effect"],"answer":2,"explanation":"The endowment effect makes people value things more once they own or use them, so giving up the features feels like a loss. Free trials exploit this along with loss aversion.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-332","question":"A coffee shop sells a small cup at ₹120 and a large at ₹220, and most buyers choose small. It then adds a medium at ₹170, and medium becomes the best seller, while small sales drop sharply. Which effect best explains this, as distinct from the decoy effect?","options":["Asymmetric dominance (decoy) effect","Endowment effect","Anchoring on the MRP","Compromise effect"],"answer":3,"explanation":"The new option sits between the extremes, and buyers drift to the middle to avoid the extremes: the compromise effect. A decoy works by being clearly dominated by the target option, which is not the case here.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-333","question":"A supermarket finds that a tasting stand with 24 jam flavours attracts more visitors than one with 6 flavours, but far fewer visitors actually buy. Which phenomenon does this illustrate?","options":["Choice overload","Variety-seeking","Selective attention","The bandwagon effect"],"answer":0,"explanation":"Too many options can attract attention but make choice harder, leading to fewer purchases. Variety-seeking describes switching among brands over time, not paralysis at the shelf.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-334","question":"In rural villages, a new seed variety is adopted widely only after a few respected progressive farmers try it and talk about it at the panchayat and the local mandi. Which communication model does this reflect?","options":["The hypodermic-needle model","The two-step flow of communication through opinion leaders","The AIDA model","Classical conditioning"],"answer":1,"explanation":"In the two-step flow, mass media and marketers influence opinion leaders, who in turn influence others by word of mouth. Rural marketers often target such influencers deliberately.","difficulty":"hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-335","question":"A teenager suggests the family buy a new tablet, her uncle recommends a brand, the father decides, the mother pays for it at the store, and the younger brother uses it most. In the buying-roles framework, the mother is the:","options":["Influencer","Decider","Buyer","Initiator"],"answer":2,"explanation":"The buyer makes the actual purchase. The teenager is the initiator, the uncle the influencer, the father the decider and the brother the user.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-336","question":"A store-brand detergent uses packaging colours, shape and graphics very similar to the leading brand's, hoping shoppers will associate it with the leader's quality. Which learning principle is the store brand relying on?","options":["Stimulus discrimination","Extinction","Shaping","Stimulus generalisation"],"answer":3,"explanation":"Stimulus generalisation means responding to a similar stimulus as one did to the original. The leader, in contrast, wants consumers to practise stimulus discrimination and tell its brand apart.","difficulty":"very-hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-337","question":"Using the multi-attribute model, a brand finds consumers rate it well on taste and value but think 'naturalness', on which it scores poorly, is the most important attribute. Instead of changing the product, it runs ads arguing that taste matters more than naturalness for a snack. Which attitude-change strategy is this?","options":["Changing beliefs about its own brand","Adding a new attribute","Changing the importance (evaluation) of attributes","Changing beliefs about competitors"],"answer":2,"explanation":"Shifting how much consumers weigh each attribute changes the evaluation terms in the model. Changing beliefs would mean convincing them the brand is in fact natural.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-338","question":"A consumer knows ten brands of shampoo. She would consider buying four of them, actively dislikes three and is indifferent to the remaining three. In consumer-behaviour terms, the three disliked brands form her:","options":["Inept set","Inert set","Evoked set","Choice set"],"answer":0,"explanation":"The evoked (consideration) set holds brands she would consider; the inept set holds brands she rejects; the inert set holds brands she is indifferent to.","difficulty":"very-hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-339","question":"A packaging-machine maker's customers each keep 100 machines and replace 10 a year. If demand for the customers' packaged goods rises 10% and they want 10% more machines, what happens to orders for new machines that year?","options":["They rise 10%","They rise 100%","They rise 20%","They stay the same"],"answer":1,"explanation":"Customers need 110 machines, so they buy 10 replacements plus 10 additions = 20 machines, double the usual 10. This acceleration effect of derived demand makes B2B capital-goods demand volatile.","difficulty":"very-hard","source":"Sales MT · Consulting"},
  {"id":"mgmt-marketing-340","question":"Arrange these stages of Robinson's buygrid model of organisational buying in order.\nP. Product specification  Q. Supplier search  R. Problem recognition  S. Order-routine specification","options":["R, Q, P, S","P, R, Q, S","R, P, Q, S","R, P, S, Q"],"answer":2,"explanation":"The buygrid runs: problem recognition, general need description, product specification, supplier search, proposal solicitation, supplier selection, order-routine specification and performance review.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-341","question":"A hospital has bought syringes from one supplier for years, but now wants a safety-engineered design and is also asking two other suppliers for quotes. Which buying situation is this?","options":["Straight rebuy","New task","Systems buying","Modified rebuy"],"answer":3,"explanation":"A modified rebuy changes the specifications, prices or suppliers of a familiar purchase. A new task is a first-time purchase; a straight rebuy reorders routinely.","difficulty":"moderate","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-342","question":"A customer expected a hotel to be 'average' and found it 'good'; another expected 'excellent' and found it 'good'. According to the expectation–disconfirmation model, which is most likely?","options":["Both are equally satisfied, since both found it good","The second is more satisfied, because her expectations were higher","The first is more satisfied, because performance exceeded her expectations","Neither is satisfied"],"answer":2,"explanation":"Satisfaction depends on performance relative to expectations: positive disconfirmation pleases, negative disconfirmation disappoints. That is why over-promising can hurt satisfaction.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-343","question":"A shopping app finds that offering a free item worth ₹50 with an order attracts far more takers than a ₹50 discount on the same order, though the economic value is equal. Which effect best explains this?","options":["Zero-price effect","Weber's law","Selective retention","Cognitive dissonance"],"answer":0,"explanation":"The zero-price effect describes how 'free' triggers a disproportionately positive response compared with an equivalent price cut, because it removes any perceived downside.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-344","question":"A home-loan company sends new borrowers a welcome kit that reassures them they got the best rate in the market and lists the benefits they will enjoy. What is this mainly meant to reduce?","options":["Perceived social risk","Post-purchase cognitive dissonance","Stimulus generalisation","Choice overload"],"answer":1,"explanation":"After a big, high-involvement purchase, buyers may doubt their choice. Reassurance and benefit reminders reduce post-purchase dissonance and the risk of cancellation or bad word of mouth.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-345","question":"Consider these statements about culture and consumer behaviour:\nI. Subcultures such as regional or religious groups can need distinct products and messages.\nII. Social class is determined only by income.\nIII. Culture is the most fundamental determinant of a person's wants and behaviour.\nWhich are correct?","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":2,"explanation":"Subcultures matter for product and message design, and Kotler calls culture the most fundamental determinant of wants. Social class reflects occupation, education, wealth and values, not income alone.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-346","question":"A utility tells customers either 'Pay by the due date and save ₹100' or 'Pay late and you will lose ₹100 as a penalty'. Research suggests the second message produces more on-time payment. Which principle explains this?","options":["Loss aversion","The zero-price effect","Stimulus generalisation","The compromise effect"],"answer":0,"explanation":"Prospect theory says losses loom larger than equivalent gains, so framing an outcome as a loss motivates more strongly than framing it as a saving.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-347","question":"Assertion (A): For low-involvement grocery items, repeated advertising can build sales even if consumers form little attitude about the brand before buying.\nReason (R): In low-involvement learning, brand familiarity from passive exposure can lead directly to trial, with attitudes forming after purchase.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Krugman's low-involvement hierarchy runs learn (passively) → do → feel: familiarity drives trial, and attitudes follow experience. That is why reach and frequency matter so much for FMCG.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-348","question":"A retailer tracks the share of shoppers whose last three purchases in a category were all the same brand (hard-core loyals), split between two brands, shifting from one favourite to another, or with no pattern. This classification is based on:","options":["Benefit segmentation","Usage rate","Readiness stage","Loyalty status"],"answer":3,"explanation":"Kotler's loyalty-status groups are hard-core loyals, split loyals, shifting loyals and switchers, a behavioural segmentation basis.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-349","question":"A consumer buys a costly air purifier after weeks of research. A month later she sees an ad for a rival model with better features at the same price. Which of these marketer actions is MOST likely to reduce her dissonance?","options":["Sending her an email comparing her model's strengths, plus tips to get the most from it","Cutting the price for new buyers and publicising it","Sending her the rival's brochure","Withdrawing the model from the market"],"answer":0,"explanation":"Post-purchase communication that reinforces the choice and helps her use the product well reduces dissonance. A price cut for others or rival information would deepen her regret.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-350","question":"Researchers show two groups of homemakers identical shopping lists that differ only in one item, instant coffee versus ground coffee, and ask them to describe the person who wrote each list. Which research approach is this, and why is it used?","options":["A Likert scale, to measure attitude strength","A conjoint study, to estimate part-worths","A focus group, to observe group dynamics","A projective technique, to uncover motives people may not state directly"],"answer":3,"explanation":"Asking people to describe a third person lets them project their own feelings, revealing hidden motives (such as guilt about convenience) that direct questions miss. This is the classic shopping-list projective study.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-351","question":"A hotel guest takes for granted a clean bed, fresh towels, working lights and a quiet room; she is not impressed by them, but would be very unhappy if any were missing. In Kotler's five product levels, these make up the:","options":["Core benefit","Basic product","Expected product","Augmented product"],"answer":2,"explanation":"The expected product is the set of attributes buyers normally expect when they buy the product. The augmented product goes beyond expectations, and the core benefit is the underlying need (rest and sleep).","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-352","question":"Shoppers rush to buy umbrellas at a station kiosk when it suddenly starts raining, paying well above the usual price. Within convenience goods, umbrellas bought this way are:","options":["Staple goods","Impulse goods","Shopping goods","Emergency goods"],"answer":3,"explanation":"Emergency goods are bought when a need is urgent, so availability matters more than price. Impulse goods are bought without planning because they catch the eye.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-353","question":"Arrange these stages of new-product development in the usual order.\nP. Business analysis  Q. Concept development and testing  R. Idea screening  S. Test marketing  T. Product development","options":["R, Q, P, T, S","Q, R, P, T, S","R, P, Q, T, S","R, Q, T, P, S"],"answer":0,"explanation":"After idea generation, firms screen ideas, develop and test concepts, design the marketing strategy, do business analysis, develop the product, test-market it and then commercialise it.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-354","question":"At the screening stage, a company drops an idea for a low-sugar ready-to-drink tea that a rival later turns into a hit; it also approves an idea for a gourmet frozen meal that later flops. These two mistakes are respectively:","options":["A go-error and a drop-error","A drop-error and a go-error","Both drop-errors","Both go-errors"],"answer":1,"explanation":"A drop-error dismisses a good idea; a go-error lets a poor idea move forward into development and commercialisation. Screening tries to minimise both.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-355","question":"A new appliance has a market potential of 10 lakh households, a coefficient of innovation (p) of 0.03 and a coefficient of imitation (q) of 0.4. Using the Bass diffusion model, how many households adopt in the second year?","options":["30,000","42,000","40,740","12,000"],"answer":2,"explanation":"Year 1 adopters = p × m = 30,000. Year 2 = [p + q × (30,000 / 10,00,000)] × (10,00,000 − 30,000) = 0.042 × 9,70,000 = 40,740. Applying 0.042 to the full 10 lakh (42,000) forgets that earlier adopters leave the pool.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-356","question":"For a Bass diffusion model with p = 0.03 and q = 0.4, the time to peak adoption is ln(q/p) / (p + q). Roughly when do yearly sales peak?","options":["After about 2.6 years","After about 13 years","After about 1 year","After about 6 years"],"answer":3,"explanation":"ln(0.4 / 0.03) = ln 13.33 ≈ 2.59, and dividing by 0.43 gives about 6.0 years. Stopping at ln(q/p) gives 2.6, forgetting the division.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-357","question":"A new cooking sauce targets 1 crore households. 20% are expected to try it once in the first year; 40% of triers become repeat buyers, purchasing 6 more packs during the year. How many packs will it sell in year one?","options":["20 lakh","48 lakh","1.4 crore","68 lakh"],"answer":3,"explanation":"Trial packs = 20 lakh; repeaters = 40% × 20 lakh = 8 lakh, buying 6 each = 48 lakh. Total = 68 lakh. Ignoring trial volume gives 48 lakh.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-358","question":"A frozen ready-meal sells slowly in India even though it saves time and tastes good, because many households believe meals must be freshly cooked each day. Which of Rogers' innovation characteristics is the main barrier?","options":["Relative advantage","Compatibility","Observability","Trialability"],"answer":1,"explanation":"Compatibility is how well an innovation fits existing values and practices. Here the product clashes with cultural norms about fresh food, despite its clear relative advantage.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-359","question":"In a Kano survey, hotel guests say free Wi-Fi gives them no particular delight when present, but its absence makes them very dissatisfied. Wi-Fi is therefore a:","options":["Performance (one-dimensional) attribute","Attractive attribute (delighter)","Indifferent attribute","Must-be (basic) attribute"],"answer":3,"explanation":"Must-be attributes are taken for granted: presence does not raise satisfaction much, but absence causes strong dissatisfaction. Many former delighters, like Wi-Fi, drift into this category over time.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-360","question":"A car maker finds that buyers were thrilled when automatic climate control first appeared in mid-size cars, but five years later they simply expect it and complain only if it is missing. In the Kano model, the feature has moved from:","options":["Must-be to attractive","Attractive to must-be","Performance to indifferent","Indifferent to attractive"],"answer":1,"explanation":"Kano attributes decay over time: delighters become performance attributes and then must-be features as competitors copy them and expectations rise.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-361","question":"A shampoo brand with variants priced at ₹100, ₹200 and ₹400 adds a ₹150 and a ₹300 variant to plug gaps in its current price range. This is:","options":["Line filling","Upward stretching","Downward stretching","Line pruning"],"answer":0,"explanation":"Line filling adds items within the present range of the line. Stretching extends the line above or below its current range; pruning removes items.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-362","question":"An instrument maker learns that a few research labs have already modified its products themselves to handle new kinds of tests, months before the general market asks for them. It works closely with these labs to design its next model. Which concept does this use?","options":["Opinion leaders","Early majority","Lead users","Laggards"],"answer":2,"explanation":"Von Hippel's lead users face needs ahead of the market and often innovate on their own; firms can co-develop with them to anticipate mainstream needs. Opinion leaders influence others but need not innovate.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-363","question":"In a concept test, 30% of respondents say they 'definitely will buy' and 40% say they 'probably will buy'. The firm's norms convert these at 75% and 25% respectively. With 60% awareness and 70% distribution expected in year one, what trial rate should it forecast?","options":["About 32.5%","About 29.4%","About 13.7%","70%"],"answer":2,"explanation":"Adjusted intention = 0.30 × 0.75 + 0.40 × 0.25 = 32.5%; × 0.60 awareness × 0.70 distribution = 13.65%. Taking the raw top-two-box (70%) or skipping awareness and distribution grossly overstates trial.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-364","question":"A company's product Z has sales of ₹50 lakh, variable costs of ₹40 lakh and ₹15 lakh of allocated fixed overheads that will not go away if Z is dropped. The accounts show Z 'losing ₹5 lakh'. What happens to company profit if Z is dropped?","options":["It rises by ₹5 lakh","It falls by ₹10 lakh","It is unchanged","It rises by ₹15 lakh"],"answer":1,"explanation":"Z contributes 50 − 40 = ₹10 lakh towards fixed costs that stay anyway. Dropping it loses this contribution, so profit falls by ₹10 lakh. The 'loss' is an artefact of allocating unavoidable overheads.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-365","question":"Buyers of a particular fountain-pen brand travel to a specific store, refuse substitutes and are willing to wait weeks for stock. For these buyers, the pen is a:","options":["Convenience good","Shopping good","Unsought good","Specialty good"],"answer":3,"explanation":"Specialty goods have unique characteristics or brand identity for which buyers make a special effort and accept no substitutes. Shopping goods are compared on price and quality across stores.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-366","question":"A snack company tests a new chip in a panel of stores where a research firm controls shelf placement, pricing and promotions and tracks sales through scanners. Which type of test market is this?","options":["Standard test market","Controlled test market","Simulated test market","Concept test"],"answer":1,"explanation":"In a controlled test market, a research firm manages distribution and in-store conditions in a set of panel stores. A standard test market uses the firm's own full launch in selected cities; a simulated test market uses a laboratory store setting.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-367","question":"A company's new-product process divides development into stages, each followed by a review point where a cross-functional team decides go, kill, hold or recycle based on set criteria. This is:","options":["The Stage-Gate process","The buygrid model","Concept testing","The diffusion of innovation"],"answer":0,"explanation":"Cooper's Stage-Gate system separates development into stages with decision 'gates' that screen out weak projects early and focus resources on promising ones.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-368","question":"Consider these statements about first-mover (pioneer) advantage:\nI. Pioneers can gain brand recognition and set the category's standard.\nII. Pioneers always outperform later entrants.\nIII. Fast followers can learn from the pioneer's mistakes and enter with an improved product.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I and III only"],"answer":3,"explanation":"Pioneers may gain awareness and set standards, but many pioneers fail and fast followers often win by improving on them, so II is false.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-369","question":"A nylon-type material's sales keep rising in waves: each time growth slows, a new use is found (first stockings, then carpets, then tyre cord), giving a new burst of growth. What life-cycle pattern is this?","options":["Fad","Growth–slump–maturity","Scalloped (successive new uses)","Cycle–recycle"],"answer":2,"explanation":"A scalloped pattern shows repeated growth spurts driven by the discovery of new product characteristics, uses or users. A cycle–recycle pattern comes from a second promotional push rather than new uses.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-370","question":"A pharmaceutical brand loses patent protection and its sales decline. Generic makers enter at much lower prices. Which response best fits a 'harvest' decision in the decline stage?","options":["Raise advertising to win back share","Cut marketing support to the minimum and maximise short-term cash flow while loyal buyers remain","Launch the brand in five new countries","Cut price below generics"],"answer":1,"explanation":"Harvesting reduces investment to the minimum and milks the brand's remaining loyalty for cash. Heavy spending or price wars contradict a harvest strategy.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-371","question":"A smartphone maker deliberately launches a new model every year with minor changes and stops software updates for models over four years old. Which practice is this?","options":["Planned obsolescence","Line pruning","Product augmentation","Mass customisation"],"answer":0,"explanation":"Planned obsolescence deliberately limits a product's useful life, through design, style or support, to encourage replacement purchases. It raises ethical and sustainability concerns.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-372","question":"Assertion (A): A product's life cycle curve is a poor tool for forecasting exactly when a product will move from growth to maturity.\nReason (R): The shape and length of each stage vary widely across products and are partly shaped by the firm's own marketing decisions.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"PLC curves differ greatly and marketing actions can extend or shorten stages, so the concept is more useful for thinking about strategy than for predicting timing.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-373","question":"A pump maker sells a ₹50,000 pump; a rival's pump costs ₹42,000 but uses ₹6,000 more electricity a year. Over a five-year life, what is the first pump's advantage in total cost of ownership, ignoring discounting?","options":["₹22,000 cheaper","₹8,000 more expensive","₹30,000 cheaper","₹2,000 cheaper"],"answer":0,"explanation":"Rival's extra running cost = 5 × 6,000 = ₹30,000, against an ₹8,000 higher purchase price, so the first pump saves ₹22,000 over five years. Comparing only purchase price makes it look ₹8,000 dearer.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-374","question":"A biscuit brand replaces its 15 slow-moving variants with five stronger ones, freeing shelf space and cutting production changeover costs. Which product-line decision is this?","options":["Line filling","Line pruning","Line stretching","Line modernisation"],"answer":1,"explanation":"Line pruning removes weak or low-margin items to focus resources on stronger ones. Modernisation updates the look or technology of existing items.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-375","question":"A premium coffee-machine brand launches a cheaper, simpler model under the same brand to reach first-time buyers, while also launching a commercial-grade model for cafés. This is:","options":["Line filling","Upward stretching only","Two-way stretching","Line pruning"],"answer":2,"explanation":"Extending the line both below and above its current range is two-way stretching. It can capture new segments but risks blurring the brand's position.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-376","question":"Match each of Rogers' innovation characteristics with the marketing action that addresses it.\nA. Trialability  B. Observability  C. Complexity  D. Relative advantage\n1. Running a cost-savings calculator on the website\n2. Offering free samples or a 14-day trial\n3. Encouraging users to share visible results on social media\n4. Providing simple set-up videos and installation support","options":["A-2, B-3, C-4, D-1","A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1","A-1, B-3, C-4, D-2"],"answer":0,"explanation":"Trials address trialability, visible results address observability, easy set-up addresses complexity, and a savings calculator demonstrates relative advantage.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-377","question":"David Aaker grouped the assets that make up brand equity into a few main dimensions. Which set matches his model?","options":["Brand loyalty, brand awareness, perceived quality, brand associations and other proprietary assets","Salience, performance, imagery, judgements, feelings and resonance","Differentiation, relevance, esteem and knowledge","Product, price, place and promotion"],"answer":0,"explanation":"Aaker's model lists loyalty, awareness, perceived quality, associations and proprietary assets such as patents and trademarks. Salience to resonance is Keller's pyramid; differentiation to knowledge is the Brand Asset Valuator.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-378","question":"Arrange the levels of Keller's customer-based brand equity pyramid from the base upwards.\nP. Judgements and feelings  Q. Salience  R. Resonance  S. Performance and imagery","options":["Q, P, S, R","S, Q, P, R","Q, S, P, R","Q, S, R, P"],"answer":2,"explanation":"Keller's pyramid starts with salience (identity), then performance and imagery (meaning), then judgements and feelings (response), and ends with resonance (relationship).","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-379","question":"Keller lists six criteria for choosing brand elements such as names, logos and jingles. Which three are 'defensive', helping to maintain and protect brand equity rather than build it?","options":["Memorable, meaningful and likeable","Memorable, transferable and protectable","Likeable, adaptable and meaningful","Transferable, adaptable and protectable"],"answer":3,"explanation":"Memorability, meaningfulness and likeability build equity; transferability across categories and markets, adaptability over time and legal and competitive protectability defend it.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-380","question":"A brand of business software is described by users as 'reliable, intelligent and successful'. In Jennifer Aaker's brand-personality framework, which dimension does this reflect?","options":["Sincerity","Excitement","Competence","Sophistication"],"answer":2,"explanation":"Aaker's competence dimension includes reliable, intelligent and successful. Sincerity covers down-to-earth, honest and cheerful; excitement covers daring and imaginative.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-381","question":"In a survey, 35% of respondents name a juice brand when asked 'Which juice brands can you think of?', and 80% say they know it when shown its logo. What do these two figures measure?","options":["Unaided recall (35%) and aided recognition (80%)","Aided recall (35%) and unaided recognition (80%)","Brand loyalty (35%) and awareness (80%)","Top-of-mind awareness for both"],"answer":0,"explanation":"Naming a brand without prompts is unaided recall; identifying it from a cue such as a logo is aided recognition. Top-of-mind is only the first brand named.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-382","question":"A brand earns revenue of ₹200 crore a year. Comparable brands are licensed at a 5% royalty on revenue, the tax rate is 25%, and the appropriate discount rate for a no-growth perpetuity is 12.5%. Using the relief-from-royalty method, what is the brand worth?","options":["₹80 crore","₹60 crore","₹10 crore","₹75 crore"],"answer":1,"explanation":"Royalty saved = 5% × 200 = ₹10 crore; after tax = ₹7.5 crore; value = 7.5 / 0.125 = ₹60 crore. Skipping tax gives ₹80 crore.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-383","question":"A branded atta sells 1 lakh packs a month at ₹60. In the same stores, the retailer's private-label atta sells 80,000 packs at ₹45. Using the revenue-premium measure of brand equity, what is the brand's monthly revenue premium?","options":["₹15 lakh","₹12 lakh","₹24 lakh","₹30 lakh"],"answer":2,"explanation":"Revenue premium = branded revenue − private-label revenue = 60 lakh − 36 lakh = ₹24 lakh. The ₹15 price gap times 1 lakh (₹15 lakh) ignores the volume difference.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-384","question":"A hotel group launches a new mid-priced chain as 'Harbour Inn — by Grandview Hotels', with the parent name in small print beneath the new name. Which branding strategy is this?","options":["Branded house","Endorsed brand","House of brands","Private label"],"answer":1,"explanation":"An endorsed brand stands as a brand in its own right, with the parent's name lending credibility in a secondary role. In a branded house the parent name dominates; in a house of brands the parent is hidden.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-385","question":"Keller says a brand audit has two parts. Which pair is correct?","options":["A brand inventory, profiling how the brand is marketed, and brand exploratory research into what consumers think and feel about it","A financial audit and a legal audit","A competitor inventory and a pricing study","A brand tracking study and a sales forecast"],"answer":0,"explanation":"The brand inventory catalogues all brand elements and marketing activities; brand exploratory research uncovers consumers' perceptions and associations. Together they reveal gaps between intended and actual meaning.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-386","question":"In the Young & Rubicam Brand Asset Valuator, which combination is used to measure a brand's 'strength', an indicator of future growth potential?","options":["Esteem × knowledge","Awareness × loyalty","Differentiation × relevance","Price × quality"],"answer":2,"explanation":"Brand strength (energised differentiation × relevance) points to future growth; brand stature (esteem × knowledge) reflects current status. A brand high in stature but low in strength may be fading.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-387","question":"Aaker's brand loyalty pyramid runs from the least to the most loyal customers. Which customer sits at the top?","options":["The habitual buyer who sees no reason to switch","The satisfied buyer who faces switching costs","The price-sensitive switcher","The committed buyer who is proud to use the brand and recommends it"],"answer":3,"explanation":"From the base: switchers, habitual buyers, satisfied buyers with switching costs, buyers who like the brand (friends of the brand), and at the top committed customers.","difficulty":"very-hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-388","question":"A cutlery brand prominently uses the phrase 'Made in Solingen, Germany' on every pack and in all ads. Which way of leveraging secondary associations is it using?","options":["Celebrity endorsement","Country (place) of origin","Co-branding","Event sponsorship"],"answer":1,"explanation":"Linking the brand to a place known for quality craftsmanship transfers that place's associations to the brand. Co-branding would combine two brands in one offer.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-389","question":"A brand name becomes so dominant that people use it for the whole product category, as happened historically with 'thermos' and 'escalator'. What is the main risk for the brand owner?","options":["Its trademark may lose legal protection because the name becomes generic","Its market share will fall immediately","Its price premium will rise too much","It will be forced to extend into new categories"],"answer":0,"explanation":"If a mark becomes the generic name for the category, courts may decide it no longer identifies one source, and protection can be lost. Owners fight this by insisting on 'Brand X vacuum flask' style usage.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-390","question":"A company wants its watch brand to stand for 'precision engineering'. Consumer research shows people see it mainly as 'a gift for retirement'. Which statement is correct?","options":["The brand image and brand identity are aligned","Brand image is what the company intends, so research is irrelevant","The brand has no equity at all","Brand identity (what the company intends) and brand image (what consumers perceive) are out of line, so communication or the offer must change"],"answer":3,"explanation":"Brand identity is the sender's intended meaning; brand image is the receiver's perception. A gap signals that positioning, communication or the product itself needs work.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-391","question":"A cola leader launches a cheaper secondary brand to compete directly with low-priced regional colas, so its flagship brand does not have to cut price. This secondary brand is a:","options":["Co-brand","Ingredient brand","Cash-cow brand","Flanker (fighter) brand"],"answer":3,"explanation":"Flanker or fighter brands protect the flagship by taking on lower-priced rivals without damaging its pricing or image. A cash cow is a BCG matrix category, not a branding role.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-392","question":"A bank and an airline jointly issue a credit card that carries both their names and gives airline miles on spending. This is an example of:","options":["Ingredient branding","Brand licensing","Co-branding","Private labelling"],"answer":2,"explanation":"Co-branding combines two established brands in one offering, each lending its associations. Ingredient branding highlights a component inside another firm's product.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-393","question":"A cartoon character's owner lets a school-bag maker use the character on bags in return for 6% of the maker's sales. If the bag maker sells ₹40 crore of such bags, how much does the owner earn, and what is this arrangement called?","options":["₹2.4 crore; co-branding","₹6 crore; franchising","₹2.4 crore; brand licensing","₹4 crore; ingredient branding"],"answer":2,"explanation":"6% × ₹40 crore = ₹2.4 crore. Renting a brand or character to another firm for a royalty is licensing; the licensee makes and sells the products.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-394","question":"Keller's brand hierarchy for a car such as 'Maruti Suzuki Swift VXi' would classify 'Maruti Suzuki', 'Swift' and 'VXi' respectively as:","options":["Individual brand, family brand, modifier","Corporate brand, family brand, individual brand","Family brand, modifier, individual brand","Corporate (or company) brand, individual brand, modifier"],"answer":3,"explanation":"The company name is the corporate brand, the model name is the individual brand, and the trim designation is a modifier showing a specific version. A family brand would span several categories.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-395","question":"Which statement best captures Keller's definition of customer-based brand equity?","options":["The price at which the brand could be sold","The differential effect that brand knowledge has on consumer response to the marketing of that brand","The total amount spent on advertising the brand","The number of products carrying the brand name"],"answer":1,"explanation":"Keller defines CBBE as how consumers respond differently to a brand's marketing because of what they know about it. A positive CBBE means they react more favourably than to an unnamed version.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-396","question":"A retailer's store-brand range includes basic 'value' packs in plain packaging, products that closely imitate leading brands' looks at lower prices, and a premium line that competes on quality with top national brands. These represent, respectively:","options":["Copycat, generic and premium store brands","Generic, copycat and premium store brands","Premium, copycat and generic store brands","National, regional and local brands"],"answer":1,"explanation":"Generics are low-priced, minimal-branding packs; copycats imitate leading brands; premium store brands compete on quality and can carry strong margins and loyalty.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-397","question":"A sports-drink brand signs a famous wicket-keeper known for fitness to endorse it, while a luxury watch signs the same cricketer. Research finds the endorsement works far better for the sports drink. Which idea explains this?","options":["The match-up hypothesis: endorsement works best when the celebrity's image fits the product","The two-step flow of communication","The zero-price effect","The mere-exposure effect alone"],"answer":0,"explanation":"Celebrity effectiveness depends on fit between the endorser's image and the product's key attributes; a fitness icon fits a sports drink better than a luxury watch. Expertise and trust are higher where the fit is obvious.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-398","question":"A heritage biscuit brand's sales have fallen for years because younger buyers see it as old-fashioned, though older consumers still trust it. Keller would call the needed strategy:","options":["Brand reinforcement","Brand revitalisation, refreshing old sources of equity or creating new ones","Brand pruning","Brand licensing"],"answer":1,"explanation":"Revitalisation restores lost equity, often by expanding awareness, improving image and finding new uses or users. Reinforcement maintains equity that is still strong.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-399","question":"A company owns many separate brands of detergent, each targeting a different segment. Which is a typical drawback of this multi-brand strategy?","options":["It always lowers total shelf space","It prevents segment targeting","It makes the corporate name more prominent","Each brand may get only a small market share and limited marketing support, and the brands may cannibalise each other"],"answer":3,"explanation":"Multi-branding captures more segments and shelf space but spreads resources thinly, and brands may take sales from each other rather than rivals.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-400","question":"Consider these statements about brand extensions:\nI. Category extensions use an existing brand name in a new product category.\nII. A failed extension can never affect the parent brand.\nIII. Extensions can lower the cost of introducing a new product by using existing awareness.\nWhich are correct?","options":["I, II and III","II and III only","I only","I and III only"],"answer":3,"explanation":"Category extensions enter new categories and benefit from existing awareness and trust, cutting launch costs. Failed extensions can dilute or damage the parent brand, so II is false.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-401","question":"Assertion (A): A strong brand can command a price premium and still hold share in a price war better than an unbranded rival.\nReason (R): Brand equity lowers consumers' price sensitivity because brand knowledge adds perceived value beyond the physical product.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Brand equity makes demand less price-elastic, letting the brand charge more and lose fewer customers when rivals cut prices. R gives the mechanism for A.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-402","question":"A brand's tracking study shows awareness at 90% and consideration at 25%, while its main rival has 70% awareness and 40% consideration. What does this most likely indicate?","options":["The brand needs more awareness advertising","The brand's problem lies in its image or associations: people know it but don't see it as a good choice","The rival is spending more on media","Consideration does not depend on brand associations"],"answer":1,"explanation":"Converting only 28% of aware consumers into considerers (vs 57% for the rival) points to weak or negative associations, not low salience. More reach would mostly reach people who already know the brand.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-403","question":"A spice brand's licensed recipes and its patented packaging technology protect it from imitation. In Aaker's brand-equity model, these belong to which category?","options":["Perceived quality","Brand associations","Other proprietary brand assets","Brand awareness"],"answer":2,"explanation":"Aaker's fifth category, other proprietary assets, covers patents, trademarks and channel relationships that protect the brand from competitors.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-404","question":"A water-purifier maker has fixed costs of ₹12 lakh, a selling price of ₹400 and a variable cost of ₹250 per unit. It wants a profit of ₹6 lakh after a 25% tax. How many units must it sell?","options":["12,000","13,334","16,000","8,000"],"answer":1,"explanation":"Pre-tax profit needed = 6 / 0.75 = ₹8 lakh, so units = (12 + 8) lakh / ₹150 = 13,333.3, rounded up to 13,334. Forgetting to gross up for tax gives 12,000; 8,000 is the plain break-even.","difficulty":"very-hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-405","question":"A brand sells 20,000 units a month and its break-even volume is 15,000 units. What are its margin of safety and its degree of operating leverage (DOL)?","options":["25% and 4","33% and 3","25% and 1.33","75% and 4"],"answer":0,"explanation":"Margin of safety = (20,000 − 15,000) / 20,000 = 25%, and DOL = 1 / margin of safety = 4: a 10% fall in sales would cut operating profit by 40%. Dividing the gap by break-even volume gives 33%.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-406","question":"A firm's cost for a contract is ₹9 lakh. It estimates the probability of winning at a bid of ₹9.5 lakh as 0.8, at ₹10.5 lakh as 0.5 and at ₹11.5 lakh as 0.2. Which bid maximises expected profit?","options":["₹9.5 lakh","₹11.5 lakh","₹10.5 lakh","All give the same expected profit"],"answer":2,"explanation":"Expected profits: 0.5 × 0.8 = ₹0.4 lakh; 1.5 × 0.5 = ₹0.75 lakh; 2.5 × 0.2 = ₹0.5 lakh. The middle bid wins; the highest bid has the biggest margin but too low a chance of winning.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-407","question":"When a rival cuts its price by 5%, a brand's unit sales fall by 8%. What is the cross-price elasticity, and what does it say about the two products?","options":["−1.6; they are complements","+1.6; they are substitutes","+0.625; they are weak substitutes","−0.625; they are complements"],"answer":1,"explanation":"Cross elasticity = % change in own quantity / % change in rival's price = (−8%) / (−5%) = +1.6. A positive value means substitutes, and above 1 means fairly close ones.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-408","question":"Software is sold to 200 students who value it at ₹300 each and 300 professionals who value it at ₹600 each. The marginal cost is ₹100 a copy. Compared with the best single price, how much more profit does charging each group its own valuation earn?","options":["₹90,000","₹1,50,000","₹50,000","₹40,000"],"answer":3,"explanation":"At ₹300, all 500 buy: profit 500 × 200 = ₹1,00,000. At ₹600, only professionals buy: 300 × 500 = ₹1,50,000, the best single price. Segmented: 200 × 200 + 300 × 500 = ₹1,90,000, a gain of ₹40,000.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-409","question":"Three customers value two apps (A, B) as follows: C1 — ₹90, ₹20; C2 — ₹70, ₹70; C3 — ₹20, ₹90. Each app costs ₹30 per user to serve. Which pricing strategy earns the most profit?","options":["Separate pricing at ₹70 each, earning ₹160","Pure bundle at ₹110, earning ₹150","Mixed bundling (A at ₹90, B at ₹90, bundle at ₹140), earning ₹200","Pure bundle at ₹140, earning ₹80"],"answer":2,"explanation":"Separately, ₹70 each sells to two buyers per app: 4 × 40 = ₹160. A ₹110 bundle sells to all three: 3 × 50 = ₹150. Mixed bundling sells A to C1 (60), B to C3 (60) and the bundle to C2 (80) = ₹200, because it avoids selling to low-value customers at a loss.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-410","question":"A cement maker charges distant customers the same delivered price as nearby customers would pay from a competitor's closer plant, absorbing part of the freight itself to win business in those markets. This is:","options":["FOB-origin pricing","Uniform delivered pricing","Zone pricing","Freight-absorption pricing"],"answer":3,"explanation":"Freight-absorption pricing absorbs all or part of the freight to match competitors' delivered prices in contested areas. FOB-origin charges each buyer the actual freight from the plant.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-411","question":"A distributor offers terms of '2/10, net 30': a 2% discount if paid within 10 days, otherwise full payment in 30 days. A retailer who skips the discount and pays on day 30 is effectively borrowing at roughly what annual rate?","options":["About 37%","2%","24%","About 12%"],"answer":0,"explanation":"Skipping the discount means paying ₹100 instead of ₹98 for 20 extra days: 2/98 × 365/20 ≈ 37% a year. Treating 2% as the annual cost badly underestimates it.","difficulty":"very-hard","source":"Sales MT · Consulting"},
  {"id":"mgmt-marketing-412","question":"A home-appliance store gives ₹3,000 off a new washing machine to customers who hand in their old machine. This is a:","options":["Functional (trade) discount","Trade-in allowance","Seasonal discount","Quantity discount"],"answer":1,"explanation":"A trade-in allowance reduces the price in return for turning in an old item. Functional discounts go to channel members for performing channel functions.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-413","question":"A new battery's unit cost is ₹500 when cumulative output is 1,000 units, and it follows an 80% experience curve (unit cost falls to 80% each time cumulative output doubles). What will the unit cost be at 8,000 units, and why does this support penetration pricing?","options":["₹100; low prices are needed to cover costs","₹400; costs fall slowly","₹256; low prices that build volume fast drive costs down quickly","₹320; costs fall in proportion to output"],"answer":2,"explanation":"8,000 units is three doublings from 1,000: 500 × 0.8³ = ₹256. A firm that builds volume fastest moves down the curve first, so penetration pricing can lock in a cost advantage.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-414","question":"A rival's industrial filter costs ₹1,000. A new filter saves the customer ₹400 in running costs and adds features worth ₹200 to the customer over its life, but switching to it involves ₹100 of retraining. What is the new filter's economic value to the customer (EVC)?","options":["₹1,600","₹1,500","₹1,400","₹1,700"],"answer":1,"explanation":"EVC = reference price + positive differentiation − negative differentiation = 1,000 + 400 + 200 − 100 = ₹1,500. Pricing below this gives the buyer a reason to switch; ignoring the switching cost gives ₹1,600.","difficulty":"very-hard","source":"Sales MT · Consulting"},
  {"id":"mgmt-marketing-415","question":"A product's price elasticity of demand is −1.5. If the price is cut by 5%, roughly what happens to sales revenue?","options":["It rises by about 2.1%","It falls by about 2.5%","It rises by 7.5%","It is unchanged"],"answer":0,"explanation":"Quantity rises about 7.5%, so revenue changes by (0.95 × 1.075) − 1 ≈ +2.1%. Because demand is elastic (|e| > 1), a price cut raises revenue, though by far less than the volume gain.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-416","question":"A fashion retailer plans operating expenses of 30% of net sales, a profit of 8% of net sales, and reductions (markdowns, shrinkage and employee discounts) of 12% of net sales. What initial markup on the original retail price should it set?","options":["38%","50%","About 44.6%","About 42.9%"],"answer":2,"explanation":"Initial markup = (expenses + profit + reductions) / (net sales + reductions) = (30 + 8 + 12) / (100 + 12) ≈ 44.6%. Simply adding the percentages gives 50%, which ignores that reductions inflate the original retail base.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-417","question":"A refinery sells heavy residues that were once treated as waste to road builders at a low price, which lowers the effective cost of its main products and lets it price them more competitively. This is:","options":["Captive-product pricing","Optional-product pricing","Product-bundle pricing","By-product pricing"],"answer":3,"explanation":"By-product pricing finds a market for leftovers from making the main product, so their revenue helps make the main product's price more competitive.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-418","question":"A dominant firm with 70% market share sells a product below its own average variable cost for a long period, apparently to drive a new entrant out of the market. Under India's competition law, how would this most likely be viewed?","options":["As a normal penetration strategy, always permitted","As predatory pricing, which can be an abuse of dominant position","As price discrimination, which is always legal","As resale price maintenance"],"answer":1,"explanation":"The Competition Act, 2002 treats predatory pricing by a dominant enterprise, selling below cost to reduce competition or eliminate competitors, as an abuse of dominance. A small firm's penetration pricing is different.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-419","question":"A supermarket sells sugar below its own cost at the store entrance, expecting shoppers who come in for cheap sugar to buy other, higher-margin items. Sugar here is a:","options":["Prestige-priced product","Captive product","Loss leader","Price-lined product"],"answer":2,"explanation":"A loss leader is priced at or below cost to draw traffic, with profits coming from other purchases on the same trip.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-420","question":"A researcher asks consumers four price questions about a new gadget: at what price would it be so cheap that you would doubt its quality, at what price a bargain, at what price getting expensive, and at what price too expensive to consider. Which method is this?","options":["Gabor–Granger method","Conjoint analysis","Van Westendorp price sensitivity meter","Target-return pricing"],"answer":2,"explanation":"Van Westendorp's price sensitivity meter uses these four questions to find an acceptable price range. Gabor–Granger asks whether people would buy at a series of specified prices.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-421","question":"Consider these statements about price–quality inferences:\nI. Buyers rely more on price as a quality cue when they cannot judge quality themselves.\nII. A large price cut on a premium brand can lower its perceived quality.\nIII. Consumers never use price to judge quality.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"When quality is hard to judge, as with wine or cosmetics, price becomes a signal, and steep discounts can cheapen a premium image. III contradicts this well-documented behaviour.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-422","question":"A product's income elasticity of demand is +2.2. What kind of good is it, and how should its sales respond to a recession that cuts incomes by 5%?","options":["A necessity; sales fall about 2.2%","An inferior good; sales rise about 11%","A luxury; sales fall about 11%","A luxury; sales fall about 2.2%"],"answer":2,"explanation":"Income elasticity above 1 marks a luxury, whose demand moves more than proportionally with income: 2.2 × 5% ≈ 11% fall. Necessities have income elasticity between 0 and 1.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-423","question":"A distributor buys a pack at ₹80 and sells it to retailers at ₹90; the retailer sells it to consumers at an MRP of ₹120. The manufacturer considers raising the MRP to ₹130 while keeping both channel members' percentage margins on their selling prices unchanged. What will the distributor's new buying price be?","options":["₹86.67","₹88","₹90","About ₹97.50"],"answer":0,"explanation":"Retailer margin = 30/120 = 25%; distributor margin = 10/90 ≈ 11.1%. New retailer buying price = 130 × 0.75 = ₹97.50; distributor's buying price = 97.50 × (1 − 1/9) = ₹86.67.","difficulty":"very-hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-424","question":"A company's demand for a gadget is Q = 10,000 − 50P, and the variable cost is ₹40 per unit with no fixed costs. What price maximises profit?","options":["₹100","₹120","₹80","₹140"],"answer":1,"explanation":"Profit = (P − 40)(10,000 − 50P). Setting the derivative to zero: 10,000 − 100P + 2,000 = 0, so P = ₹120 and Q = 4,000. ₹100 maximises revenue, not profit.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-425","question":"A mobile operator charges a ₹199 monthly rental that includes 2 GB of data, plus ₹50 for every extra GB. Which pricing structure is this?","options":["Pure bundling","Penetration pricing","Cost-plus pricing","Two-part tariff"],"answer":3,"explanation":"A two-part tariff combines a fixed fee with a usage charge. It captures value from heavy users while keeping a low entry price for light users.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-426","question":"Assertion (A): Raising price on a product with inelastic demand at its current price always increases profit, other things being equal.\nReason (R): With inelastic demand, a price rise increases revenue while the lower volume also reduces total variable cost.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"When |e| < 1, revenue rises with price, and selling fewer units also cuts variable costs, so profit must rise. That is why a profit-maximising firm never prices in the inelastic part of its demand curve.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-427","question":"A luxury-car maker offers its base model at an attractive price but charges heavily for sunroofs, premium audio and alloy wheels, which most buyers end up adding. This is:","options":["Captive-product pricing","Optional-product pricing","By-product pricing","Segmented pricing"],"answer":1,"explanation":"Optional-product pricing sets prices for accessories offered with the main product. Captive-product pricing applies to items that must be used with the main product, like printer ink.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-428","question":"A snack maker sells 50,000 packs a week at ₹20, with a variable cost of ₹12. A rival cuts its price, and the maker estimates it will lose 20% of volume if it holds price, or keep its volume if it matches with a ₹2 cut. Which choice gives more weekly contribution, and by how much?","options":["Matching, by ₹20,000","Holding price, by ₹60,000","Both give the same contribution","Holding price, by ₹20,000"],"answer":3,"explanation":"Hold: 40,000 × ₹8 = ₹3,20,000. Match: 50,000 × ₹6 = ₹3,00,000. Holding price earns ₹20,000 more a week, because the ₹2 cut slashes unit contribution by 25% while holding loses only 20% of volume.","difficulty":"hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-429","question":"A paint company sets prices for 'economy', 'standard' and 'premium' ranges at ₹200, ₹350 and ₹600 a litre, so buyers can easily compare levels without studying every shade. This is:","options":["Psychological odd pricing","Geographical pricing","Two-part pricing","Price lining (product-line pricing)"],"answer":3,"explanation":"Price lining sets a few clear price points for different quality levels within a line, simplifying choice. The gaps between price points should reflect perceived quality differences.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-430","question":"A region has 10,000 outlets selling a category worth ₹50 crore a year. A shampoo brand is stocked in 2,500 of them, and those outlets together account for ₹30 crore of category sales. What are the brand's numeric and weighted distribution, and what do they suggest?","options":["ND 25%, WD 60%: the brand is present mainly in the larger outlets","ND 60%, WD 25%: the brand is present mainly in small outlets","ND 25%, WD 25%: coverage is evenly spread","ND 30%, WD 60%: the brand has high value share"],"answer":0,"explanation":"Numeric distribution = 2,500 / 10,000 = 25% of outlets; weighted distribution = 30 / 50 = 60% of category sales. WD well above ND means the brand is in the high-throughput stores; the next lever is reach into smaller outlets.","difficulty":"very-hard","source":"FMCG MT · Sales MT · MBA placement"},
  {"id":"mgmt-marketing-431","question":"Five manufacturers each sell directly to the same 20 retailers. If all trade instead goes through a single wholesaler, how many contacts are saved?","options":["80","75","25","95"],"answer":1,"explanation":"Direct: 5 × 20 = 100 contacts. Through one wholesaler: 5 + 20 = 25 contacts. The saving of 75 contacts shows how intermediaries improve contactual efficiency.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-432","question":"A dominant FMCG company does not own its retailers or have franchise contracts with them, yet its sheer size lets it dictate display, shelf space and promotion terms to thousands of independent shops. Which type of vertical marketing system is this?","options":["Corporate VMS","Contractual VMS","Administered VMS","Horizontal marketing system"],"answer":2,"explanation":"An administered VMS coordinates the channel through the size and power of one member rather than ownership or contract. Corporate VMS rests on ownership; contractual VMS on legal agreements such as franchises.","difficulty":"very-hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-433","question":"A group of independent kirana stores jointly sets up and owns a buying organisation to purchase in bulk and run joint promotions. A wholesaler, by contrast, organises another group of independent stores into a chain it sponsors. These are respectively:","options":["A wholesaler-sponsored voluntary chain and a retailer cooperative","A franchise and a corporate chain","A retailer cooperative and a wholesaler-sponsored voluntary chain","Two forms of administered VMS"],"answer":2,"explanation":"Retailers who own their joint buying body form a retailer cooperative; a chain organised by a wholesaler is a voluntary chain. Both are forms of contractual VMS.","difficulty":"very-hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-434","question":"A manufacturer warns a distributor that its distributorship will be terminated unless it stops stocking a competitor's brand. Which channel power base is the manufacturer using?","options":["Reward power","Expert power","Referent power","Coercive power"],"answer":3,"explanation":"Threatening to withdraw resources or end the relationship is coercive power. It can work in the short run but tends to breed resentment and conflict.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-435","question":"Discount retailers often start with bare stores and very low prices, then gradually add services and upgrade their stores, raising costs and prices until new low-cost entrants undercut them. Which concept describes this?","options":["The wheel of retailing","The retail accordion","Scrambled merchandising","The bullwhip effect"],"answer":0,"explanation":"The wheel of retailing describes the cycle of low-cost entry, trading up and vulnerability to new discounters. The retail accordion describes swings between wide-assortment and specialised retailers.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-436","question":"A distributor buys stock worth ₹1 lakh a day at cost. It holds 15 days of inventory and gives retailers 10 days' credit, while the company gives it 7 days' credit. Its annual net profit is ₹9 lakh. What is its return on working capital?","options":["About 28%","36%","50%","About 35%"],"answer":2,"explanation":"Cash-conversion cycle = 15 + 10 − 7 = 18 days, so working capital ≈ 18 × ₹1 lakh = ₹18 lakh and return = 9 / 18 = 50%. Ignoring the company's credit (25 days) gives 36%.","difficulty":"very-hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-437","question":"A beat salesman can visit 40 outlets a day and works 6 days a week. The territory has 2,000 outlets that must each be visited once a week. How many salesmen are needed?","options":["8","9","10","50"],"answer":1,"explanation":"Each salesman covers 40 × 6 = 240 outlets a week, so 2,000 / 240 = 8.33, rounded up to 9. Rounding down leaves about 80 outlets unvisited each week.","difficulty":"hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-438","question":"In a month, a salesman makes 300 retail calls, of which 210 result in an order, and he books 840 product lines in all. What are his strike rate and lines per productive call?","options":["70% and 2.8","30% and 4","84% and 4","70% and 4"],"answer":3,"explanation":"Strike rate = productive calls / total calls = 210 / 300 = 70%; lines per productive call = 840 / 210 = 4. Dividing lines by all calls gives 2.8.","difficulty":"hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-439","question":"A distributor received 200 orders from retailers in a month; 170 were delivered on time, and 150 of those on-time orders were also delivered complete. What is its OTIF (on time, in full) rate?","options":["85%","75%","88%","95%"],"answer":1,"explanation":"OTIF counts only orders that were both on time and complete: 150 / 200 = 75%. 85% measures on-time delivery alone.","difficulty":"hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-440","question":"A distributor's annual demand for a product is 7,200 cases, each order costs ₹250 to place, and holding a case costs ₹40 a year. What is the economic order quantity?","options":["300 cases","600 cases","about 212 cases","424 cases"],"answer":0,"explanation":"EOQ = √(2DS/H) = √(2 × 7,200 × 250 / 40) = √90,000 = 300 cases. Omitting the 2 gives about 212.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-441","question":"A retailer sells 50 units of a product a day, the supplier takes 6 days to deliver, and the retailer keeps 100 units of safety stock. At what stock level should it reorder?","options":["300 units","350 units","400 units","150 units"],"answer":2,"explanation":"Reorder point = demand during lead time + safety stock = 50 × 6 + 100 = 400 units. Leaving out the safety stock gives 300.","difficulty":"moderate","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-442","question":"Small changes in consumer demand for a detergent lead to larger swings in retailers' orders, still larger swings in distributors' orders and huge swings in the factory's production plan. What is this called, and what is a common remedy?","options":["The wheel of retailing; open more stores","The bullwhip effect; share point-of-sale demand data across the chain and reduce order batching","Channel conflict; terminate distributors","Cannibalisation; cut the number of variants"],"answer":1,"explanation":"The bullwhip effect amplifies demand variability upstream because each tier forecasts from orders, batches them and adds buffers. Sharing real sales data and smaller, more frequent orders dampen it.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-443","question":"A shopper researches a laptop online, reads reviews and compares prices on websites, then goes to a physical store to see it and buy it there. This behaviour is called:","options":["Showrooming","Click-and-collect","Drop-shipping","Webrooming"],"answer":3,"explanation":"Webrooming is researching online and buying offline. Showrooming is the reverse: examining products in a store and then buying online, often more cheaply.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-444","question":"A grocery chain unloads trucks from manufacturers at its distribution centre and immediately moves the goods onto outbound trucks to stores, with almost no storage in between. This is:","options":["Drop-shipping","Vendor-managed inventory","Consignment selling","Cross-docking"],"answer":3,"explanation":"Cross-docking transfers incoming goods straight to outbound transport, cutting storage time and inventory costs. Drop-shipping sends goods directly from the supplier to the end customer.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-445","question":"Bucklin's theory of channel structure says channels form to provide service outputs that customers value. Which of these is one of those service outputs?","options":["Brand equity","Advertising reach","Spatial convenience (market decentralisation)","Trade margins"],"answer":2,"explanation":"Service outputs include lot size, waiting or delivery time, spatial convenience, product variety and service backup. Channels that give more of these cost more to run, so they must match what target buyers will pay for.","difficulty":"very-hard","source":"Sales MT · Consulting"},
  {"id":"mgmt-marketing-446","question":"In category management, a supermarket treats rice and atta as categories that define it as the shoppers' main grocery store, gives them broad assortment and sharp prices, and uses them to drive store choice. Which category role is this?","options":["Routine (preferred) category","Convenience category","Seasonal category","Destination category"],"answer":3,"explanation":"A destination category defines the retailer as the primary store for that need, with the best assortment and value. Routine categories meet everyday needs; convenience categories round out the trip.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-447","question":"A premium kitchen-appliance brand chooses about one in five appliance dealers in each city: those with trained staff and good display, rather than every dealer that wants to stock it. This is:","options":["Selective distribution","Intensive distribution","Exclusive distribution","Direct distribution"],"answer":0,"explanation":"Selective distribution uses more than one but fewer than all willing intermediaries, trading some reach for better control and service. Exclusive distribution would use only one dealer per area.","difficulty":"moderate","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-448","question":"Consider these statements about vertical channel conflict:\nI. It occurs between different levels of the same channel, such as manufacturer and distributor.\nII. Some conflict can be constructive if it pushes members to improve.\nIII. Conflict between two retailers of the same brand in one city is vertical conflict.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"Vertical conflict is between levels of a channel; some conflict can drive adaptation. Conflict between two retailers at the same level is horizontal conflict, so III is wrong.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-449","question":"A biscuit company finds that eye-level shelves sell far more than bottom shelves. It agrees with retailers on a diagram specifying the exact position, number of facings and adjacency of each SKU. This diagram is a:","options":["Beat plan","Bill of lading","Perceptual map","Planogram"],"answer":3,"explanation":"A planogram is a visual plan for placing products on shelves to maximise sales and visibility. A beat plan schedules a salesman's outlet visits.","difficulty":"moderate","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-450","question":"A manufacturer sells through distributors but also starts selling the same SKUs directly to large modern-trade chains at prices below what distributors charge them. Which type of channel conflict is this most likely to create, and what is a common fix?","options":["Horizontal conflict; merge the distributors","Multichannel conflict; assign separate SKUs or pack sizes to each channel, or pay distributors a service fee on direct sales in their territory","Vertical conflict; abolish modern trade","No conflict, since modern trade is a different channel"],"answer":1,"explanation":"Selling the same goods through competing routes creates multichannel conflict. Channel-specific SKUs, clear territory rules or compensation for distributors are common remedies.","difficulty":"hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-451","question":"A distributor earns a 5% margin on its selling price and turns its stock 18 times a year (at cost). Roughly what is its gross margin return on inventory investment (GMROI)?","options":["About 0.9","About 0.05","18","About 0.95"],"answer":3,"explanation":"GMROI = gross margin / average inventory at cost. Cost of goods sold = 18 × inventory, and margin is 5/95 of cost, so GMROI = 18 × 5/95 ≈ 0.95. Taking 5% of cost gives 0.9; 18 is the stock turn itself.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-452","question":"An appliance maker asks its dealers to stock all its models, keep a minimum display and attend training; in return it offers margins, co-op advertising funds and exclusive territory rights. Which channel management idea does this reflect?","options":["Pure push strategy without obligations","Channel partnership with agreed rights and responsibilities of each member","Horizontal marketing system","Administered VMS based on coercion"],"answer":1,"explanation":"Good channel management spells out each member's rights and responsibilities: territory, margins and support from the producer; stocking, service and display from dealers.","difficulty":"moderate","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-453","question":"Assertion (A): An FMCG company may deliberately use super-stockists in rural areas even though they add one more margin to the chain.\nReason (R): Small rural distributors and retailers are scattered and buy in small lots, so an extra level can cut the cost of servicing them below what direct supply would cost.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Extra levels add margin but can lower total cost to serve when outlets are dispersed and drops are small, through consolidation of orders and local stocking.","difficulty":"hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-454","question":"In a shopping mall, a large department store and a hypermarket are given big spaces at the two ends at low rents, so that shoppers walking between them pass the smaller shops. These large stores are called:","options":["Category killers","Anchor stores","Flagship franchises","Pop-up stores"],"answer":1,"explanation":"Anchor stores draw footfall to a mall and are often given favourable terms because smaller tenants benefit from the traffic. A category killer is a large specialist in one category.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-455","question":"In channel flows, which flow typically runs from the manufacturer to distributors to retailers as each buys the goods outright, while payment runs in the opposite direction?","options":["Information flow","Promotion flow","Title (ownership) flow","Negotiation flow"],"answer":2,"explanation":"Title passes forward as each member buys the goods; payment flows backwards. Information and negotiation flow both ways.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-456","question":"A company appoints a new distributor in a town where its brand's weighted distribution is high but numeric distribution is low. What should be the distributor's main coverage priority?","options":["Increase visits to the large outlets already stocking the brand","Raise the brand's prices in large outlets","Add the many smaller outlets not yet stocking the brand","Cut the number of SKUs in all outlets"],"answer":2,"explanation":"High WD with low ND means the brand is already in the big stores; growth lies in extending reach into the many small outlets that are missing. Further work on large outlets brings diminishing returns.","difficulty":"hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-457","question":"Arrange the stages of Lavidge and Steiner's hierarchy-of-effects model in order.\nP. Liking  Q. Knowledge  R. Conviction  S. Awareness  T. Preference","options":["S, Q, P, T, R","S, P, Q, T, R","Q, S, P, T, R","S, Q, T, P, R"],"answer":0,"explanation":"The model runs awareness, knowledge, liking, preference, conviction and purchase: cognitive stages first, then affective, then behavioural.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-458","question":"Russell Colley's DAGMAR approach says advertising objectives should be stated as specific, measurable communication tasks. Which sequence of communication stages does DAGMAR use?","options":["Attention, interest, desire, action","Awareness, comprehension, conviction, action","Awareness, knowledge, liking, preference","Exposure, attention, comprehension, retention"],"answer":1,"explanation":"DAGMAR (Defining Advertising Goals for Measured Advertising Results) uses the ACCA stages: awareness, comprehension, conviction and action. AIDA is a different, older model.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-459","question":"Using the objective-and-task method, a brand wants to reach 60% of its 50 lakh target consumers an average of 5 times through digital video at a CPM of ₹150, and also distribute 2 lakh samples at ₹10 each. What budget does this imply?","options":["₹22.5 lakh","₹62.5 lakh","₹42.5 lakh","₹45 lakh"],"answer":2,"explanation":"Impressions = 50 lakh × 0.6 × 5 = 1.5 crore; media cost = 1.5 crore / 1,000 × ₹150 = ₹22.5 lakh. Sampling = 2 lakh × ₹10 = ₹20 lakh. Total = ₹42.5 lakh.","difficulty":"very-hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-460","question":"A brand holds 10% market share, and its advertising accounts for 15% of all category advertising spend. What is its excess share of voice (ESOV), and what does research generally associate with positive ESOV?","options":["−5 points; share tends to fall","+15 points; share stays the same","+5 points; share tends to grow over time","+1.5 points; no link with share"],"answer":2,"explanation":"ESOV = share of voice − share of market = 15 − 10 = +5 points. Studies of many brands find that brands with positive ESOV tend to gain market share over time, while those below their share tend to lose.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-461","question":"After a three-week TV campaign, a tracking study of the target audience shows: 20% saw no ad, 25% saw it 1–2 times, 30% saw it 3–5 times and 25% saw it 6 or more times. If the brand believes at least 3 exposures are needed, what are the campaign's reach and effective reach?","options":["80% and 30%","100% and 55%","75% and 55%","80% and 55%"],"answer":3,"explanation":"Reach counts anyone exposed at least once: 25 + 30 + 25 = 80%. Effective reach at 3+ counts only 30 + 25 = 55%.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-462","question":"A TV spot on Channel P costs ₹2 lakh and delivers 4 rating points in the target audience; a spot on Channel Q costs ₹3 lakh and delivers 5 rating points. Which channel is more cost-efficient on cost per rating point (CPRP)?","options":["P, at ₹50,000 per point vs ₹60,000","Q, at ₹60,000 per point vs ₹50,000","Q, because it delivers more rating points","Both are equally efficient"],"answer":0,"explanation":"CPRP = cost / rating points: P = 2 lakh / 4 = ₹50,000; Q = 3 lakh / 5 = ₹60,000. P is cheaper per point, even though Q delivers more points per spot.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-463","question":"A message from a low-credibility source initially persuades few people, but weeks later its persuasive effect has increased, as people remember the message but forget where it came from. This is called the:","options":["Halo effect","Sleeper effect","Wear-out effect","Vampire effect"],"answer":1,"explanation":"The sleeper effect occurs when the source and message become dissociated in memory, so a discounting cue (low credibility) fades and the message's impact rises over time.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-464","question":"A new brand is selling to a well-educated audience that already holds a favourable view of a rival. According to communication research, which message structure is likely to work better?","options":["A one-sided message stating only the brand's strengths","A message that makes no claims at all","A message that uses extreme fear appeals","A two-sided message that acknowledges a minor weakness and then refutes the rival's advantages"],"answer":3,"explanation":"Two-sided messages are more credible with educated audiences and those initially opposed, and they inoculate against counter-arguments. One-sided messages work better with audiences already favourable and less educated.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-465","question":"A sunscreen brand advertises heavily in summer and holiday seasons, and not at all in winter. Which media-scheduling pattern is this?","options":["Continuity","Pulsing","Flighting","Blitz-only"],"answer":2,"explanation":"Flighting alternates periods of advertising with periods of none. Pulsing keeps a low continuous level with periodic bursts; continuity spreads exposure evenly through the year.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-466","question":"A TV brand offers a ₹500 mail-in rebate on 10,000 sets sold during a promotion. Experience shows only 30% of buyers will claim it. What is the expected cost of the rebate, and why do marketers like rebates?","options":["₹15 lakh; many buyers never claim, so the promotion costs less than its headline value","₹50 lakh; every buyer claims it","₹35 lakh; rebates are always claimed by 70% of buyers","₹15 lakh; rebates lower the list price permanently"],"answer":0,"explanation":"Expected cost = 10,000 × 0.30 × ₹500 = ₹15 lakh. 'Slippage' (buyers who do not claim) makes rebates cheaper than an equal instant discount, while the headline offer still drives sales.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-467","question":"A company's sales are ₹100 crore with a 30% contribution margin, and it spends ₹5 crore on advertising. Its advertising elasticity of sales is 0.1. Should it raise advertising by 20% (₹1 crore), judged on contribution?","options":["Yes, contribution rises by ₹2 crore","Yes, sales rise by 20%","No, extra contribution is only ₹0.6 crore against ₹1 crore of extra spend","No, sales would fall"],"answer":2,"explanation":"A 20% rise in advertising lifts sales by 0.1 × 20% = 2%, or ₹2 crore, which yields only ₹0.6 crore of contribution, less than the ₹1 crore cost. Treating the sales gain as profit is the trap.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-468","question":"The Dorfman–Steiner condition says that, at the profit-maximising level, the ratio of advertising to sales equals the advertising elasticity divided by the absolute price elasticity. If a brand's advertising elasticity is 0.1 and its price elasticity is −2.5, what advertising-to-sales ratio is optimal?","options":["25%","4%","10%","2.5%"],"answer":1,"explanation":"A/S = 0.1 / 2.5 = 0.04, or 4%. Brands with more price-elastic demand should spend a smaller share of sales on advertising.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-469","question":"Arrange the steps of the personal selling process in the usual order.\nP. Handling objections  Q. Pre-approach  R. Prospecting and qualifying  S. Presentation  T. Closing","options":["R, Q, S, P, T","Q, R, S, P, T","R, S, Q, P, T","R, Q, P, S, T"],"answer":0,"explanation":"The classic sequence is prospecting and qualifying, pre-approach, approach, presentation and demonstration, handling objections, closing and follow-up.","difficulty":"moderate","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-470","question":"A brand runs a heavy two-week price promotion. Sales jump during the promotion, but for several weeks afterwards they fall below the normal baseline. What is this pattern called, and what usually causes it?","options":["A wear-out effect, caused by ad fatigue","A post-promotion dip, caused mainly by consumers stockpiling and buying ahead","A halo effect, caused by better brand image","The bullwhip effect, caused by retailers"],"answer":1,"explanation":"Promotions often pull purchases forward; consumers stock up and then buy less until their pantry empties. This dip must be netted off when measuring incremental volume.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-471","question":"In print-ad post-testing, the Starch method reports three scores. Which set is correct?","options":["Recall, recognition and persuasion","Awareness, liking and purchase intention","Noted, associated and read most","Reach, frequency and GRPs"],"answer":2,"explanation":"Starch scores show the share of readers who noted the ad, who associated it with the brand, and who read most of its copy.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-472","question":"Viewers vividly remember a funny celebrity-led ad for a shampoo, but when asked, many cannot name the brand. What is this problem called?","options":["Sleeper effect","Vampire effect, where the celebrity or creative overshadows the brand","Selective retention","Wear-in effect"],"answer":1,"explanation":"The vampire effect describes a celebrity or creative device that draws attention away from the brand. It shows that ad recall without brand linkage does little for sales.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-473","question":"Which of these is generally classed as a 'below-the-line' (BTL) activity?","options":["A national TV campaign","A radio jingle on all major stations","A full-page newspaper ad","In-store sampling and point-of-purchase displays"],"answer":3,"explanation":"Below-the-line activities are targeted and usually non-mass-media, such as sampling, in-store promotions, direct mail and events. Mass-media advertising is above the line.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-474","question":"A brand runs a contest that asks entrants to create a short video about the product, judged by a panel; another brand runs a lucky draw where any purchaser may win a car. Which statement correctly distinguishes the two?","options":["The first is a sweepstake and the second a contest","A contest requires skill or effort that is judged, while a sweepstake or lucky draw selects winners by chance","Both are identical promotional tools","A contest always requires a purchase, while a sweepstake never allows one"],"answer":1,"explanation":"Contests judge entries on skill or creativity; sweepstakes and lucky draws pick winners at random. The distinction matters both for promotional design and for legal compliance.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-475","question":"Herbert Krugman's 'three-hit' theory suggests three exposures to an ad can be enough. What does each exposure do in his view?","options":["First: curiosity ('What is it?'); second: evaluation ('What of it?'); third: reminder","First: purchase; second: trial; third: loyalty","All three serve only as reminders","First: liking; second: knowledge; third: awareness"],"answer":0,"explanation":"Krugman argued the first exposure prompts recognition and curiosity, the second evaluation and personal relevance, and the third acts as a reminder, with later exposures repeating the third.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-476","question":"A brand donates ₹2 to a children's literacy programme for every pack sold during a three-month campaign. This is an example of:","options":["Comparative advertising","Guerrilla marketing","Native advertising","Cause-related marketing"],"answer":3,"explanation":"Cause-related marketing links sales directly to contributions to a social cause. It can build brand image but risks scepticism if seen as exploitative.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-477","question":"Which advertising objective is most suitable for a well-established toothpaste brand in the maturity stage, with high awareness and a loyal user base?","options":["Informative advertising to explain the category","Comparative advertising against a new entrant only","Reminder advertising that keeps the brand top of mind","No advertising at all"],"answer":2,"explanation":"Informative advertising suits the introduction stage, persuasive the growth stage, and reminder advertising the maturity stage, where the task is to sustain salience among existing buyers.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-478","question":"Consider these statements about fear appeals:\nI. A moderate level of fear tends to be more persuasive than very high fear.\nII. A fear appeal works better when it also tells people a clear, doable action that removes the threat.\nIII. The more frightening the message, the more persuasive it always is.\nWhich are correct?","options":["I, II and III","II and III only","I only","I and II only"],"answer":3,"explanation":"Very high fear can make audiences avoid or deny the message; fear works best with moderate intensity and clear efficacy (an action that solves the problem). III contradicts both.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-479","question":"A brand's media plan delivers 360 GRPs in a month with an average frequency of 4.5. What reach does it achieve?","options":["80%","75%","72%","90%"],"answer":0,"explanation":"Reach = GRPs / average frequency = 360 / 4.5 = 80%. Reach can never exceed 100%, while GRPs can.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-480","question":"A shampoo brand's campaign is tested before launch with a panel of target consumers who watch it inside a programme and are later asked what they remember and whether they would buy. Which form of research is this?","options":["Post-testing","Ad pre-testing","Market testing","Brand tracking"],"answer":1,"explanation":"Pre-testing evaluates ads before they run, using recall, persuasion and diagnostic measures. Post-testing measures effects after the campaign airs.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-481","question":"Assertion (A): Heavy, frequent price promotions can weaken a brand's equity over time.\nReason (R): Frequent deals teach consumers to wait for discounts and can lower the brand's reference price and perceived quality.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Repeated deals train deal-buying, lower the price consumers think is 'normal', and can signal lower quality, which erodes the price premium a strong brand commands.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-482","question":"An ad ran 40 times; after it, sales were tracked at 1,000 units a week during the campaign versus 800 before. In a matched control region with no ads, sales rose from 820 to 860 over the same period. What is the estimated weekly sales lift caused by the campaign?","options":["200 units","40 units","160 units","180 units"],"answer":2,"explanation":"Test region rose by 200 units, but the control rose by 40 without ads, so the campaign's effect is 200 − 40 = 160 units a week. Ignoring the control overstates the lift.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-483","question":"A news website publishes a sponsored article about home-loan tips, written in the site's normal editorial style and labelled 'In partnership with XYZ Bank'. This is:","options":["Public relations","Guerrilla marketing","Product placement","Native advertising (branded content)"],"answer":3,"explanation":"Native advertising matches the look and feel of the platform's content while being paid for by an advertiser, and should be labelled as such. Product placement embeds a brand inside entertainment content.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-484","question":"A D2C brand's average order is ₹1,000 at a 50% gross margin, and each order costs ₹100 for shipping and payment fees. What is the minimum ROAS at which its ads break even on contribution?","options":["2.0","2.5","1.67","4.0"],"answer":1,"explanation":"Contribution per order = 500 − 100 = ₹400, so ad spend per order can be at most ₹400 and break-even ROAS = 1,000 / 400 = 2.5. Using gross margin alone gives 2.0, ignoring the per-order costs.","difficulty":"hard","source":"Digital marketing · FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-485","question":"An online store converts 2% of paid visitors into buyers. The average order is ₹2,000 at a 30% margin. What is the highest cost per click it can pay and still break even on the first order?","options":["₹40","₹600","₹12","₹6"],"answer":2,"explanation":"Margin per order = ₹600, so the break-even CPA is ₹600; with a 2% conversion rate each order needs 50 clicks, so max CPC = 600 / 50 = ₹12. Using revenue instead of margin gives ₹40.","difficulty":"hard","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-486","question":"In a simplified search auction, ad rank = bid × quality score, and an advertiser pays (ad rank of the advertiser just below ÷ its own quality score) + ₹0.01 per click. Bids and quality scores are: A — ₹40, QS 5; B — ₹25, QS 10; C — ₹30, QS 6. Who takes the top position, and what does it pay per click?","options":["A, paying ₹36.01","B, paying ₹25","A, paying ₹40","B, paying ₹20.01"],"answer":3,"explanation":"Ad ranks: A 200, B 250, C 180, so B ranks first despite the lowest bid. B pays A's rank divided by its own QS: 200 / 10 + 0.01 = ₹20.01. Quality score lets B win the top slot while paying less.","difficulty":"very-hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-487","question":"A customer sees a display ad, later clicks a search ad and finally clicks an email link before buying for ₹3,000. Under a position-based (U-shaped) attribution model giving 40% to the first touch, 40% to the last and 20% split across the middle, how much credit does the search ad get?","options":["₹600","₹1,000","₹1,200","₹0"],"answer":0,"explanation":"The first (display) and last (email) touches each get 40% = ₹1,200, and the single middle touch (search) gets 20% = ₹600. Linear attribution would give ₹1,000 each.","difficulty":"hard","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-488","question":"In an A/B test, Page A converts 200 of 10,000 visitors (2.0%) and Page B converts 250 of 10,000 (2.5%). Using a two-proportion z-test with the pooled rate, what is the z-statistic, and is B's lift significant at the 5% level (two-tailed)?","options":["About 1.2; not significant","About 2.4; significant","About 0.5; not significant","About 5.0; significant"],"answer":1,"explanation":"Pooled p = 450 / 20,000 = 2.25%; SE = √(0.0225 × 0.9775 × 2 / 10,000) ≈ 0.0021; z = 0.005 / 0.0021 ≈ 2.38, above 1.96, so the difference is significant at 5%.","difficulty":"very-hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-489","question":"A subscription earns ₹300 of margin in its first month, and 10% of remaining subscribers cancel at the end of every month. CAC is ₹900. Counting the expected margin per acquired customer, in which month is the CAC recovered?","options":["Month 3","Month 5","Never","Month 4"],"answer":3,"explanation":"Expected margin: month 1 = 300, month 2 = 270, month 3 = 243, total 813 after three months; month 4 adds 218.7, reaching 1,031.7. Ignoring churn (900 / 300) wrongly gives month 3.","difficulty":"very-hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-490","question":"An email goes to a list of 50,000. 4% bounce, 22% of delivered emails are opened, and 15% of openers click. What are the click-to-open rate (CTOR) and the click-through rate on delivered emails?","options":["15% and about 3.3%","15% and 22%","3.3% and 15%","22% and 3.2%"],"answer":0,"explanation":"Delivered = 48,000; opens = 10,560; clicks = 1,584. CTOR = 1,584 / 10,560 = 15%; CTR on delivered = 1,584 / 48,000 = 3.3%. CTOR judges the content; CTR reflects the whole send.","difficulty":"hard","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-491","question":"A lead-generation campaign pays ₹250 per lead, and 8% of leads become customers. What is the effective customer acquisition cost from this campaign?","options":["₹2,000","₹3,125","₹20","₹270"],"answer":1,"explanation":"Each customer needs 1 / 0.08 = 12.5 leads, so CAC = 12.5 × 250 = ₹3,125. Multiplying 250 by 8 (₹2,000) confuses the conversion rate with its reciprocal.","difficulty":"moderate","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-492","question":"A keyword gets 20,000 searches a month. A brand's organic listing moves from position 5 (5% click-through) to position 2 (15% click-through). Visitors convert at 3%, the average order is ₹1,500 and the margin is 40%. By how much does monthly margin rise?","options":["₹90,000","₹1,08,000","₹36,000","₹54,000"],"answer":2,"explanation":"Extra visits = 20,000 × (15% − 5%) = 2,000; extra orders = 60; extra margin = 60 × 1,500 × 0.4 = ₹36,000. ₹90,000 is the extra revenue.","difficulty":"hard","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-493","question":"A mobile game has 1.2 lakh monthly active users and 30,000 daily active users on an average day. What is its DAU/MAU stickiness ratio, and roughly how many days a month does a typical monthly user play?","options":["4%; about 1 day","40%; about 12 days","25%; about 3 days","25%; about 7–8 days"],"answer":3,"explanation":"Stickiness = 30,000 / 1,20,000 = 25%, which means the average monthly user is active on about 25% of days, roughly 7–8 days in a 30-day month.","difficulty":"hard","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-494","question":"A freemium app earns ₹9 lakh in a month from 3 lakh users, of whom 15,000 pay. What are its ARPU and ARPPU?","options":["₹3 and ₹60","₹60 and ₹3","₹30 and ₹600","₹3 and ₹6"],"answer":0,"explanation":"ARPU = revenue / all users = 9,00,000 / 3,00,000 = ₹3; ARPPU = revenue / paying users = 9,00,000 / 15,000 = ₹60. The gap shows how much depends on a small paying base.","difficulty":"hard","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-495","question":"A brand's total revenue last quarter was ₹12 crore from all channels, and its total marketing spend across all channels was ₹2 crore. Platform-reported ROAS for its ads averaged 8. What is its marketing efficiency ratio (MER), and why do analysts track it alongside ROAS?","options":["8; because it equals ROAS","4; because it measures profit","6; it is a blended measure that is not inflated by platforms' over-attribution","0.17; because it measures cost per sale"],"answer":2,"explanation":"MER = total revenue / total marketing spend = 12 / 2 = 6. Because it uses total figures, it cannot be inflated by several platforms claiming the same sale, which often makes summed platform ROAS look better.","difficulty":"hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-496","question":"A search campaign was eligible to appear on 1,00,000 searches but received 40,000 impressions. Of the 60,000 it missed, 45,000 were lost because of low ad rank and 15,000 because the daily budget ran out. What is its impression share, and which fix matters more?","options":["40%; raising the budget","40%; improving bids or quality score","60%; raising the budget","45%; reducing bids"],"answer":1,"explanation":"Impression share = 40,000 / 1,00,000 = 40%. Most lost share (45%) is due to rank, so better bids or quality score would recover more than a bigger budget (15%).","difficulty":"hard","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-497","question":"Influencer X charges ₹60,000 for a post that reaches 2 lakh people and gets 6,000 engagements. Influencer Y charges ₹40,000 for a post reaching 1 lakh people with 5,000 engagements. Which is cheaper per engagement, and which has the higher engagement rate?","options":["X on both","X is cheaper per engagement; Y has the higher engagement rate","Y on both","Y is cheaper per engagement; X has the higher engagement rate"],"answer":2,"explanation":"Cost per engagement: X = ₹10, Y = ₹8. Engagement rate: X = 3%, Y = 5%. Y wins on both, even though X reaches twice as many people.","difficulty":"hard","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-498","question":"An Instagram post reaches 80,000 people and gets 2,400 likes, 300 comments, 500 shares and 800 saves. Taking engagement rate as all interactions divided by reach, what is it?","options":["3%","5%","4%","3.4%"],"answer":1,"explanation":"Total interactions = 2,400 + 300 + 500 + 800 = 4,000, and 4,000 / 80,000 = 5%. Counting only likes gives 3%, which understates engagement.","difficulty":"moderate","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-499","question":"Consider these statements about measuring digital marketing:\nI. Multi-touch attribution uses user-level journey data, while marketing mix modelling uses aggregate spend and sales data over time.\nII. Marketing mix modelling can include offline media such as TV.\nIII. Last-click attribution tends to under-credit upper-funnel channels like display and video.\nWhich are correct?","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":3,"explanation":"MTA works on individual paths; MMM regresses aggregate sales on spend across all media, including offline. Last-click gives all credit to the final touch, so awareness channels look weaker than they are.","difficulty":"very-hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-500","question":"A SaaS firm's customers each bring ₹2,000 of monthly gross margin. Monthly churn falls from 5% to 4%. Using LTV ≈ monthly margin ÷ churn, by what percentage does LTV rise?","options":["1%","20%","25%","10%"],"answer":2,"explanation":"LTV goes from 2,000 / 0.05 = ₹40,000 to 2,000 / 0.04 = ₹50,000, a 25% rise. A one-point fall in churn looks small but cuts churn by a fifth, which lifts expected lifetime by a quarter.","difficulty":"very-hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-501","question":"A campaign shows ads to a test group and withholds them from a randomly chosen control group of equal size. The test group buys 1,300 units and the control group 1,000. The campaign cost ₹1.5 lakh and each unit earns ₹400 of margin. What is the incremental return on ad spend measured in margin?","options":["0.8, a loss","2.67","3.47","1.0, break-even"],"answer":0,"explanation":"Incremental units = 300, giving 300 × 400 = ₹1.2 lakh of margin against ₹1.5 lakh of spend: 0.8, a loss. Crediting all 1,300 units to the ads gives 3.47.","difficulty":"very-hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-502","question":"A video ad costs ₹1.2 lakh and gets 3 lakh impressions and 60,000 views (counted at 30 seconds). What are the cost per view and the view rate?","options":["₹0.40 and 20%","₹0.40 and 5%","₹2 and 5%","₹2 and 20%"],"answer":3,"explanation":"Cost per view = 1,20,000 / 60,000 = ₹2; view rate = 60,000 / 3,00,000 = 20%. Dividing cost by impressions gives ₹0.40, which is cost per impression.","difficulty":"moderate","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-503","question":"A brand's paid ads report 5,000 conversions. When the brand pauses its branded search ads for two weeks in half the regions, organic clicks absorb about 80% of the lost branded-search conversions. What does this suggest about the branded search ads?","options":["They are fully incremental and should be expanded","They are mostly non-incremental: most of those buyers would have arrived anyway via organic results","They only affect brand awareness","They should replace all organic SEO work"],"answer":1,"explanation":"If 80% of conversions shift to organic when ads pause, only about 20% were truly incremental. Branded search often captures demand that already exists; geo holdouts like this measure it.","difficulty":"hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-504","question":"A product page has 10,000 sessions. Product A's 'add to cart' rate is 8%, 50% of carts reach checkout and 70% of checkouts complete. A redesign raises add-to-cart to 10% without changing the later stages. How many extra orders result?","options":["140","200","56","70"],"answer":3,"explanation":"Orders before = 10,000 × 0.08 × 0.5 × 0.7 = 280; after = 10,000 × 0.10 × 0.5 × 0.7 = 350. The gain is 70 orders, a 25% rise from a 2-point improvement at the top.","difficulty":"moderate","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-505","question":"Assertion (A): Optimising ads purely for the highest click-through rate can reduce campaign profit.\nReason (R): Clickbait creative may attract many low-intent visitors who rarely convert, raising cost per acquisition.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"CTR is an intermediate metric. Creative that attracts curious but unqualified clicks inflates spend per sale, so the right target is cost per acquisition or profit, not clicks.","difficulty":"hard","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-506","question":"A company's net revenue retention is calculated as (starting MRR + expansion − contraction − churned MRR) ÷ starting MRR. A cohort starts at ₹20 lakh of MRR; over the year it adds ₹5 lakh of upgrades, loses ₹1 lakh to downgrades and ₹3 lakh to cancellations. What are its NRR and gross revenue retention (which ignores expansion)?","options":["120% and 85%","105% and 85%","105% and 80%","110% and 80%"],"answer":2,"explanation":"NRR = (20 + 5 − 1 − 3) / 20 = 21 / 20 = 105%. Gross revenue retention ignores expansion: (20 − 1 − 3) / 20 = 80%. NRR above 100% means the cohort grows even as some customers leave.","difficulty":"very-hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-507","question":"A brand's ads drive app installs at ₹80 each. 40% of installers register, and 25% of registered users make a first purchase. What is the cost per first-purchase customer?","options":["₹320","₹200","₹800","₹1,000"],"answer":2,"explanation":"Installs per purchaser = 1 / (0.40 × 0.25) = 10, so cost per purchasing customer = 10 × ₹80 = ₹800. Dividing by only one stage gives ₹200 or ₹320.","difficulty":"moderate","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-508","question":"A retailer's last-click report shows its affiliate coupon sites with a ROAS of 15, far above other channels. Analysis shows most coupon-site visitors already had items in their carts before searching for a code. Which conclusion is most appropriate?","options":["Shift most budget to coupon sites","Coupon sites mostly capture sales at the last step that other channels created, so their incremental value is far lower than ROAS suggests","Coupon sites cause cart abandonment","Last-click attribution under-credits coupon sites"],"answer":1,"explanation":"Visitors who already have a full cart and then hunt for a code would mostly have bought anyway. Last-click over-credits such 'closing' touchpoints, so their true incremental return is much lower.","difficulty":"very-hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-509","question":"A retargeting campaign shows ads only to people who visited the product page in the last 7 days. It reports a 12% conversion rate versus 1% for prospecting ads. What is the main caution in comparing these figures?","options":["Retargeting audiences already show high intent, so part of their conversions would have happened anyway (selection bias)","Prospecting ads are always better","Conversion rates cannot be compared across campaigns","Retargeting always lowers CAC to zero"],"answer":0,"explanation":"Retargeted people were already close to buying, so a high conversion rate partly reflects who they are, not the ad's effect. Holdout tests are needed to measure the true lift.","difficulty":"hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-510","question":"A company forecasts sales of ₹60 crore next year. An average rep sells ₹1.5 crore a year, and it expects 10% sales-force turnover (vacancies that cost lost selling time). Using the breakdown method adjusted for turnover, how many reps should it plan for?","options":["40","44","36","46"],"answer":1,"explanation":"Breakdown method: N = (forecast / sales per rep) × (1 + turnover) = (60 / 1.5) × 1.1 = 44. Ignoring turnover gives 40.","difficulty":"hard","source":"Sales MT · FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-511","question":"A firm estimates total annual contribution (₹ lakh) for different sales-force sizes: 10 reps — 500; 11 reps — 535; 12 reps — 562; 13 reps — 582. Each rep costs ₹25 lakh a year. Using the incremental method, how many reps should it employ?","options":["10","11","13","12"],"answer":3,"explanation":"Marginal contributions are 35 (11th rep), 27 (12th) and 20 (13th). Add reps while the marginal contribution exceeds the ₹25 lakh cost: the 11th and 12th qualify, the 13th does not.","difficulty":"very-hard","source":"Sales MT · Consulting"},
  {"id":"mgmt-marketing-512","question":"A buying-power index weights a territory's share of national income at 0.5, of retail sales at 0.3 and of population at 0.2. A territory has 3% of income, 4% of retail sales and 5% of population. What is its BPI?","options":["3.7%","4.0%","4.3%","12%"],"answer":0,"explanation":"BPI = 0.5 × 3 + 0.3 × 4 + 0.2 × 5 = 1.5 + 1.2 + 1.0 = 3.7%. A simple average of the three shares gives 4.0%.","difficulty":"hard","source":"Sales MT · FMCG MT"},
  {"id":"mgmt-marketing-513","question":"A rep gets a recoverable draw of ₹30,000 a month against a 5% commission on sales. In month 1 she sells ₹4 lakh; in month 2 she sells ₹10 lakh. How much is she paid in month 2?","options":["₹50,000","₹30,000","₹40,000","₹20,000"],"answer":2,"explanation":"Month 1 commission = ₹20,000, so the ₹30,000 draw leaves a ₹10,000 advance to recover. Month 2 commission = ₹50,000, minus the ₹10,000 recovery = ₹40,000, which is above the draw.","difficulty":"very-hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-514","question":"A company forecasts next month's sales with a weighted moving average using weights 0.5, 0.3 and 0.2 on the most recent, second and third most recent months. Sales were 100 (last month), 90 and 80. What is the forecast?","options":["90","95","93","87"],"answer":2,"explanation":"Forecast = 0.5 × 100 + 0.3 × 90 + 0.2 × 80 = 50 + 27 + 16 = 93. Applying the heaviest weight to the oldest month gives 87; a simple average gives 90.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-515","question":"Actual sales over three months were 100, 120 and 80 units; the forecasts were 110, 108 and 88. What are the mean absolute percentage error (MAPE) and the mean error (bias, actual − forecast)?","options":["MAPE 10%; bias −2 units, a slight over-forecast","MAPE 10%; bias +2 units, a slight under-forecast","MAPE 3.3%; bias 0","MAPE 30%; bias −2 units"],"answer":0,"explanation":"Absolute percentage errors are 10%, 10% and 10%, so MAPE = 10%. Errors are −10, +12 and −8, averaging −2: forecasts run slightly high. MAPE measures size of error; bias measures direction.","difficulty":"hard","source":"Sales MT · Consulting"},
  {"id":"mgmt-marketing-516","question":"A brand's quarterly seasonal index for Q4 is 1.6. It forecasts total sales of 1,200 units for next year on a deseasonalised basis. What is the Q4 forecast?","options":["300","400","480","1,920"],"answer":2,"explanation":"Average quarter = 1,200 / 4 = 300 units; Q4 = 300 × 1.6 = 480. Applying the index to the annual total gives 1,920.","difficulty":"very-hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-517","question":"A salesperson asks a plant manager: \"If that packing machine broke down for a week during peak season, what would it mean for your deliveries and penalties?\" In Rackham's SPIN model, this is a:","options":["Situation question","Problem question","Implication question","Need-payoff question"],"answer":2,"explanation":"Implication questions explore the consequences of a problem to raise its perceived seriousness. Need-payoff questions ask about the value of solving it; problem questions uncover difficulties in the first place.","difficulty":"very-hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-518","question":"A buyer objects: \"Your machine is more expensive than the competitor's.\" The rep replies: \"Exactly — and that's because it uses hardened parts that last twice as long, which is why it costs you less over five years.\" Which objection-handling technique is this?","options":["Denial method","Boomerang method","Pass-up method","Questioning method"],"answer":1,"explanation":"The boomerang technique turns the objection into a reason to buy. The compensation method would admit the drawback and offset it with a separate benefit, while denial flatly contradicts the buyer.","difficulty":"very-hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-519","question":"Near the end of a meeting, a rep asks: \"Would you prefer delivery on Monday or Thursday?\" without first asking whether the customer wants to buy. Which closing technique is this?","options":["Alternative-choice close","Summary close","Trial close","Standing-room-only close"],"answer":0,"explanation":"The alternative-choice close offers two options, both implying a purchase. A trial close tests readiness with a question such as 'How does that sound?', while a summary close recaps benefits.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-520","question":"A company sets up a dedicated sales team for large hospitals, another for small clinics and a third for retail pharmacies, each selling the full product range. Which sales-force structure is this?","options":["Territorial","Product","Matrix by product and region","Customer (market)"],"answer":3,"explanation":"Organising reps by type of customer or industry is a customer (market) structure. A product structure assigns reps by product line; a territorial structure by geography.","difficulty":"moderate","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-521","question":"Customer A buys ₹50 lakh a year and Customer B ₹30 lakh, both at a 30% gross margin. Serving A needs 20 sales visits at ₹5,000 each, 40 orders processed at ₹2,000 each and ₹6 lakh of returns handling; B needs 5 visits, 10 orders and no returns. Which customer is more profitable after cost to serve?","options":["A, by about ₹6 lakh","Both are equally profitable","A, by about ₹1.4 lakh","B, by about ₹1.35 lakh"],"answer":3,"explanation":"A: 15 − (1.0 + 0.8 + 6.0) = ₹7.2 lakh. B: 9 − (0.25 + 0.2) = ₹8.55 lakh. B is about ₹1.35 lakh more profitable despite lower sales, which is why customer profitability analysis looks beyond revenue.","difficulty":"very-hard","source":"Sales MT · Consulting"},
  {"id":"mgmt-marketing-522","question":"A rep's combination quota weights volume at 50%, gross margin at 30% and activity (calls) at 20%. She achieves 110% of the volume quota, 90% of the margin quota and 100% of the activity quota. What is her overall quota achievement?","options":["100%","102%","110%","98%"],"answer":1,"explanation":"Weighted achievement = 0.5 × 110 + 0.3 × 90 + 0.2 × 100 = 55 + 27 + 20 = 102%. A simple average of the three gives 100%.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-523","question":"A company is launching a technical medical device with a 9-month sales cycle, where reps must spend a lot of time educating doctors and building relationships before any order. Which compensation plan fits best?","options":["Straight commission","Commission only on the first order","A pure team bonus with no salary","Mainly salary with a modest incentive"],"answer":3,"explanation":"Long cycles, missionary work and non-selling activities make straight commission risky and unfair, so a salary-heavy plan supports the needed behaviour. Straight commission suits short-cycle, transactional selling.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-524","question":"A pharmaceutical representative visits doctors to explain a drug's clinical benefits and leave samples, but never takes orders; the orders are placed by chemists with distributors. This type of salesperson is a:","options":["Order taker","Order getter in the field","Inside salesperson","Missionary salesperson"],"answer":3,"explanation":"Missionary salespeople build goodwill and educate influencers who create demand, without directly taking orders. Order takers handle routine reorders; order getters actively close new sales.","difficulty":"moderate","source":"Sales MT · FMCG MT"},
  {"id":"mgmt-marketing-525","question":"A sales head forecasts next year's sales by asking each rep to estimate sales for their territory, then adjusting the totals for known optimism or pessimism by region. This method is:","options":["Delphi method","Jury of executive opinion","Time-series analysis","Sales-force composite"],"answer":3,"explanation":"The sales-force composite builds the forecast from reps' territory estimates. It uses field knowledge but often needs adjustment for bias, especially when the forecast affects quotas.","difficulty":"moderate","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-526","question":"In the Churchill, Ford and Walker model of salesperson performance, which set lists the main determinants of performance?","options":["Product, price, place and promotion","Aptitude, skill level, motivation, role perceptions, and personal, organisational and environmental factors","Territory size, quota and commission only","Reach, frequency and GRPs"],"answer":1,"explanation":"The model explains performance through aptitude, skills, motivation and role perceptions (accuracy, ambiguity and conflict), together with personal, organisational and environmental variables.","difficulty":"very-hard","source":"Sales MT · Consulting"},
  {"id":"mgmt-marketing-527","question":"A territory's market potential is ₹50 crore, and the company's target share in that territory is 12%. Last year the rep sold ₹5 crore. If quotas are set on potential and target share, what is next year's quota, and what does it imply?","options":["₹5 crore; flat performance expected","₹6 crore; a 20% stretch over last year","₹6.5 crore; a 30% stretch","₹4.4 crore; lower than last year"],"answer":1,"explanation":"Quota = 12% × ₹50 crore = ₹6 crore, which is 20% above last year's ₹5 crore. Setting quotas from potential rather than history can reveal under-penetrated territories.","difficulty":"moderate","source":"Sales MT · FMCG MT"},
  {"id":"mgmt-marketing-528","question":"Consider these statements about sales quotas:\nI. Quotas that are seen as unattainable can lower motivation.\nII. Activity quotas are useful when outcomes take a long time to appear.\nIII. A quota based only on last year's sales plus a fixed percentage automatically reflects each territory's potential.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"Unrealistic quotas demotivate, and activity quotas help guide effort in long sales cycles. Historical-plus quotas ignore differences in untapped potential, so III is false.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-529","question":"A sales manager finds that one rep's calls per day are the highest in the team, but her orders per call and average order size are the lowest. What does this pattern most likely indicate?","options":["She is the most productive rep","Her territory is too small","She is busy but not effective; coaching should focus on call quality and targeting","Her quota is too low"],"answer":2,"explanation":"High input (calls) with poor output ratios (strike rate, order size) points to weak call quality or poor targeting. Evaluation should combine input and output measures.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-530","question":"A sales manager sees that her team's pipeline holds ₹4 crore of opportunities, while the quarterly quota is ₹2 crore and the historical win rate is 30%. What is the pipeline coverage ratio, and is it enough?","options":["2×; enough, since coverage exceeds 1","0.5×; too much","2×; not enough, because at a 30% win rate it is expected to close only ₹1.2 crore","3.3×; more than enough"],"answer":2,"explanation":"Coverage = 4 / 2 = 2×. With a 30% win rate the expected close is ₹1.2 crore, short of ₹2 crore; at that win rate she needs about 3.3× coverage (₹6.7 crore).","difficulty":"very-hard","source":"Sales MT · Consulting"},
  {"id":"mgmt-marketing-531","question":"Which statement best distinguishes order takers from order getters?","options":["Order takers create new demand; order getters process routine reorders","Both roles are identical in skills and pay","Order getters work only inside the office","Order takers mainly handle routine repeat orders from existing customers; order getters seek new customers and actively persuade them"],"answer":3,"explanation":"Order takers maintain existing business, often reorders; order getters prospect and persuade, typically needing more skill and earning more incentive pay.","difficulty":"moderate","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-532","question":"A company's territories differ greatly: Territory X has ₹40 crore potential and Territory Y ₹15 crore, and each has one rep with similar ability. Both reps sold ₹6 crore last year. Which conclusion is most sound?","options":["Both reps performed equally well","Y's rep performed relatively better, since he captured 40% of potential vs 15% for X","X's rep performed better because his territory is bigger","Potential is irrelevant to evaluation"],"answer":1,"explanation":"Market share of potential is 6 / 15 = 40% for Y and 6 / 40 = 15% for X. Equal sales hide very different performance; X's territory may also be too large for one rep.","difficulty":"hard","source":"Sales MT · FMCG MT"},
  {"id":"mgmt-marketing-533","question":"Assertion (A): Pure straight-commission plans can lead reps to neglect non-selling tasks such as customer service and market feedback.\nReason (R): Under straight commission, only sales volume is rewarded, so effort shifts to activities that close orders quickly.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Rewards steer effort: when only closed sales pay, reps under-invest in service, reporting and long-term relationships. That is why many plans combine salary, commission and qualitative measures.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-534","question":"A sales team has 60 open deals with an average value of ₹5 lakh, a 25% win rate and an average sales cycle of 90 days. Using pipeline velocity = (deals × win rate × average value) ÷ cycle length, how much revenue does the pipeline generate per day?","options":["₹25,000","₹75 lakh","About ₹83,333","About ₹3.3 lakh"],"answer":2,"explanation":"Velocity = 60 × 0.25 × ₹5 lakh / 90 = ₹75 lakh / 90 ≈ ₹83,333 a day. ₹75 lakh is the expected value of the pipeline before dividing by cycle length.","difficulty":"hard","source":"Sales MT · Consulting"},
  {"id":"mgmt-marketing-535","question":"A company with 8 territories finds that the top 2 have workloads so heavy that reps cannot visit all key accounts, while 3 others have reps with idle time. Which territory-design principle is being violated, and what is the remedy?","options":["Workload and potential should be roughly balanced across territories; redraw boundaries or add reps to the overloaded ones","Territories should be equal in size; give each the same area","Territories should follow state boundaries","Each territory should have the same number of accounts"],"answer":0,"explanation":"Good territory design balances workload and sales potential, not area or account count, so reps can cover their markets and be evaluated fairly. Unbalanced territories waste capacity and lose sales.","difficulty":"hard","source":"Sales MT · FMCG MT"},
  {"id":"mgmt-marketing-536","question":"A sales contest gives one big prize to the single top-performing rep nationally. Most reps believe a few star territories make winning impossible for them. What is the most likely effect, and the fix?","options":["Most reps will disengage; offer multiple prizes or judge improvement over each rep's own baseline","All reps will try harder; no fix needed","Reps will ask for higher quotas","Sales will rise uniformly"],"answer":0,"explanation":"When most participants see a near-zero chance of winning, expectancy collapses and the contest motivates only a few. Several prize tiers or improvement-based criteria widen the pool of realistic winners.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-537","question":"Customers of a salon chain complain that the same haircut is excellent at one branch and poor at another, and even differs between stylists in the same branch. Which service characteristic is the root cause, and what is the usual remedy?","options":["Intangibility; use physical evidence such as smart interiors","Perishability; use reservation systems","Variability (heterogeneity); standardise processes, train staff and monitor satisfaction","Inseparability; serve customers online"],"answer":2,"explanation":"Because services depend on who provides them and when, quality varies. Firms counter variability with standard procedures, careful hiring and training, and satisfaction tracking.","difficulty":"hard","source":"FMCG MT · Services · MBA placement"},
  {"id":"mgmt-marketing-538","question":"In a service blueprint for a hotel check-in, the kitchen preparing a welcome drink and the IT system updating room status are shown below one particular line, because guests cannot see them. Which line is this?","options":["Line of interaction","Line of visibility","Line of internal interaction","Line of order penetration"],"answer":1,"explanation":"The line of visibility separates onstage actions the customer can see from backstage actions they cannot. The line of interaction separates the customer's own actions from frontline staff's.","difficulty":"very-hard","source":"Services · Consulting"},
  {"id":"mgmt-marketing-539","question":"A customer's flight is cancelled, but the airline rebooks her within an hour, upgrades her and apologises sincerely. Afterwards she is more loyal than before the problem. What is this phenomenon called?","options":["The service recovery paradox","The sleeper effect","The zone of tolerance","Cognitive dissonance"],"answer":0,"explanation":"The service recovery paradox describes customers who, after an excellently handled failure, feel more satisfied or loyal than if nothing had gone wrong. It does not mean firms should cause failures.","difficulty":"hard","source":"Services · MBA placement"},
  {"id":"mgmt-marketing-540","question":"In the SERVQUAL tradition, the 'zone of tolerance' refers to:","options":["The range between the best possible and worst possible service","The range between desired service and adequate (minimum acceptable) service","The time a customer will wait in a queue","The gap between management's perception and service standards"],"answer":1,"explanation":"Customers accept performance anywhere between their desired and adequate levels. Performance below the adequate level causes dissatisfaction; the zone tends to be narrower for the most important attributes.","difficulty":"very-hard","source":"Services · Consulting"},
  {"id":"mgmt-marketing-541","question":"Arrange the links of the service–profit chain in order.\nP. Customer loyalty  Q. Employee satisfaction  R. Internal service quality  S. External service value  T. Customer satisfaction","options":["Q, R, S, T, P","R, S, Q, T, P","R, Q, T, S, P","R, Q, S, T, P"],"answer":3,"explanation":"Heskett and colleagues linked internal service quality to employee satisfaction (and retention and productivity), then to the value delivered to customers, customer satisfaction, loyalty and finally profit and growth.","difficulty":"very-hard","source":"Services · Consulting"},
  {"id":"mgmt-marketing-542","question":"A 100-room hotel can price at ₹5,000 a night and expect 70% occupancy, or at ₹4,200 and expect 85% occupancy. Which option yields higher revenue per available room (RevPAR), and by how much?","options":["₹5,000, by ₹800","₹4,200, by ₹70","Both give the same RevPAR","₹5,000, by ₹70"],"answer":1,"explanation":"RevPAR = average rate × occupancy: 5,000 × 0.70 = ₹3,500 vs 4,200 × 0.85 = ₹3,570. The lower price wins by ₹70 per available room per night. Comparing rates alone favours the wrong option.","difficulty":"very-hard","source":"Services · MBA placement"},
  {"id":"mgmt-marketing-543","question":"A bank designs its branches so that customers waiting in queues can see that a token system is fair, have something to read and can watch staff working on their requests. Which idea from the psychology of waiting (Maister) does this apply?","options":["Customers always prefer longer queues","Waiting time does not affect satisfaction","Occupied time feels shorter than unoccupied time, and unfair waits feel longer than fair ones","Customers prefer not to know how long they will wait"],"answer":2,"explanation":"Maister noted that unoccupied, uncertain, unexplained and unfair waits feel longer. Visible fairness and something to do reduce perceived waiting time.","difficulty":"hard","source":"Services · MBA placement"},
  {"id":"mgmt-marketing-544","question":"A survey asks: \"How satisfied are you with the speed and friendliness of our delivery staff?\" with one 1–5 scale. What is the main flaw?","options":["It is a leading question","It uses a ratio scale","It is a double-barrelled question, asking about two things at once","It uses an open-ended format"],"answer":2,"explanation":"Speed and friendliness are different attributes; a respondent who finds staff fast but rude cannot answer accurately. Each attribute needs its own question.","difficulty":"moderate","source":"Market research · MBA placement"},
  {"id":"mgmt-marketing-545","question":"A brand wants to estimate the share of buyers who prefer a new pack within ±4 percentage points at 95% confidence. A pilot suggests the share is about 30%. What minimum sample size is needed?","options":["About 600","About 385","About 252","About 505"],"answer":3,"explanation":"n = z² p(1 − p) / E² = 1.96² × 0.3 × 0.7 / 0.04² ≈ 504.2, so 505. Using p = 0.5 would need about 601, and using z = 1 would need far fewer.","difficulty":"very-hard","source":"Market research · Consulting"},
  {"id":"mgmt-marketing-546","question":"A survey of 144 shoppers finds an average spend of ₹250 per visit with a standard deviation of ₹60. What is the approximate 95% confidence interval for the average spend of all shoppers?","options":["₹240.2 to ₹259.8","₹190 to ₹310","₹245 to ₹255","₹232.4 to ₹267.6"],"answer":0,"explanation":"Standard error = 60 / √144 = ₹5, so the interval is 250 ± 1.96 × 5 = ₹240.2 to ₹259.8. Using ±1 standard deviation (₹190–₹310) describes the spread of individual shoppers, not the uncertainty in the mean.","difficulty":"hard","source":"Market research · MBA placement"},
  {"id":"mgmt-marketing-547","question":"A researcher concludes that a new ad campaign raised sales when in fact the rise was due to a festival. A second researcher fails to detect a real effect of a price change because her sample was too small. Which errors have they made?","options":["Both made Type II errors","The first made a Type II error and the second a Type I error","The first made a Type I error (false positive) and the second a Type II error (false negative)","Both made Type I errors"],"answer":2,"explanation":"Wrongly concluding an effect exists is a Type I error; failing to detect a real effect is a Type II error, often caused by small samples and low power.","difficulty":"hard","source":"Market research · Consulting"},
  {"id":"mgmt-marketing-548","question":"A rating scale asks respondents to describe a bank on a series of seven-point scales anchored by opposite adjectives, such as 'modern — old-fashioned' and 'friendly — unfriendly'. Which scale is this?","options":["Likert scale","Stapel scale","Constant-sum scale","Semantic differential scale"],"answer":3,"explanation":"A semantic differential uses bipolar adjective pairs at each end of the scale. A Likert scale measures agreement with statements; a Stapel scale uses a single adjective with plus and minus points.","difficulty":"moderate","source":"Market research · MBA placement"},
  {"id":"mgmt-marketing-549","question":"To find users of a rare industrial chemical, a researcher interviews a few known users and asks each to refer others they know. Which sampling method is this, and what is its main weakness?","options":["Stratified sampling; it is costly","Snowball sampling; the sample may be biased towards people in the same network","Systematic sampling; it can miss periodic patterns","Simple random sampling; it requires a complete list"],"answer":1,"explanation":"Snowball sampling grows the sample through referrals, useful for hard-to-reach groups, but respondents tend to resemble one another, so the sample is not representative.","difficulty":"hard","source":"Market research · MBA placement"},
  {"id":"mgmt-marketing-550","question":"Analysis of 50 stores finds that sales (₹'000 a month) = 200 + 3.5 × local ad spend (₹'000), with R² = 0.64. Which interpretation is correct?","options":["Each extra ₹1,000 of ad spend is associated with ₹3,500 more monthly sales, and ad spend explains 64% of the variation in sales across stores","Ad spend causes 64% of all sales","Every store sells ₹200,000 without advertising, for certain","Each extra ₹3,500 of ad spend raises sales by ₹1,000"],"answer":0,"explanation":"The slope means sales rise ₹3,500 per extra ₹1,000 of ad spend on average, and R² means 64% of the variation is explained. Regression on such data shows association, not proven causation.","difficulty":"hard","source":"Market research · Consulting"},
  {"id":"mgmt-marketing-551","question":"A marketer finds that cities with more ice-cream sales also have more drowning incidents, and suggests limiting ice-cream ads to improve safety. What is the flaw?","options":["The sample is too small","A third variable, hot weather, drives both, so correlation does not show causation","Ice-cream sales cannot be measured","The correlation must be negative"],"answer":1,"explanation":"Hot weather increases both ice-cream sales and swimming, which raises drownings. A spurious correlation caused by a lurking variable says nothing about one causing the other.","difficulty":"moderate","source":"Market research · MBA placement"},
  {"id":"mgmt-marketing-552","question":"A company wants to know whether preference for three pack sizes (small, medium, large) differs between urban and rural buyers, using counts of buyers in each cell. Which statistical test is most appropriate?","options":["Paired t-test","Correlation coefficient","Simple linear regression","Chi-square test of independence"],"answer":3,"explanation":"Both variables are categorical (region and pack size), so a chi-square test of independence checks whether they are related. t-tests compare means of numeric variables.","difficulty":"hard","source":"Market research · MBA placement"},
  {"id":"mgmt-marketing-553","question":"A retailer hires people who pose as ordinary customers to visit stores, make purchases and report on staff behaviour, cleanliness and compliance with service standards. This is:","options":["A focus group","Mystery shopping","A consumer panel","An in-depth interview"],"answer":1,"explanation":"Mystery shopping is covert observation of service delivery by trained researchers posing as customers. It measures what actually happens rather than what staff say they do.","difficulty":"moderate","source":"Market research · MBA placement"},
  {"id":"mgmt-marketing-554","question":"A company runs a new in-store display in 20 stores and compares their sales before and after with 20 similar stores that did not get it. Test stores rise 15% and control stores rise 5%. What is the estimated effect of the display, and why is the control group needed?","options":["15%; the control group is not needed","20%; add both changes","10%; the control captures changes that would have happened anyway, such as seasonality","5%; only the control matters"],"answer":2,"explanation":"Effect = 15% − 5% = 10%. The control group absorbs common influences such as season, prices or the economy, so the difference-in-differences isolates the display's effect.","difficulty":"hard","source":"Market research · Consulting"},
  {"id":"mgmt-marketing-555","question":"Perlmutter's EPRG framework describes management orientations towards international markets. A company that treats each country as unique, lets local subsidiaries develop their own products and marketing, and staffs them with local managers has which orientation?","options":["Ethnocentric","Regiocentric","Geocentric","Polycentric"],"answer":3,"explanation":"Polycentric firms see each host country as distinct and adapt locally. Ethnocentric firms extend home-country practices abroad; geocentric firms take a global view and blend standardisation with local adaptation.","difficulty":"very-hard","source":"International marketing · Consulting"},
  {"id":"mgmt-marketing-556","question":"A consumer-goods firm wants to enter a new country with the highest degree of control over operations and brand, and is willing to accept the highest investment and risk. Which entry mode fits best?","options":["Indirect exporting","Licensing","Wholly owned subsidiary (direct investment)","Joint venture"],"answer":2,"explanation":"Entry modes rise in control, commitment and risk from exporting to licensing to joint ventures to wholly owned subsidiaries. Full ownership gives the most control but carries the most risk.","difficulty":"hard","source":"International marketing · MBA placement"},
  {"id":"mgmt-marketing-557","question":"For rural marketing in India, a widely used '4A' framework replaces the 4Ps. Which set is it?","options":["Availability, affordability, acceptability and awareness","Attention, interest, desire and action","Awareness, comprehension, conviction and action","Analysis, adaptation, activation and audit"],"answer":0,"explanation":"Rural 4As: availability (reaching scattered villages), affordability (small packs and low unit prices), acceptability (products and messages that fit rural needs) and awareness (reaching people with limited media access).","difficulty":"very-hard","source":"FMCG MT · Rural marketing"},
  {"id":"mgmt-marketing-558","question":"A detergent maker sells 'eco-friendly' packs whose only green feature is a leaf printed on the label, with no change in ingredients or packaging. What is this practice called, and what is the main risk?","options":["Cause marketing; higher sales","Green positioning; no risk","Societal marketing; higher costs","Greenwashing; loss of trust and possible regulatory action for misleading claims"],"answer":3,"explanation":"Greenwashing makes misleading environmental claims. When exposed, it damages credibility and can attract action from consumer-protection and advertising regulators.","difficulty":"moderate","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-559","question":"C. K. Prahalad's 'fortune at the bottom of the pyramid' argument says companies can profitably serve very low-income consumers. Which strategy is most consistent with it?","options":["Selling the same large packs at urban prices","Innovating in product, packaging and distribution, such as single-use sachets and low-cost models, to make products affordable and accessible","Ignoring low-income markets","Selling only through modern trade"],"answer":1,"explanation":"Prahalad argued that serving the poor requires new business models: small unit packs, low price points, frugal design and new distribution, achieving profit through volume.","difficulty":"hard","source":"FMCG MT · Rural marketing"},
  {"id":"mgmt-marketing-560","question":"A bank's customer meets a teller, a call-centre agent and a mobile app on different days; each interaction shapes her overall view of the bank. Jan Carlzon called each such interaction a:","options":["Service gap","Line of visibility","Zone of tolerance","Moment of truth"],"answer":3,"explanation":"Carlzon's 'moments of truth' are the brief contacts where customers form impressions of a service firm. Managing them consistently is central to service quality.","difficulty":"moderate","source":"Services · MBA placement"},
  {"id":"mgmt-marketing-561","question":"Consider these statements about the services marketing mix:\nI. Physical evidence helps make an intangible service more tangible to customers.\nII. 'Process' covers the flow of activities by which the service is delivered.\nIII. 'People' refers only to the firm's customers, not its employees.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"Physical evidence (facilities, uniforms, brochures) signals quality, and process covers how the service is delivered. 'People' includes employees and other customers who affect the experience, so III is wrong.","difficulty":"hard","source":"Services · MBA placement"},
  {"id":"mgmt-marketing-562","question":"Assertion (A): Non-sampling errors can make a survey misleading even with a very large sample.\nReason (R): Errors from poor question wording, non-response and interviewer bias do not shrink as the sample size grows.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Larger samples reduce sampling error but leave systematic errors untouched; a big but biased survey is precisely wrong. R explains why A holds.","difficulty":"hard","source":"Market research · MBA placement"},
  {"id":"mgmt-marketing-563","question":"A coaching institute's classrooms are cramped, poorly lit and noisy, though its teachers are excellent. Prospective students who visit for a demo class enrol less often than expected. Using Bitner's concept, which element most needs attention?","options":["Price","Promotion","The servicescape (physical environment)","Distribution"],"answer":2,"explanation":"The servicescape is the physical setting where a service is delivered. Because services are intangible, buyers use such cues to judge quality before they experience the core service.","difficulty":"moderate","source":"Services · MBA placement"},
  {"id":"mgmt-marketing-564","question":"A detergent normally sells 10,000 units a week at ₹100 with ₹50 contribution per unit. A two-week 20%-off promotion lifts sales to 25,000 units a week. Afterwards, 30% of the incremental units turn out to be pulled forward from later weeks, and 10% of all promoted units are cannibalised from a sister brand that earns ₹40 a unit. What is the promotion's net effect on contribution?","options":["A gain of ₹5 lakh","A gain of ₹50,000","A loss of ₹1.5 lakh","A loss of ₹6.5 lakh"],"answer":2,"explanation":"Promo contribution = 50,000 × ₹30 = ₹15 lakh vs a baseline of 20,000 × ₹50 = ₹10 lakh. Subtract pull-forward (9,000 × ₹50 = ₹4.5 lakh) and cannibalisation (5,000 × ₹40 = ₹2 lakh): 15 − 10 − 4.5 − 2 = −₹1.5 lakh.","difficulty":"very-hard","source":"FMCG MT · Consulting · MBA placement"},
  {"id":"mgmt-marketing-565","question":"A company with a 30% share launches a second brand that wins 5% of the category. If the new brand draws share from all existing brands in proportion to their current shares (the 'fair share' assumption), by how much does the company's total share rise?","options":["5 points","3.5 points","1.5 points","6.5 points"],"answer":1,"explanation":"Under fair-share draw, 30% of the new brand's 5 points (1.5 points) come from the company's own brand, so the net gain is 5 − 1.5 = 3.5 points. Ignoring cannibalisation gives 5 points.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-566","question":"A brand's weighted distribution is 55%. A distribution drive adds smaller outlets, raising numeric distribution from 40% to 60% and weighted distribution to 65%. If sales are proportional to weighted distribution, roughly how much will sales grow?","options":["50%","10%","About 18%","20%"],"answer":2,"explanation":"Sales rise in proportion to WD: 65 / 55 − 1 ≈ 18.2%. The 50% jump in outlet count (ND 40 → 60) overstates the gain because the new outlets are small.","difficulty":"very-hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-567","question":"Channel A brings customers at a CAC of ₹800 who are retained 70% each year; Channel B brings customers at ₹500 retained 50% each year. Each customer earns ₹1,000 of margin a year, and LTV is taken as margin ÷ (1 − retention). Which channel is better on LTV minus CAC, and on LTV/CAC?","options":["A on both","B on both","A on LTV − CAC, B on LTV/CAC","B on LTV − CAC, A on LTV/CAC"],"answer":0,"explanation":"A: LTV = 1,000 / 0.3 ≈ ₹3,333, so LTV − CAC ≈ ₹2,533 and LTV/CAC ≈ 4.2. B: LTV = ₹2,000, LTV − CAC = ₹1,500, ratio 4.0. The cheaper CAC of B is outweighed by A's better retention.","difficulty":"very-hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-568","question":"A TV campaign delivers 100 GRPs in week 1, 80 in week 2 and none in week 3. Using an adstock model with a weekly carry-over (decay) rate of 0.6, what is the adstock in week 3?","options":["0","48","60","84"],"answer":3,"explanation":"Adstock = this week's GRPs + 0.6 × last week's adstock: week 1 = 100; week 2 = 80 + 60 = 140; week 3 = 0 + 0.6 × 140 = 84. The ad still works after it stops airing.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-569","question":"A rural distribution van costs ₹40,000 a month and makes 80 village visits a month. The company earns a 15% contribution on van sales. What average sales per visit does the van need to break even?","options":["₹2,500","₹3,333","₹500","₹6,000"],"answer":1,"explanation":"Contribution needed per visit = 40,000 / 80 = ₹500, so sales per visit = 500 / 0.15 ≈ ₹3,333. ₹500 is the contribution, not the sales, needed.","difficulty":"very-hard","source":"FMCG MT · Rural marketing"},
  {"id":"mgmt-marketing-570","question":"A café chain's loyalty programme has 50,000 members who used to spend ₹2,000 a year each. The programme raises their spending by 10%. Rewards cost 2% of members' total spend, the gross margin is 30%, and the programme's fixed cost is ₹5 lakh a year. What is its net annual effect?","options":["A gain of ₹3 lakh","A gain of ₹23 lakh","A loss of ₹2 lakh","A gain of ₹30 lakh"],"answer":0,"explanation":"Per member: extra margin = 200 × 0.3 = ₹60; rewards = 2% × 2,200 = ₹44; fixed cost = ₹10. Net = ₹6 × 50,000 = ₹3 lakh. Charging rewards only on the extra ₹200 of spend gives ₹23 lakh, the common trap.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-571","question":"A supplier's price list says ₹100 a unit for the first 1,000 units and ₹90 for units above 1,000 (an incremental discount). A rival offers ₹90 on all units once an order reaches 1,000 (an all-units discount). For an order of 1,200 units, how much cheaper is the rival?","options":["₹2,000","₹12,000","₹18,000","₹10,000"],"answer":3,"explanation":"Incremental: 1,000 × 100 + 200 × 90 = ₹1,18,000. All-units: 1,200 × 90 = ₹1,08,000. The rival is ₹10,000 cheaper, because its lower price applies to the first 1,000 units too.","difficulty":"very-hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-572","question":"A brand can put an extra ₹1 lakh of advertising into Region A, where it would add ₹4 lakh of sales at a 25% contribution margin, or Region B, where it would add ₹3 lakh of sales at a 40% margin. Which region should get the money, and what is the net gain?","options":["A, gain ₹3 lakh","B, gain ₹20,000","A, no gain","B, gain ₹2 lakh"],"answer":1,"explanation":"Extra contribution: A = 4 × 0.25 = ₹1 lakh (exactly paying back the spend), B = 3 × 0.40 = ₹1.2 lakh. B nets ₹20,000. Choosing on sales lift alone picks A.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-573","question":"A food-delivery platform charges restaurants a commission but often gives consumers free delivery and discounts, even at a loss on the consumer side. Which logic of two-sided platforms best explains this?","options":["Consumers are more profitable than restaurants","It is predatory pricing, which is the only reason platforms subsidise","Platforms subsidise the side whose participation creates more value for the other side and is more price-sensitive, then earn on the other side","Platforms must charge both sides equally"],"answer":2,"explanation":"Cross-side network effects mean more consumers make the platform more valuable to restaurants. Platforms therefore subsidise the price-sensitive, value-creating side and charge the side that benefits.","difficulty":"very-hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-574","question":"A biscuit brand's sales fell 5% last year while its market share rose from 20% to 22%. What must have happened to the category, roughly?","options":["It grew about 5%","It was flat","It shrank about 14%","It shrank about 5%"],"answer":2,"explanation":"Category = brand sales / share. If brand sales are 0.95 of before and share is 1.1 times before, the category is 0.95 / 1.1 ≈ 0.864 of before, a fall of about 13.6%. A brand can gain share while shrinking in a collapsing category.","difficulty":"very-hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-575","question":"A shampoo with an MRP of ₹200 gives the retailer 20% on MRP and the distributor 8% on the distributor's selling price. The company wants to offer consumers ₹20 off while leaving both channel members' rupee margins unchanged. What will the company's net realisation per unit become?","options":["₹127.20","₹147.20","₹132.48","₹136"],"answer":0,"explanation":"Retailer buys at ₹160 (margin ₹40); distributor buys at 160 × 0.92 = ₹147.20 (margin ₹12.80). Keeping both rupee margins fixed, the company absorbs the full ₹20: 147.20 − 20 = ₹127.20. Keeping percentage margins instead would give ₹132.48.","difficulty":"very-hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-576","question":"A premium juice brand at ₹120 faces a new rival at ₹90 with similar quality. Research shows 30% of its buyers would switch if it does nothing. Matching at ₹90 would keep all buyers, but contribution per unit falls from ₹50 to ₹20. A third option, a 'fighter' variant at ₹90 with ₹25 contribution, would retain switchers on the fighter while the main brand keeps its loyal 70%, but 10% of loyal buyers would trade down to the fighter. Which option maximises contribution per 100 original buyers?","options":["Do nothing: ₹3,500","Match price: ₹2,000","Fighter brand: ₹4,250","Fighter brand: ₹4,075"],"answer":3,"explanation":"Do nothing: 70 × 50 = ₹3,500. Match: 100 × 20 = ₹2,000. Fighter: 63 loyal buyers stay on the main brand (63 × 50 = ₹3,150) and 37 buy the fighter (30 switchers + 7 trading down: 37 × 25 = ₹925), total ₹4,075. Ignoring the trade-down gives ₹4,250.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-577","question":"A consumer-durables brand earns ₹2,000 of contribution per unit sold through dealers. It is weighing a 'no-cost EMI' scheme in which it pays the financier 6% of the ₹40,000 price for each EMI sale. If the scheme raises unit sales by 15% and 50% of all buyers (old and new) use the EMI, what happens to total contribution per 100 baseline units?","options":["It rises by ₹30,000","It falls by ₹1,08,000","It falls by ₹1,38,000","It falls by ₹6,000"],"answer":1,"explanation":"Baseline = 100 × 2,000 = ₹2,00,000. With the scheme: 115 × 2,000 = ₹2,30,000 less EMI cost on 57.5 units × ₹2,400 = ₹1,38,000, leaving ₹92,000, a fall of ₹1,08,000. Charging the EMI cost only on the 15 extra units wrongly suggests a small ₹6,000 dip.","difficulty":"very-hard","source":"Sales MT · Consulting"},
  {"id":"mgmt-marketing-578","question":"A brand's funnel shows 70% awareness, 35% consideration, 21% trial and 7% regular use, while the category norms are 70%, 42%, 21% and 10.5%. At which stage-to-stage conversion is the brand's biggest gap against the norm?","options":["Awareness to consideration","Consideration to trial","Trial to regular use","There is no gap"],"answer":2,"explanation":"Brand conversions: 50%, 60% and 33%; norms: 60%, 50% and 50%. The brand is weaker at awareness → consideration (50% vs 60%), stronger at consideration → trial, and weakest relative to norm at trial → regular use (33% vs 50%), pointing to a product or value problem after trial.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-579","question":"A packaged-food company finds that its Hindi-belt rural sales respond strongly to ₹5 packs and wall paintings, while metro sales respond to digital ads and larger value packs. Allocating a single national plan to both would most clearly violate which principle?","options":["Segments should differ in their response to marketing-mix elements, and each should get a tailored mix","All segments should get the same mix for brand consistency","Rural markets do not need promotion","Price should be identical in all markets"],"answer":0,"explanation":"Segments are worth separating precisely because they respond differently to price points, pack sizes and media; a single mix wastes spend in both.","difficulty":"hard","source":"FMCG MT · Rural marketing"},
  {"id":"mgmt-marketing-580","question":"A brand's market share is 12% and the leader's is 30%. The market grows 4% a year. In BCG terms, and with relative share defined as own share ÷ largest rival's share, what is the brand's relative share and its likely quadrant (using 1.0 and 10% growth as cut-offs)?","options":["2.5; cash cow","0.4; question mark","0.12; star","0.4; dog"],"answer":3,"explanation":"Relative share = 12 / 30 = 0.4, below 1.0, in a market growing 4%, below 10%: a dog. A question mark would need high growth.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-581","question":"A D2C brand lowers its free-shipping threshold from ₹999 to ₹599. Average order value falls from ₹1,100 to ₹900, but conversion rate rises from 2.0% to 2.6%. Shipping cost per order is ₹80 and gross margin is 50%, with shipping previously paid by 30% of orders (those below ₹999) and now by none. Per 1,000 visitors, what happens to gross margin after shipping costs borne by the brand?","options":["It falls by ₹260","It rises by ₹700","It rises by ₹220","It falls by ₹960"],"answer":0,"explanation":"Before: 20 orders × ₹550 = ₹11,000, less brand-paid shipping on 70% of orders (14 × 80 = ₹1,120) = ₹9,880. After: 26 orders × ₹450 = ₹11,700, less shipping on all 26 (₹2,080) = ₹9,620, a fall of ₹260. Ignoring shipping shows a misleading ₹700 rise.","difficulty":"very-hard","source":"Digital marketing · Consulting"},
  {"id":"mgmt-marketing-582","question":"Assertion (A): A brand with high awareness but low trial should usually spend more on sampling and in-store activation than on additional mass advertising.\nReason (R): The funnel bottleneck lies at converting awareness into trial, which sampling and activation address more directly than further reach.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Spending should target the weakest funnel stage. When awareness is already high, more reach adds little; sampling and activation tackle the trial barrier directly.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-583","question":"Consider these statements about measuring marketing performance:\nI. A rising market share always means rising profit.\nII. Customer lifetime value should be based on margin, not revenue.\nIII. Marketing ROI should compare incremental contribution with incremental spend.\nWhich are correct?","options":["I and II only","II and III only","I, II and III","I and III only"],"answer":1,"explanation":"LTV built on revenue overstates customer worth, and marketing ROI should be measured on incremental contribution. Share can rise through unprofitable price cuts, so I is false.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-584","question":"An FMCG company cuts its trade margin on a fast-moving soap from 12% to 9% to fund a TV campaign. Within months, retailers give the soap less shelf space and push a rival paying 13%. Which concept explains the retailers' response?","options":["Pull strategy dominance","Consumer brand loyalty","Channel members act on their own economics; a weaker push incentive shifts their effort to better-paying brands","Stimulus generalisation"],"answer":2,"explanation":"Retailers allocate shelf space and recommendations to maximise their own returns. Cutting push incentives in favour of pull spend can backfire if consumer pull is not strong enough to force retailers to stock and display the brand.","difficulty":"hard","source":"FMCG MT · Sales MT"},
  {"id":"mgmt-marketing-585","question":"A shampoo maker introduces a ₹1 sachet in villages, uses local-language wall paintings and haat demonstrations, and appoints village-level resellers. Which elements of the rural 4A framework is it mainly addressing?","options":["Acceptability only","Affordability, awareness and availability","Awareness only","Availability and acceptability only"],"answer":1,"explanation":"₹1 sachets address affordability, wall paintings and haat demos build awareness, and village resellers improve availability. Acceptability would involve adapting the product itself to rural needs.","difficulty":"hard","source":"FMCG MT · Rural marketing"},
  {"id":"mgmt-marketing-586","question":"A brand finds that 80% of its buyers buy it only once or twice a year, and that its few heavy buyers are also heavy buyers of rival brands. According to the empirical regularities popularised by Byron Sharp and the Ehrenberg-Bass Institute, which growth strategy does this support?","options":["Focusing almost all spend on deepening loyalty among existing heavy buyers","Growing penetration by reaching all category buyers, including light buyers, and building mental and physical availability","Raising prices to signal premium quality","Cutting distribution to focus on fewer stores"],"answer":1,"explanation":"Ehrenberg-Bass research finds brands grow mainly by increasing penetration, since most buyers are light and loyalty levels are similar across brands of similar size. Broad reach and availability matter more than loyalty programmes.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-587","question":"A brand with 5% share has a 'double jeopardy' problem relative to a rival with 25% share. Which pattern does the double jeopardy law describe?","options":["Smaller brands always have more loyal buyers","Smaller brands have more buyers but less loyalty","Brand size has no link with loyalty","Smaller brands have fewer buyers, and those buyers are also somewhat less loyal"],"answer":3,"explanation":"The double jeopardy law (Ehrenberg) says small brands suffer twice: they have far fewer buyers, and those buyers buy them slightly less often. It argues against the idea of small 'niche' brands with unusually loyal customers.","difficulty":"very-hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-588","question":"A company is choosing between two campaigns with the same ₹50 lakh cost. Campaign X is expected to add ₹2.4 crore of sales at a 25% contribution margin; Campaign Y is expected to add ₹1.6 crore at a 40% margin. Which has the higher marketing ROI, defined as (incremental contribution − spend) ÷ spend?","options":["X: 20% vs Y: 28%","Both: 20%","Y: 28% vs X: 20%","X: 380% vs Y: 220%"],"answer":2,"explanation":"X adds 2.4 × 0.25 = ₹60 lakh of contribution, ROI = (60 − 50) / 50 = 20%. Y adds 1.6 × 0.40 = ₹64 lakh, ROI = 28%. Using sales rather than contribution gives the misleading 380% vs 220%.","difficulty":"hard","source":"FMCG MT · Consulting"},
  {"id":"mgmt-marketing-589","question":"A new soft drink faces a choice: launch nationally at once, or roll out region by region. Which situation most favours a rapid national launch?","options":["The product needs heavy local adaptation","The firm has limited production capacity","The firm has no national distribution","A competitor is about to launch a similar product and first-mover share matters"],"answer":3,"explanation":"Rapid national launches make sense when speed and pre-emption matter and the firm has the capacity and distribution to support them. Limited capacity or distribution favours a phased rollout.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-590","question":"A brand team wants to know whether a 10% price rise on its tea will hurt volume. Which approach gives the most reliable estimate of the causal effect of the price rise?","options":["Asking consumers in a survey whether they would still buy at the higher price","Comparing this year's sales with last year's after raising price everywhere","Looking at the correlation between price and sales across all brands in the category","Raising price in a set of randomly chosen test stores and comparing their sales with matched control stores over the same weeks"],"answer":3,"explanation":"A controlled store test isolates the price effect from seasonality, competitor moves and other changes. Stated intentions overstate willingness to pay, and before–after or cross-brand comparisons are confounded.","difficulty":"hard","source":"FMCG MT · Market research"},
  {"id":"mgmt-marketing-591","question":"A 100 g pack of coffee sells at ₹100 and costs ₹60 to make (cost proportional to weight). The brand compares two promotions: 20% off the price, or 25% extra coffee free at the same ₹100. What is the contribution per pack under each?","options":["₹20 under price-off and ₹25 under extra-free","₹20 under both, since 25% extra equals 20% off","₹20 under price-off and ₹15 under extra-free","₹25 under price-off and ₹20 under extra-free"],"answer":0,"explanation":"Price-off: ₹80 − ₹60 = ₹20. Extra-free: ₹100 − 1.25 × ₹60 = ₹25, because the brand gives away product at cost, not at price. Treating 25% extra like 25% off (₹75 − ₹60 = ₹15) is the classic error; the shopper's value is equivalent to 20% off, but the brand's cost is not.","difficulty":"very-hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-592","question":"A brand budgeted to sell 10,000 units at ₹50. It actually sold 9,000 units at ₹55. How do the sales price and sales volume variances explain the change in revenue?","options":["Price ₹50,000 favourable; volume ₹45,000 adverse","Price ₹45,000 favourable; volume ₹50,000 adverse; net ₹5,000 adverse","Price ₹45,000 adverse; volume ₹50,000 favourable","Price ₹5,000 favourable; volume nil"],"answer":1,"explanation":"Price variance = (₹55 − ₹50) × 9,000 actual units = ₹45,000 F. Volume variance = (9,000 − 10,000) × ₹50 budget price = ₹50,000 A. Net: ₹4,95,000 − ₹5,00,000 = ₹5,000 adverse.","difficulty":"hard","source":"FMCG MT · sales MT · MBA placement"},
  {"id":"mgmt-marketing-593","question":"A brand planned a 10% share of a 1,00,000-unit market, at ₹20 contribution a unit. The market turned out to be 80,000 units, and the brand won a 12% share. Splitting the contribution shortfall, what are the market-size and market-share variances?","options":["Size ₹8,000 adverse; share nil","Size ₹48,000 adverse; share ₹40,000 favourable","Size ₹40,000 adverse; share ₹32,000 favourable","Size ₹32,000 adverse; share ₹40,000 favourable"],"answer":2,"explanation":"Size variance = (80,000 − 1,00,000) × 10% planned share × ₹20 = ₹40,000 A. Share variance = (12% − 10%) × 80,000 actual market × ₹20 = ₹32,000 F. Net ₹8,000 A matches 9,600 vs 10,000 units. The marketing team actually outperformed; the shortfall came from the market.","difficulty":"very-hard","source":"FMCG MT · consulting · MBA placement"},
  {"id":"mgmt-marketing-594","question":"Town A has 4 lakh people and Town B 1 lakh, 30 km apart on a highway. Using Reilly's law of retail gravitation, how far from Town B is the breaking point beyond which shoppers prefer Town A?","options":["6 km","15 km","20 km","10 km"],"answer":3,"explanation":"Breaking point from B = distance ÷ (1 + √(Pa/Pb)) = 30 ÷ (1 + √4) = 10 km, so the larger town pulls shoppers to within 10 km of B. Using the population ratio without the square root gives 6 km; 15 km ignores size; 20 km is measured from A.","difficulty":"very-hard","source":"Retail MT · MBA placement"},
  {"id":"mgmt-marketing-595","question":"Using the Huff model with attraction = floor area ÷ (travel time)², a shopper chooses among three malls: X (2 lakh sq ft, 10 minutes away), Y (1 lakh sq ft, 5 minutes) and Z (50,000 sq ft, 5 minutes). What is the probability she visits Y?","options":["50%","40%","29%","33%"],"answer":0,"explanation":"Attractions: X 2,00,000/100 = 2,000; Y 1,00,000/25 = 4,000; Z 50,000/25 = 2,000. Y's share = 4,000/8,000 = 50%. Dividing by time rather than time squared gives 40%, and size alone gives 29%.","difficulty":"very-hard","source":"Retail MT · MBA placement"},
  {"id":"mgmt-marketing-596","question":"A D2C brand with a 40% gross margin raised monthly ad spend from ₹10 lakh to ₹15 lakh, and attributed revenue rose from ₹40 lakh to ₹50 lakh. The team says, 'ROAS is still 3.3, above our break-even ROAS of 2.5, so the extra spend paid off.' What is wrong?","options":["Nothing; average ROAS above break-even means every rupee is profitable","The extra ₹5 lakh brought ₹10 lakh revenue (marginal ROAS 2.0), i.e. ₹4 lakh gross profit, so the increment lost ₹1 lakh","Break-even ROAS for a 40% margin is 4.0, so even the original spend was loss-making","ROAS should be computed on profit, so the true ROAS was always below 1"],"answer":1,"explanation":"Decisions about additional spend need marginal ROAS: ₹10 lakh ÷ ₹5 lakh = 2.0, below the break-even of 1/0.40 = 2.5. The incremental ₹4 lakh of gross profit does not cover ₹5 lakh of spend, even though the blended average looks healthy.","difficulty":"very-hard","source":"Digital marketing · D2C · MBA placement"},
  {"id":"mgmt-marketing-597","question":"A redesigned checkout button lifts conversion by 18% in the first week of an A/B test, but by week four the lift has shrunk to 2%. Returning users made up most of the early traffic. What is the most likely explanation?","options":["The test was underpowered in week one","Seasonality affected only the test group","A novelty effect: returning users clicked the new button out of curiosity, and the effect faded once it became familiar","The control group was contaminated by the treatment"],"answer":2,"explanation":"Changes seen by returning users often show an early spike from novelty that decays. Reading results only from the first days overstates the long-run effect; running the test long enough or analysing new users separately guards against this.","difficulty":"hard","source":"Digital marketing · product analyst · MBA placement"},
  {"id":"mgmt-marketing-598","question":"An analyst checks an A/B test's p-value every morning and stops the test the first day it falls below 0.05, declaring a winner. Why is this a problem?","options":["P-values cannot be computed before the test ends","It makes Type II errors more likely","It is fine, as long as the sample is above 1,000","Repeatedly checking and stopping at the first significant result inflates the false-positive rate well above 5%"],"answer":3,"explanation":"Each look is another chance for random noise to cross the threshold, so 'peeking' with optional stopping greatly raises the true Type I error rate. Fix the sample size in advance or use sequential testing methods built for repeated looks.","difficulty":"very-hard","source":"Digital marketing · product analyst · MBA placement"},
  {"id":"mgmt-marketing-599","question":"Many shoppers will drive 15 minutes to save ₹500 on a ₹1,500 mixer, but not to save the same ₹500 on a ₹60,000 TV. What does this show, and what does it imply for promotions?","options":["People judge savings relative to the price, so the same rupee discount should be framed as a percentage on cheap items and in rupees on expensive ones","People are fully rational, so discounts should always be shown in rupees","Expensive products have elastic demand, so discounts never work","Shoppers value time more when buying a TV"],"answer":0,"explanation":"Mental accounting and relative thinking (Thaler; Tversky and Kahneman) make ₹500 feel large on ₹1,500 (33%) and trivial on ₹60,000 (under 1%). Marketers therefore show the bigger-looking figure: a percentage on low prices, a rupee amount on high ones.","difficulty":"hard","source":"FMCG MT · consumer behaviour · MBA placement"},
  {"id":"mgmt-marketing-600","question":"A shampoo sells 1,000 units a week in a store and is out of stock 8% of the time. When it is missing, 35% of shoppers buy another brand, 25% buy a different size of the same brand, 30% come back later and buy it, and 10% buy nothing. How many units a year does the brand lose?","options":["1,456","4,160","1,872","3,120"],"answer":2,"explanation":"Annual demand during stock-outs = 8% × 52,000 = 4,160. The brand loses only the switchers (35%) and the non-buyers (10%): 45% × 4,160 = 1,872. Counting only switchers gives 1,456; treating delayed purchases as lost gives 3,120.","difficulty":"very-hard","source":"FMCG MT · sales MT · MBA placement"},
  {"id":"mgmt-marketing-601","question":"Young professionals like the idea of investing in mutual funds and their friends approve, yet few start a SIP because they think the paperwork and choice of fund are too complex. In the theory of planned behaviour, which factor should the marketer target?","options":["Attitude towards the behaviour","Subjective norms","Brand awareness","Perceived behavioural control"],"answer":3,"explanation":"Attitude and norms are already favourable; the barrier is people's belief that they can carry out the behaviour. Simplifying onboarding (one-tap KYC, a recommended starter fund) raises perceived behavioural control.","difficulty":"hard","source":"Marketing MT · consumer behaviour · MBA placement"},
  {"id":"mgmt-marketing-602","question":"A retailer's loyalty scheme gives 2 points per ₹100 spent; each point can be redeemed for ₹0.50. Experience shows 60% of points are eventually redeemed. What is the expected cost of the scheme as a share of sales?","options":["0.6%","1.0%","1.2%","2.0%"],"answer":0,"explanation":"Face value = 2 × ₹0.50 = ₹1 per ₹100 = 1.0% of sales; with 40% breakage (unredeemed points), the expected cost is 0.6%. 1.0% ignores breakage, and 1.2% values each point at ₹1.","difficulty":"hard","source":"Retail MT · MBA placement"},
  {"id":"mgmt-marketing-603","question":"A brand distributes 2 lakh free samples at ₹8 each. 5% of recipients become buyers who each buy 6 packs in the first year at ₹20 contribution a pack, but 40% of these buyers would have bought anyway. What is the sampling campaign's first-year net effect?","options":["A gain of ₹7.2 lakh","A loss of ₹8.8 lakh","A loss of ₹4.0 lakh","A gain of ₹12.0 lakh"],"answer":1,"explanation":"Cost = ₹16 lakh. Incremental buyers = 10,000 × 60% = 6,000, giving 6,000 × 6 × ₹20 = ₹7.2 lakh. Net = −₹8.8 lakh in year one (repeat purchases in later years may still justify it). Counting all 10,000 buyers gives −₹4.0 lakh.","difficulty":"very-hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-604","question":"When a premium truffle costs ₹15 and a basic chocolate ₹1, most buyers choose the truffle. When both prices drop by ₹1, to ₹14 and ₹0, most buyers switch to the free basic chocolate, although the price gap has not changed. What does this show?","options":["Demand is linear in price","Shoppers ignore prices below ₹5","The zero-price effect: 'free' is perceived as having no downside and attracts far more demand than a tiny price cut implies","Odd pricing"],"answer":2,"explanation":"Shampanier, Mazar and Ariely showed a ₹1 cut to zero causes a much bigger demand jump than any other ₹1 cut, because free removes perceived risk. It explains the power of 'free trial', 'free delivery' and 'free gift' offers.","difficulty":"hard","source":"Marketing MT · consumer behaviour · MBA placement"},
  {"id":"mgmt-marketing-605","question":"A travel site shows a flight at ₹3,999 and adds a mandatory convenience fee and seat charges at checkout, taking the total to ₹4,800. Rivals quote ₹4,600 all-in. Why can the site still win bookings, and what is the risk?","options":["Drip pricing anchors buyers on the low headline price and they continue after investing effort, but the hidden mandatory fees erode trust and may be treated as unfair practice","The total is lower than rivals'","Buyers always compare the final all-in price","Partitioned prices make the product look more premium"],"answer":0,"explanation":"Showing a low base and revealing compulsory fees late exploits anchoring and sunk effort. It may lift short-term conversions, but it angers customers once noticed and is increasingly regarded as a misleading practice.","difficulty":"hard","source":"Marketing MT · pricing · MBA placement"},
  {"id":"mgmt-marketing-606","question":"A bank targets new branches by grouping neighbourhoods on combined census-style data such as income, education, housing type and family life-stage, on the logic that 'birds of a feather flock together'. Which segmentation basis is this?","options":["Benefit segmentation","Geodemographic segmentation","Occasion segmentation","Psychographic segmentation"],"answer":1,"explanation":"Geodemographics (as in PRIZM-type systems) combines location with demographics to profile neighbourhoods. Benefit and occasion are behavioural bases, and psychographics uses lifestyle and personality.","difficulty":"moderate","source":"Marketing MT · MBA placement"},
  {"id":"mgmt-marketing-607","question":"India's New Consumer Classification System (NCCS), widely used for media and market research, classifies a household mainly on which two variables?","options":["Monthly household income and city size","Occupation and age of the chief earner","Education of the chief earner and the number of listed consumer durables the household owns","Type of house and vehicle ownership only"],"answer":2,"explanation":"NCCS replaced the old SEC grid by combining the chief earner's education with ownership of a list of durables (from electricity connection to car). Income is avoided because respondents misreport it.","difficulty":"hard","source":"FMCG MT · market research · MBA placement"},
  {"id":"mgmt-marketing-608","question":"A chemicals maker tells its packaging supplier, 'We buy your drums; we would like you to source your cleaning solvents from us.' What is this B2B practice called?","options":["Derived demand","Systems buying","Straight rebuy","Reciprocity"],"answer":3,"explanation":"Reciprocity means firms buying from each other. It is common in B2B markets, though it can conflict with purchasing on merit and, if coerced, with competition law.","difficulty":"moderate","source":"B2B sales · MBA placement"},
  {"id":"mgmt-marketing-609","question":"A city's retail scene moves from general stores carrying everything, to specialist shops, back to large hypermarkets with very wide ranges, and then to niche specialty boutiques. Which theory describes this cycle of assortment width?","options":["The retail accordion","The wheel of retailing","The product life cycle","Bucklin's postponement-speculation theory"],"answer":0,"explanation":"The retail accordion (Hollander) describes alternation between wide-assortment generalists and narrow specialists. The wheel of retailing is about price and service levels: low-cost entrants trade up and are replaced by new discounters.","difficulty":"hard","source":"Retail MT · MBA placement"},
  {"id":"mgmt-marketing-610","question":"An Indian snack maker entering the Middle East changes both its recipes (less spice, halal certification) and its advertising message (from 'family chai-time' to 'office snacking'). In Keegan's product–communication strategies, this is:","options":["Straight extension","Dual adaptation","Communication adaptation","Product invention"],"answer":1,"explanation":"Changing both the product and the promotion is dual adaptation. Straight extension changes neither, communication adaptation changes only the message, and product invention creates a new product for the market.","difficulty":"hard","source":"Marketing MT · international marketing · MBA placement"},
  {"id":"mgmt-marketing-611","question":"A liquor company, barred from advertising alcohol on TV, advertises 'club soda' and music CDs under the same brand name and logo, though these products barely sell. What is this practice called?","options":["Ambush marketing","Guerrilla marketing","Surrogate advertising","Native advertising"],"answer":2,"explanation":"Surrogate advertising promotes a restricted product indirectly through a brand extension that keeps the brand name visible. Regulators look at whether the surrogate product is genuine and sold in meaningful volumes.","difficulty":"moderate","source":"Marketing MT · MBA placement"},
  {"id":"mgmt-marketing-612","question":"In Kotler's 'Marketing 4.0' customer path, what comes after a customer is aware of and attracted to a brand, and is the stage where friends, reviews and online search matter most?","options":["Act","Advocate","Appeal","Ask"],"answer":3,"explanation":"The 5A path is Aware → Appeal → Ask → Act → Advocate. 'Ask' is the stage where curious customers seek information from friends, reviews and search, which is why connectivity shapes it so strongly.","difficulty":"hard","source":"Marketing MT · digital marketing · MBA placement"},
  {"id":"mgmt-marketing-613","question":"A campaign uses TV, which reaches 40% of the target, and YouTube, which reaches 30%. If exposure to the two is independent, what is the combined unduplicated reach?","options":["58%","70%","12%","35%"],"answer":0,"explanation":"Combined reach = 1 − (1 − 0.40)(1 − 0.30) = 1 − 0.42 = 58%. Adding gives 70%, which double-counts the 12% reached by both.","difficulty":"hard","source":"Marketing MT · media planning · MBA placement"},
  {"id":"mgmt-marketing-614","question":"A researcher has 1,500 respondents' ratings on 24 attitude statements about snacks and wants to reduce them to a few underlying dimensions, such as 'health concern' and 'indulgence'. Which technique fits?","options":["Cluster analysis","Factor analysis","Conjoint analysis","Discriminant analysis"],"answer":1,"explanation":"Factor analysis groups correlated variables into a smaller set of underlying factors. Cluster analysis groups respondents rather than variables; it is often run afterwards on the factor scores to form segments.","difficulty":"hard","source":"Market research · MBA placement"},
  {"id":"mgmt-marketing-615","question":"A researcher asks consumers only to rate how similar each pair of eight car brands is, without naming any attributes, and then builds a map showing the brands' positions. Which technique produces such a map?","options":["Factor analysis of attribute ratings","Correspondence analysis of a brand–attribute table","Multidimensional scaling","Cluster analysis of respondents"],"answer":2,"explanation":"Multidimensional scaling turns overall similarity judgements into a spatial map, and the analyst then interprets the dimensions. Its strength is that it does not presuppose which attributes matter; factor and correspondence methods start from named attributes.","difficulty":"very-hard","source":"Market research · consulting · MBA placement"},
  {"id":"mgmt-marketing-616","question":"To survey car owners in a city, a firm draws a random sample from a list of landline telephone subscribers. Even with a large sample, the results are biased. Which error is this?","options":["Non-response error","Measurement error","Random sampling error","Sampling frame error"],"answer":3,"explanation":"The list used to draw the sample does not match the population (many car owners have no landline), so certain people cannot be selected. A larger sample from the wrong list does not fix it.","difficulty":"moderate","source":"Market research · MBA placement"},
  {"id":"mgmt-marketing-617","question":"A brand ran the same humorous ad for eight months. Recall stayed high, but tracking shows that its persuasive effect fell sharply and some viewers now find it irritating. What has happened, and what is the usual response?","options":["Advertising wear-out; refresh the creative with new executions of the same idea","The sleeper effect; keep running the ad","Message decay from too little frequency; buy more GRPs","Cognitive dissonance; switch to a fear appeal"],"answer":0,"explanation":"After many exposures an ad stops adding persuasion and may annoy (wear-out). Brands keep the campaign idea but rotate fresh executions; adding more GRPs of the same ad would make it worse.","difficulty":"moderate","source":"Marketing MT · advertising · MBA placement"},
  {"id":"mgmt-marketing-618","question":"The East region has 20% of the country's population, 30% of national category sales and 12% of the brand's sales. What are its CDI and BDI, and what do they suggest?","options":["CDI 60, BDI 150: the category is weak but the brand is strong, so defend","CDI 150, BDI 60: the category is strong but the brand is under-developed, so it is a high-potential region for investment","CDI 150, BDI 40: invest only in the category","CDI 30, BDI 12: the region is too small to matter"],"answer":1,"explanation":"CDI = 30/20 × 100 = 150 and BDI = 12/20 × 100 = 60. High CDI with low BDI means people buy the category heavily but not our brand, the classic case for extra investment.","difficulty":"hard","source":"FMCG MT · sales MT · MBA placement"},
  {"id":"mgmt-marketing-619","question":"Jan Carlzon of SAS airline argued that a company is judged in many brief encounters, each lasting perhaps 15 seconds, between a customer and front-line staff. What did he call these, and what did he conclude?","options":["Service encounters; managers should script every one","Critical incidents; they should be recorded and punished","Moments of truth; front-line staff must be empowered to act on the spot","Touchpoints; they matter only in digital channels"],"answer":2,"explanation":"Carlzon's 'moments of truth' are the brief contacts that shape the customer's view of the whole company. He inverted the hierarchy so that front-line staff could solve problems immediately without referring upwards.","difficulty":"moderate","source":"Services marketing · MBA placement"},
  {"id":"mgmt-marketing-620","question":"A dealer's list price for a machine is ₹1,000. On the invoice it gets a 10% dealer discount and a ₹50 volume discount. Off the invoice, the maker also gives a 2% cash discount on the invoice amount, ₹30 of co-op advertising support and ₹40 of free freight. What is the pocket price?","options":["₹850","₹760","₹803","₹763"],"answer":3,"explanation":"Invoice price = 1,000 − 100 − 50 = ₹850. Pocket price = 850 − 17 (2% of invoice) − 30 − 40 = ₹763. Stopping at ₹850 ignores the off-invoice leakages that the price waterfall is meant to expose; taking the cash discount on list gives ₹760.","difficulty":"very-hard","source":"Consulting · pricing · MBA placement"},
  {"id":"mgmt-marketing-621","question":"A company's new snack has fixed costs of ₹3 crore a year and a contribution of ₹40 a unit. The category sells 50 lakh units a year. What market share must it win to break even?","options":["15%","7.5%","1.5%","13.3%"],"answer":0,"explanation":"Break-even volume = ₹3,00,00,000 ÷ ₹40 = 7.5 lakh units, which is 7.5/50 = 15% of the market. 7.5% mixes up lakh and share, and 1.5% slips a decimal place.","difficulty":"hard","source":"FMCG MT · MBA placement"},
  {"id":"mgmt-marketing-622","question":"In a price survey, the share of respondents who say they would buy a gadget is 80% at ₹100, 65% at ₹120, 50% at ₹140 and 35% at ₹160. The variable cost is ₹60. Which price maximises revenue and which maximises contribution?","options":["₹100 for both","₹100 for revenue, ₹140 for contribution","₹120 for revenue, ₹140 for contribution","₹140 for both"],"answer":1,"explanation":"Per 100 respondents, revenue is 8,000, 7,800, 7,000, 5,600 (max at ₹100); contribution is 40 × 80 = 3,200, 60 × 65 = 3,900, 80 × 50 = 4,000, 100 × 35 = 3,500 (max at ₹140). Revenue maximisation ignores cost and so prices too low.","difficulty":"very-hard","source":"Pricing · consulting · MBA placement"},
  {"id":"mgmt-marketing-623","question":"A B2B software rep opens meetings by sharing research showing the client is losing money in a way it had not noticed, tailors the message to each stakeholder, and pushes back firmly on price rather than conceding. Which sales approach is this?","options":["Relationship building","Solution selling with a reactive problem-solver","The Challenger approach: teach, tailor and take control","Transactional order taking"],"answer":2,"explanation":"Dixon and Adamson's 'Challenger' reps teach customers new insights about their business, tailor them to each stakeholder and take control of the conversation, including on money. Relationship builders, by contrast, focus on goodwill and tend to concede.","difficulty":"hard","source":"Sales MT · B2B · MBA placement"},
  {"id":"mgmt-marketing-624","question":"An enterprise software firm splits its sales force so that one team only wins new logos and another only manages and grows existing accounts. What is the main risk of this hunter–farmer split, and how is it usually handled?","options":["Hunters lose motivation because they never close deals","Farmers have no way of earning incentives","It removes the need for CRM records","Poor hand-offs: hunters may oversell or pass on badly set-up accounts, so firms use structured transition plans and give hunters a stake in early retention"],"answer":3,"explanation":"The split lets each team specialise, but the hand-off is the weak point: a hunter paid only on signing has no reason to care about fit. Shared metrics such as first-year retention and formal transition meetings align the two.","difficulty":"hard","source":"Sales MT · B2B · MBA placement"},
  {"id":"mgmt-marketing-625","question":"A low-cost entrant launches basic, cheap ultrasound machines that clinics in small towns can afford, while the incumbents keep improving premium machines for big hospitals, which value performance. Over years the entrant's machines improve and win the mainstream. What is this pattern?","options":["Disruptive innovation from the low end","Sustaining innovation","Blue-ocean value innovation with no competitors","Leapfrogging the leader's technology"],"answer":0,"explanation":"Christensen's disruption starts with 'good enough', cheaper products for overlooked or new customers; incumbents, chasing their best customers, ignore the entrant until it improves enough to take the mainstream.","difficulty":"hard","source":"Strategy · marketing MT · MBA placement"},
  {"id":"mgmt-marketing-626","question":"A fashion brand asks website visitors to opt in to weekly style emails in return for early access to sales, and sends nothing to those who decline. Which concept, popularised by Seth Godin, does this reflect?","options":["Interruption marketing","Permission marketing","Viral marketing","Stealth marketing"],"answer":1,"explanation":"Permission marketing sends anticipated, personal and relevant messages to people who have agreed to receive them. Interruption marketing pushes messages at people who did not ask for them, such as TV breaks.","difficulty":"moderate","source":"Digital marketing · MBA placement"},
  {"id":"mgmt-marketing-627","question":"During a cricket tournament, a beverage brand that is not an official sponsor runs ads full of cricket imagery and 'Cheer for India' messages timed to the matches, so many viewers think it is a sponsor. What is this called?","options":["Cause marketing","Surrogate advertising","Ambush marketing","Co-branding"],"answer":2,"explanation":"Ambush marketing links a brand to an event without paying for official sponsorship, often reducing the value of the real sponsor's rights. Events now write anti-ambush clauses and monitor venues closely.","difficulty":"moderate","source":"Marketing MT · MBA placement"},
  {"id":"mgmt-marketing-628","question":"A brand's monthly dashboard tracks market share, revenue, consideration among non-users, trial rate, and share of search. Which of these are leading indicators of future sales rather than lagging ones?","options":["Market share and revenue","Revenue and trial rate","Only market share","Consideration, trial rate and share of search"],"answer":3,"explanation":"Consideration, trial and search interest move before purchases do, so they warn early. Revenue and market share record what has already happened (lagging).","difficulty":"hard","source":"Marketing MT · analytics · MBA placement"},
  {"id":"mgmt-marketing-629","question":"A phone brand finds that '₹2,499 a month for 24 months, no-cost EMI' sells far better than '₹59,999', even though the total paid is about the same. Which consumer tendency explains this most directly?","options":["Present bias: buyers overweight the small immediate cost and underweight future payments","The endowment effect","The decoy effect","Regression to the mean"],"answer":0,"explanation":"Present-biased (hyperbolic) discounting makes the immediate pain of a small monthly amount feel much lighter than a large upfront price, even when the total is similar. EMI framing reduces the immediate 'pain of paying'.","difficulty":"hard","source":"Marketing MT · consumer behaviour · MBA placement"},
  {"id":"mgmt-marketing-630","question":"A brand manager wants to know (a) the brand's sell-out and stock levels across grocery outlets, and (b) whether the brand's buyers are new households or the same households buying more. Which data source suits each?","options":["Consumer panel for both","Retail audit for (a), consumer household panel for (b)","Consumer panel for (a), retail audit for (b)","Ex-factory sales data for both"],"answer":1,"explanation":"Retail audits measure what stores sell and stock (distribution, out-of-stock, sell-out). Household panels follow the same households over time, so they reveal penetration, repeat rate and switching. Ex-factory data show pipeline shipments, not consumer buying.","difficulty":"hard","source":"FMCG MT · market research · MBA placement"},
  {"id":"mgmt-marketing-631","question":"Brand A's price is cut by ₹10 for a month. Its normal contribution is ₹30 a unit and normal sales are 5,000 units; on promotion it sells 7,000. Sister brand B (₹35 contribution) loses 600 units, and complementary product C (₹20 contribution) gains 300. What is the promotion's net effect on the company's contribution?","options":["A gain of ₹45,000","A gain of ₹25,000","A loss of ₹25,000","A loss of ₹10,000"],"answer":2,"explanation":"A: 7,000 × ₹20 − 5,000 × ₹30 = −₹10,000, because the discount is also given on the 5,000 units that would have sold anyway. Add −600 × ₹35 = −₹21,000 and +300 × ₹20 = +₹6,000: net −₹25,000. +₹45,000 ignores the discount and +₹25,000 applies it only to the extra units.","difficulty":"very-hard","source":"FMCG MT · trade marketing · MBA placement"},
  {"id":"mgmt-marketing-632","question":"An industrial-goods firm pays reps commission on revenue, and reps routinely give the maximum allowed discount to close deals faster. What change would best align their behaviour with company profit?","options":["Raise the commission rate on revenue","Pay a higher fixed salary and no incentive","Cap the number of deals each rep can close","Pay commission on gross margin, so a discount also reduces the rep's payout"],"answer":3,"explanation":"On revenue-based pay, a 10% discount costs the rep only 10% of the commission but can wipe out much of the company's margin. Margin-based commission makes the rep share the cost of discounting.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-633","question":"A streaming app's monthly plan costs ₹500, charged at the start of each month, and 6% of subscribers cancel at the end of every month. What is the expected revenue in the first 12 months from a new monthly subscriber?","options":["About ₹4,367","₹6,000","About ₹3,840","About ₹2,855"],"answer":0,"explanation":"Expected revenue = 500 × (1 + 0.94 + 0.94² + … + 0.94¹¹) = 500 × (1 − 0.94¹²)/0.06 ≈ ₹4,367. So an annual prepaid plan at ₹5,000 earns more than a 'cheaper-looking' monthly plan. ₹6,000 ignores churn; ₹3,840 assumes churn falls linearly.","difficulty":"very-hard","source":"Digital marketing · subscription · MBA placement"},
  {"id":"mgmt-marketing-634","question":"An exporter's ex-factory price is ₹100. Freight and insurance add ₹20; the importing country charges 10% duty on the landed (CIF) value; the importer adds a 20% markup and the retailer a 40% markup, each on its own cost. What is the shelf price abroad?","options":["₹168.00","₹221.76","₹218.40","₹211.20"],"answer":1,"explanation":"CIF ₹120 + duty ₹12 = ₹132; × 1.2 = ₹158.40; × 1.4 = ₹221.76. Ignoring freight and duty gives ₹168; charging duty on ex-factory value gives ₹218.40; adding the two markups (60%) instead of compounding them gives ₹211.20. This is price escalation.","difficulty":"very-hard","source":"International marketing · MBA placement"},
  {"id":"mgmt-marketing-635","question":"Studies of customer complaint behaviour (such as the TARP studies) found a pattern that changes how firms read low complaint counts. Which statement reflects it?","options":["Most dissatisfied customers complain, so complaint counts track dissatisfaction well","Complaining customers are the least likely to buy again, whatever is done","Most dissatisfied customers never complain, but those whose complaints are resolved well are often more loyal than those who never had a problem","Customers complain more about cheap products than expensive ones"],"answer":2,"explanation":"Only a small share of unhappy customers complain; the rest leave quietly and tell others. A complaint is therefore a chance to recover, and quick, good resolution greatly raises repurchase intention.","difficulty":"hard","source":"Services marketing · MBA placement"},
  {"id":"mgmt-marketing-636","question":"A sales team has 100 qualified opportunities with an average deal size of ₹2 lakh, a 25% win rate and an average sales cycle of 50 days. What is its pipeline velocity in expected won revenue per 30 days?","options":["₹1 lakh","₹50 lakh","₹120 lakh","₹30 lakh"],"answer":3,"explanation":"Velocity = (100 × ₹2 lakh × 25%) ÷ 50 days = ₹1 lakh a day, i.e. ₹30 lakh per 30 days. ₹1 lakh is the daily figure, ₹50 lakh ignores the cycle length, and ₹120 lakh drops the win rate.","difficulty":"hard","source":"Sales MT · MBA placement"},
  {"id":"mgmt-marketing-637","question":"A buyer scores three laptops 1–10 on price, battery and weight, in that order of importance. A: 8, 5, 9. B: 8, 7, 3. C: 6, 9, 8. Which laptop does a lexicographic rule pick, and which survive a conjunctive rule requiring at least 5 on every attribute?","options":["B; A and C","A; A and C","B; all three","C; A only"],"answer":0,"explanation":"Lexicographic: A and B tie on price (8), so the next attribute, battery, decides: B (7 vs 5). Conjunctive: B fails weight (3), so A and C survive. Breaking the tie on weight wrongly gives A.","difficulty":"very-hard","source":"Marketing MT · consumer behaviour · MBA placement"},
  {"id":"mgmt-marketing-638","question":"Interviews show many morning commuters buy a thick milkshake not for taste but because it lasts the boring drive and keeps them full till lunch. A product team uses this to compete with bananas and bagels rather than other shakes. Which framework is this?","options":["Maslow's hierarchy","Jobs to be done","The Kano model","The FCB grid"],"answer":1,"explanation":"Christensen's jobs-to-be-done asks what 'job' the customer hires a product for; the real competitors are whatever else does that job. The milkshake case is the standard illustration.","difficulty":"hard","source":"Product management · marketing MT · MBA placement"},
  {"id":"mgmt-marketing-639","question":"A telecom firm builds a model to target a retention offer. Which customers should it target to get the most incremental retention per rupee?","options":["Those most likely to churn, whether or not the offer changes their minds","Those least likely to churn","Those whose churn probability falls most because of the offer (the 'persuadables'), avoiding 'sure things' and 'sleeping dogs' who react badly to contact","Every customer equally"],"answer":2,"explanation":"Uplift modelling targets the difference the offer makes, not churn risk alone. Some high-risk customers leave anyway ('lost causes'), loyal ones stay anyway ('sure things'), and some are prompted to leave by contact ('sleeping dogs').","difficulty":"very-hard","source":"Marketing analytics · consulting · MBA placement"},
  {"id":"mgmt-marketing-640","question":"Narver and Slater describe market orientation as having three behavioural components. Which set is correct?","options":["Product, price and promotion orientation","Production, selling and societal orientation","Profitability, long-term focus and innovation","Customer orientation, competitor orientation and inter-functional coordination"],"answer":3,"explanation":"Narver and Slater's model has customer orientation, competitor orientation and inter-functional coordination, with long-term focus and profitability as decision criteria. The other options mix up marketing philosophies and the marketing mix.","difficulty":"hard","source":"Marketing MT · MBA placement"},
  {"id":"mgmt-marketing-641","question":"A company's CMO commissions an independent, periodic review of the firm's entire marketing environment, objectives, strategies and activities, to find problems and opportunities. Which type of marketing control is this?","options":["Strategic control through a marketing audit","Annual-plan control","Profitability control","Efficiency control"],"answer":0,"explanation":"A marketing audit is comprehensive, systematic, independent and periodic, and it is the main tool of strategic control. Annual-plan control checks sales and share against plan; profitability and efficiency control look at products, channels and spending.","difficulty":"hard","source":"Marketing MT · MBA placement"},
  {"id":"mgmt-marketing-642","question":"An appliance maker switches from rail to air freight for spare parts. Transport costs rise sharply, but the firm can close three regional warehouses and hold far less stock. Which logistics principle should guide the decision?","options":["Always choose the cheapest transport mode","The total cost concept: compare transport, inventory, warehousing and lost-sales costs together","Minimise inventory at any cost","Postpone all decisions to the distributor"],"answer":1,"explanation":"Logistics costs trade off against each other; faster, dearer transport can lower inventory carrying, warehousing and stock-out costs by more than it adds. Only the total, together with service levels, should decide.","difficulty":"hard","source":"Sales and distribution · MBA placement"},
  {"id":"mgmt-marketing-643","question":"A pharmacy chain starts selling greeting cards, snacks, toys and phone accessories alongside medicines, items unrelated to its core line, because they have high margins and impulse appeal. What is this called?","options":["Category management","Private labelling","Scrambled merchandising","Category killing"],"answer":2,"explanation":"Scrambled merchandising means a retailer adding unrelated product lines to raise traffic and margins. It blurs traditional retail boundaries and creates new competitors for specialist stores.","difficulty":"moderate","source":"Retail MT · MBA placement"},
  {"id":"mgmt-marketing-644","question":"A business-software firm wins not by being cheapest or most innovative but by learning each client's processes in depth and tailoring solutions so closely that switching becomes unattractive. In Treacy and Wiersema's value disciplines, which discipline is it pursuing?","options":["Operational excellence","Customer intimacy","Product leadership","Cost leadership"],"answer":1,"explanation":"Treacy and Wiersema's three disciplines are operational excellence (lowest total cost and hassle), product leadership (best products) and customer intimacy (tailoring to specific customers). Cost leadership is Porter's term, not one of the three.","difficulty":"hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-645","question":"Consider these statements about findings from the PIMS (Profit Impact of Market Strategy) database:\nI. Market share is strongly and positively associated with return on investment.\nII. Relative perceived quality is positively associated with profitability.\nIII. High investment intensity tends to raise ROI.\nWhich are correct?","options":["I and III only","II and III only","I, II and III","I and II only"],"answer":3,"explanation":"PIMS found that higher market share and higher relative quality go with higher ROI. Heavy investment intensity (investment relative to sales) was found to depress ROI, so III is false.","difficulty":"hard","source":"UGC NET Management · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-646","question":"A gym chain's members are identical, each with monthly demand for classes q = 100 − P (P in ₹ per class), and each class costs the chain ₹20 to run. Using a profit-maximising two-part tariff (membership fee plus per-class price), what should it charge?","options":["₹60 per class and no membership fee","₹60 per class plus an ₹800 membership fee","₹20 per class plus a ₹3,200 membership fee","₹20 per class plus a ₹4,000 membership fee"],"answer":2,"explanation":"Set the usage price at marginal cost (₹20), so each member takes 80 classes, and capture the whole consumer surplus as the fee: ½ × 80 × 80 = ₹3,200. A single price of ₹60 earns only ₹1,600; ₹4,000 is the area up to ₹100 without netting the ₹20 cost.","difficulty":"very-hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-647","question":"A subscription box earns ₹500 of contribution per customer per month, collected at the start of each month. After every month 5% of remaining customers cancel. If the firm wants each customer's expected contribution in the first 12 months to cover the acquisition cost, what is the maximum CAC it can afford (to the nearest rupee)?","options":["₹4,367","₹6,000","₹4,596","₹10,000"],"answer":2,"explanation":"Expected 12-month contribution = 500 × (1 + 0.95 + … + 0.95¹¹) = 500 × (1 − 0.95¹²)/0.05 ≈ ₹4,596. ₹4,367 wrongly applies churn before the first month, ₹6,000 ignores churn and ₹10,000 is the full lifetime value 500/0.05.","difficulty":"very-hard","source":"MBA placement (Marketing) · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-648","question":"When Brand A raises its price from ₹50 to ₹55, monthly sales of rival Brand B rise from 2,000 to 2,120 units, other things equal. What is the cross-price elasticity of B with respect to A's price, and what does it show?","options":["+0.6, so A and B are substitutes","−0.6, so A and B are complements","+1.67, so A and B are substitutes","+0.6, so A and B are complements"],"answer":0,"explanation":"Cross elasticity = %ΔQ_B ÷ %ΔP_A = 6% ÷ 10% = +0.6. A positive value means a price rise for A pushes buyers to B, so they are substitutes; complements have a negative cross elasticity. 1.67 inverts the ratio.","difficulty":"moderate","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-649","question":"An advertising doctrine says every ad should make one specific claim, one that competitors cannot or do not offer, and that is strong enough to pull new customers, such as 'melts in your mouth, not in your hand'. Whose idea is this?","options":["Rosser Reeves' unique selling proposition","Ries and Trout's positioning concept","Russell Colley's DAGMAR approach","David Ogilvy's brand-image approach"],"answer":0,"explanation":"Rosser Reeves defined the USP as a single, unique and compelling product claim. Ries and Trout focused on owning a position in the prospect's mind, and Colley's DAGMAR is about setting measurable communication goals.","difficulty":"moderate","source":"Bank SO (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-650","question":"In lab studies, consumers shown an unfamiliar brand logo many times, without any message or claim and without remembering the exposures, later rate it more favourably than logos shown once. Which effect is this?","options":["Sleeper effect","Mere-exposure effect","Halo effect","Stimulus discrimination"],"answer":1,"explanation":"Zajonc's mere-exposure effect says repeated exposure alone increases liking, even without conscious recall. The sleeper effect concerns a low-credibility message gaining persuasiveness over time as its source is forgotten.","difficulty":"hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-651","question":"A researcher asks consumers to collect pictures from magazines that express how they feel about their car, then uses in-depth interviews around those images to uncover deep metaphors and build a consensus map. Which technique is this?","options":["Kelly's repertory grid technique","Conjoint analysis of trade-offs","ZMET (Zaltman's metaphor technique)","Semantic differential scaling"],"answer":2,"explanation":"ZMET (Gerald Zaltman) uses consumer-chosen images and guided interviews to surface unconscious thoughts and metaphors. A semantic differential rates objects on bipolar adjective scales and does not use pictures or metaphors.","difficulty":"hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-652","question":"Respondents are shown an ambiguous drawing of a woman standing in a supermarket aisle holding a product and asked to write a story about what is happening and how she feels. Which research technique is being used?","options":["Word association test","Thematic Apperception Test (TAT)","Sentence completion test","Third-person (role-playing) technique"],"answer":1,"explanation":"In a TAT, people interpret an ambiguous picture by telling a story, projecting their own motives onto it. Word association asks for the first word that comes to mind, and sentence completion asks people to finish incomplete sentences.","difficulty":"hard","source":"UGC NET Management · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-653","question":"To measure attitudes towards online banking, a researcher writes about 100 statements, has a panel of judges sort them into 11 piles from most unfavourable to most favourable, uses the median pile as each statement's scale value and keeps about 20 statements with low disagreement among judges. Respondents then tick the statements they agree with. Which scale is this?","options":["Likert summated rating scale","Guttman cumulative (scalogram) scale","Stapel unipolar rating scale","Thurstone equal-appearing interval scale"],"answer":3,"explanation":"Thurstone scaling uses judges to give each statement a scale value; a respondent's score is the mean (or median) of the values of statements endorsed. A Likert scale has respondents rate agreement with every item and sums the ratings, with no judges.","difficulty":"very-hard","source":"UGC NET Management"},
  {"id":"mgmt-marketing-654","question":"A motorcycle maker's researchers spend months reading and analysing conversations in online riders' forums and social groups, without revealing themselves or interfering, to understand the community's values and language. This is:","options":["Netnography","A focus group","Mystery shopping","A consumer panel"],"answer":0,"explanation":"Netnography (Kozinets) adapts ethnography to online communities, studying naturally occurring discussions. A focus group is a moderated discussion the researcher convenes, and a consumer panel records purchases over time.","difficulty":"moderate","source":"MBA placement (Marketing)"},
  {"id":"mgmt-marketing-655","question":"A snack company invites the public to submit and vote on new flavour ideas through an online contest, launches the winning flavour and rewards its creator. Which approach to new-product ideas is this?","options":["Crowdsourcing","Lead-user research","Reverse engineering","Concept testing"],"answer":0,"explanation":"Crowdsourcing outsources idea generation and selection to a large, open group of people. Lead-user research seeks out a few advanced users who are already innovating, and concept testing evaluates ideas the firm has already developed.","difficulty":"moderate","source":"MBA placement (Marketing)"},
  {"id":"mgmt-marketing-656","question":"A fashion retailer sells through stores, a website and an app. Customers can buy online and return in any store, see store stock on the app, and keep one loyalty account and cart across all channels. What best describes this, as distinct from a multichannel approach?","options":["Multichannel retailing, running each channel as a separate profit centre","Showrooming, where shoppers inspect in store and then buy online cheaper","Dual distribution, selling both directly and through independent dealers","Omnichannel retailing, integrating channels into one seamless customer experience"],"answer":3,"explanation":"Multichannel simply offers several channels, often run in silos; omnichannel integrates inventory, data and service so the customer moves freely between them. Showrooming is a shopper behaviour, not a retailer strategy.","difficulty":"hard","source":"MBA placement (Marketing)"},
  {"id":"mgmt-marketing-657","question":"According to Prahalad and Hamel, which three tests identify a core competence?","options":["It gives access to many markets, adds much to perceived customer benefit and is hard to imitate","It is the firm's largest business, has the highest margin and has a strong brand","It is valuable, rare, inimitable and organised, as in the VRIO framework","It is protected by patents, needs heavy capital and enjoys scale economies"],"answer":0,"explanation":"Prahalad and Hamel's core competence provides potential access to a wide variety of markets, contributes significantly to the benefits customers perceive in end products and is difficult for competitors to imitate. VRIO is Barney's resource-based test.","difficulty":"hard","source":"UGC NET Management · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-658","question":"A store plans an initial markup of 40% on retail. It expects reductions (markdowns, shrinkage and employee discounts) equal to 10% of net sales. What maintained markup (on net sales) should it expect?","options":["30%","34%","36%","40%"],"answer":1,"explanation":"Initial markup % = (maintained markup % + reductions %) ÷ (100% + reductions %), so MMU = 0.40 × 1.10 − 0.10 = 34%. Simply subtracting 10 points (30%) forgets that the initial markup was set on a retail base that included the reductions.","difficulty":"very-hard","source":"MBA placement (Marketing) · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-659","question":"Lovelock classifies services by whether the act is tangible or intangible and whether it is directed at people or at possessions. A tax-preparation and investment-advisory service, which works intangibly on customers' assets and data, is which type?","options":["People processing","Possession processing","Mental-stimulus processing","Information processing"],"answer":3,"explanation":"Tangible acts on people's bodies are people processing (haircuts), tangible acts on things are possession processing (repairs), intangible acts on minds are mental-stimulus processing (education), and intangible acts on intangible assets are information processing (accounting, banking).","difficulty":"very-hard","source":"UGC NET Management · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-660","question":"A month-long TV campaign gives this exposure distribution in the target audience: 0 exposures 25%, 1 exposure 20%, 2 exposures 18%, 3 exposures 15%, 4 exposures 12%, 5 or more 10%. If the planner treats 3+ exposures as effective, what is the effective reach?","options":["75%","55%","37%","22%"],"answer":2,"explanation":"Effective reach counts those exposed at least three times: 15% + 12% + 10% = 37%. 75% is ordinary (1+) reach, 55% is 2+ reach and 22% is 4+ reach.","difficulty":"hard","source":"MBA placement (Marketing) · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-661","question":"A display campaign costs ₹48,000 for 8,00,000 served impressions, of which 60% meet the viewability standard. What is its cost per thousand viewable impressions (vCPM)?","options":["₹60","₹36","₹150","₹100"],"answer":3,"explanation":"Viewable impressions = 0.6 × 8,00,000 = 4,80,000, so vCPM = 48,000 ÷ 480 = ₹100. ₹60 is the CPM on all served impressions; ₹36 multiplies instead of dividing by the viewable share.","difficulty":"hard","source":"MBA placement (Marketing)"},
  {"id":"mgmt-marketing-662","question":"Match each item with its media type.\nA. A brand's own mobile app and website\nB. Customer reviews and news stories about the brand\nC. Sponsored posts and search ads\n1. Paid media  2. Owned media  3. Earned media","options":["A-1, B-3, C-2","A-2, B-1, C-3","A-2, B-3, C-1","A-3, B-2, C-1"],"answer":2,"explanation":"Owned media are channels the brand controls (its app and site), earned media is coverage others give it (reviews, press, shares) and paid media is space bought (ads, sponsored posts).","difficulty":"moderate","source":"MBA placement (Marketing)"},
  {"id":"mgmt-marketing-663","question":"A sportswear brand's ads always show the same stereotyped user: young, lean, competitive and successful. In Kapferer's brand identity prism, which facet is this portrayed image of the typical user?","options":["Self-image","Reflection","Personality","Culture"],"answer":1,"explanation":"Reflection is the outward image of the typical user that the brand projects. Self-image is the buyer's inner picture of himself when using the brand, personality is the brand's own character, and culture is its value system and origins.","difficulty":"very-hard","source":"UGC NET Management"},
  {"id":"mgmt-marketing-664","question":"Keller says brand associations create a differentiated response only when they have three characteristics. Which set is correct?","options":["Awareness, recall and recognition","Relevance, esteem and knowledge","Strength, favourability and uniqueness","Salience, imagery and resonance"],"answer":2,"explanation":"Keller's brand image depends on associations that are strong, favourable and unique. Relevance, esteem and knowledge come from Young & Rubicam's BAV, and salience and resonance are levels of his own CBBE pyramid.","difficulty":"hard","source":"UGC NET Management · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-665","question":"An analyst plots car makers on two axes, price level and breadth of model range, and finds three clusters: premium narrow-range makers, mass full-line makers and budget small-car specialists. Firms in each cluster compete hard with one another but little with other clusters. What concept is this?","options":["Strategic groups","Perceptual mapping","Market segmentation","Product-line stretching"],"answer":0,"explanation":"Strategic groups are firms in an industry following similar strategies on key dimensions; rivalry is strongest within a group, and mobility barriers protect each group. A perceptual map plots brands as customers see them, not firms' strategies.","difficulty":"hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-666","question":"Young college students in a town avoid a scooter brand because it is strongly linked in their minds with a group of older, conservative riders they do not want to be associated with. For these students, that group is a:","options":["Aspirational group","Dissociative group","Primary membership group","Formal secondary group"],"answer":1,"explanation":"A dissociative group is one whose values or behaviour a person rejects and wants to avoid being identified with, so brands linked to it lose appeal. An aspirational group is one the person wants to join, which pulls toward a brand instead.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-667","question":"Daniel Katz's functional theory says attitudes serve different needs. A consumer insists on a well-known luxury pen mainly to show colleagues that he values achievement and refinement. Which attitude function is mainly at work?","options":["Utilitarian function","Ego-defensive function","Knowledge function","Value-expressive function"],"answer":3,"explanation":"Value-expressive attitudes let a person express central values and self-concept. Utilitarian attitudes rest on rewards and costs, ego-defensive ones protect against threats to self-image, and the knowledge function provides order and meaning.","difficulty":"very-hard","source":"UGC NET Management"},
  {"id":"mgmt-marketing-668","question":"A junior manager stretches her budget to buy the same premium watch her CEO wears, explaining that it reflects the kind of leader she is working to become rather than who she is today. Which self-concept is the purchase mainly serving?","options":["Actual self-image","Social self-image","Ideal self-image","Looking-glass self"],"answer":2,"explanation":"The ideal self is the person one would like to be, and consumers buy brands whose image matches that aspiration. The actual self is how she sees herself now, and the social self is how she thinks others currently see her.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-669","question":"Applying Thaler's mental-accounting principles from prospect theory, how should a car dealer present a deal that includes three free accessories and a set of separate fees?","options":["Itemise the free accessories separately and fold all the fees into one single price","Bundle the free accessories into one package and list each of the fees separately","Itemise both the free accessories and each fee, so the buyer sees full detail","Bundle both the free accessories and the fees, so the buyer sees one net figure"],"answer":0,"explanation":"Because the value function is concave for gains, several separate gains feel bigger than one combined gain; because it is convex for losses, one combined loss hurts less than several separate ones. So segregate gains and integrate losses.","difficulty":"very-hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-670","question":"A software firm's marginal cost per licence is ₹60. Students have a constant price elasticity of −4 and professionals −1.5, and resale between the groups is impossible. What profit-maximising prices should it set?","options":["Students ₹180 and professionals ₹80","Students ₹75 and professionals ₹100","Students ₹80 and professionals ₹90","Students ₹80 and professionals ₹180"],"answer":3,"explanation":"With constant elasticity, P = MC × |e| ÷ (|e| − 1): students 60 × 4/3 = ₹80 and professionals 60 × 1.5/0.5 = ₹180. The less elastic group pays more. ₹75 and ₹100 wrongly use MC × (1 + 1/|e|).","difficulty":"very-hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-671","question":"A cement maker in Gujarat wants to win customers in Maharashtra, where a rival plant is nearby. It charges distant buyers its normal ex-works price but bears part of the freight itself so its delivered price matches the local rival. Which geographic pricing method is this?","options":["FOB-origin pricing","Freight-absorption pricing","Uniform delivered pricing","Zone pricing"],"answer":1,"explanation":"Freight absorption means the seller absorbs some or all freight to meet competition in distant markets. FOB-origin makes the buyer pay all freight; uniform delivered charges every buyer the same price including an average freight.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-672","question":"A small company's owner sets the promotion budget at whatever money is left after covering all operating costs, capital spending and a target profit. Which budgeting method is this, and what is its main weakness?","options":["Percentage of sales; it makes promotion a result of sales rather than a cause","Competitive parity; it assumes rivals know the right level of spending","Affordable method; it ignores promotion's effect on sales and varies erratically","Objective-and-task; it is too costly to research for a small company"],"answer":2,"explanation":"The affordable method treats promotion as a residual, so the budget ignores what promotion could achieve and swings from year to year, making long-range planning hard. Objective-and-task is the most logical method, building the budget up from goals.","difficulty":"moderate","source":"Bank SO (Marketing)"},
  {"id":"mgmt-marketing-673","question":"A coffee brand offers a branded steel mug for ₹149 plus two pack tops; the ₹149 fully covers the mug's cost, packing and postage. What is this promotion called?","options":["A self-liquidating premium","An in-pack premium","A bonus pack","A refund (rebate) offer"],"answer":0,"explanation":"A self-liquidating premium is sold to consumers at a price that recovers the marketer's cost, so it costs the brand little. An in-pack premium is given free inside the pack, and a bonus pack adds extra product at the same price.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-674","question":"A direct-mail campaign to 1,00,000 households costs ₹25 per piece for printing and postage plus ₹50,000 for creative work. Each order yields ₹500 of contribution. What response rate does the campaign need to break even?","options":["5.0%","4.9%","19.6%","5.1%"],"answer":3,"explanation":"Total cost = 1,00,000 × 25 + 50,000 = ₹25.5 lakh, needing 25,50,000 ÷ 500 = 5,100 orders, a 5.1% response rate. 5.0% forgets the fixed creative cost, and 19.6% inverts the ratio.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-675","question":"A new 'customer delight' scale correlates 0.78 with an established customer-satisfaction scale and only 0.08 with a scale measuring price consciousness. What do these two results support?","options":["Test–retest and split-half reliability","Convergent and discriminant validity","Content and face validity","Predictive and concurrent validity"],"answer":1,"explanation":"High correlation with a measure of a related construct shows convergent validity; low correlation with an unrelated construct shows discriminant validity, and together they support construct validity. Reliability concerns consistency, not what is measured.","difficulty":"hard","source":"UGC NET Management · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-676","question":"Researchers survey shoppers' awareness of a new detergent, run a campaign, then survey the same shoppers again. Awareness rises sharply, partly because the first survey made respondents notice the brand. Which threat to validity is this?","options":["History effect","Testing (pre-measurement) effect","Mortality effect","Instrumentation effect"],"answer":1,"explanation":"The testing effect arises when an earlier measurement changes how people respond later. History would be an outside event during the study, and mortality is respondents dropping out. A control group or a post-test-only design guards against it.","difficulty":"hard","source":"UGC NET Management · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-677","question":"A firm wants to estimate the share of its 2,000 dealers who would adopt a new ordering app, within ±5 percentage points at 95% confidence, assuming the most conservative proportion. Applying the finite population correction, roughly how many dealers should it survey?","options":["385","400","323","192"],"answer":2,"explanation":"n₀ = 1.96² × 0.25 ÷ 0.05² ≈ 384.2; with N = 2,000, n = n₀ ÷ (1 + (n₀ − 1)/N) ≈ 322.4, so 323. 385 ignores the correction, and 400 uses z = 2.","difficulty":"very-hard","source":"UGC NET Management · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-678","question":"Eight respondents say which of four new flavours they would buy: R1 A, B; R2 A; R3 A, C; R4 B; R5 C, D; R6 D; R7 A, B; R8 B, D. Using TURF analysis, which pair of flavours should the firm launch to maximise unduplicated reach?","options":["A and D, reaching 7 of the 8 respondents","A and B, the two most popular, reaching 6","B and D, reaching 7 of the 8 respondents","A and C, reaching 6 of the 8 respondents"],"answer":0,"explanation":"Counting distinct respondents: A + D reaches R1, R2, R3, R5, R6, R7, R8 = 7; A + B reaches only 6 because A and B buyers overlap heavily; B + D reaches 6 and A + C 5. TURF picks the combination, not the most popular singles.","difficulty":"very-hard","source":"MBA placement (Marketing)"},
  {"id":"mgmt-marketing-679","question":"A bank's customer-profitability analysis finds that its most profitable 20% of customers generate about 150% of total profit, while the least profitable customers destroy enough value to bring the total back to 100%. What is this pattern usually called, and what does it suggest?","options":["The 80/20 rule; serve only the top 20% of customers","The service–profit chain; raise employee satisfaction","Double jeopardy; small brands have fewer and less loyal buyers","The whale curve; fix or reprice unprofitable relationships"],"answer":3,"explanation":"Plotting cumulative profit against customers ranked by profitability gives a whale curve that peaks well above 100%. The usual response is to reprice, change service levels or cut costs for loss-making customers rather than simply abandon them.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-680","question":"A camera brand sells at much lower prices in Southeast Asia than in India. Traders buy genuine units cheaply abroad and resell them in India outside the brand's authorised dealer network, undercutting its dealers. What is this?","options":["Grey-market (parallel) importing","Counterfeiting","Dumping by the manufacturer","Transfer pricing"],"answer":0,"explanation":"Grey-market goods are genuine branded products sold through unauthorised channels, usually exploiting price gaps between countries. Counterfeits are fakes, and dumping is the producer itself selling abroad below its home price or cost.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-681","question":"A Pune engineering firm first exports occasionally through an agent to Sri Lanka, then sets up a sales subsidiary there, and only years later starts production abroad and enters distant markets such as Germany. Which model of internationalisation does this gradual path illustrate?","options":["Porter's diamond model","The born-global model","The Uppsala (stages) model","Vernon's product life-cycle theory"],"answer":2,"explanation":"The Uppsala model says firms internationalise step by step, raising commitment as they learn and entering markets with small 'psychic distance' first. Born-global firms internationalise rapidly from founding instead.","difficulty":"hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-682","question":"A state health department runs a campaign using research, segmentation and a mix of messages, incentives and easier access to persuade rural men to quit smoking, with no product to sell. What is this?","options":["Societal marketing","Cause-related marketing","Demarketing","Social marketing"],"answer":3,"explanation":"Social marketing (Kotler and Zaltman) applies marketing tools to change behaviour for social good. Cause-related marketing ties a firm's sales to donations, and societal marketing is a firm balancing profit with society's long-term welfare.","difficulty":"moderate","source":"Bank SO (Marketing)"},
  {"id":"mgmt-marketing-683","question":"In the relationship-marketing 'ladder of loyalty', which rung comes immediately after a customer who buys repeatedly (a 'client') and before an 'advocate' who actively recommends the firm?","options":["Prospect","Supporter","Partner","Customer"],"answer":1,"explanation":"The ladder runs prospect → customer → client → supporter → advocate → partner. A supporter likes the firm but is passive; an advocate actively recommends it, and a partner works with the firm in a mutual relationship.","difficulty":"hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-684","question":"A biscuit brand that keeps losing sales to look-alike store brands changes its pack to a distinctive shape and colour and runs ads stressing what makes it different, so shoppers stop treating the store brands as equivalent. In learning theory, the brand is encouraging:","options":["Stimulus discrimination","Stimulus generalisation","Operant extinction","Vicarious learning"],"answer":0,"explanation":"Stimulus discrimination is learning to respond differently to similar stimuli. The look-alikes rely on stimulus generalisation, shoppers transferring the brand's associations to similar-looking packs.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-685","question":"In Wells and Gubar's family life cycle, a couple whose youngest child is under six, who have low liquid assets, are dissatisfied with their financial position and buy washers, baby food and medicines, are in which stage?","options":["Newly married couple","Full nest II","Full nest I","Empty nest I"],"answer":2,"explanation":"Full nest I (youngest child under six) brings heavy home purchasing and tight finances. Full nest II (youngest six or over) is financially better off, and newly married couples have no children yet.","difficulty":"hard","source":"Bank SO (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-686","question":"An ad for an insurance plan must present several arguments to a low-involvement audience that will hear it once. According to research on message order, where should the strongest argument usually go?","options":["In the middle, so it is cushioned by weaker points","Anywhere, because order has no effect on recall","Only at the end, because of the primacy effect","At the start or the end, as primacy and recency aid recall"],"answer":3,"explanation":"Arguments at the beginning (primacy) and end (recency) are remembered better than those in the middle; with an uninterested audience, a strong opening helps capture attention. The middle is the weakest position.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-687","question":"A pest-control firm promises: 'If pests return before your next scheduled visit, we re-treat free; if you are still not satisfied, we refund the full fee.' Besides reassuring buyers, what is the main internal benefit Hart identified for such service guarantees?","options":["They let the firm raise prices without any change in operations","They force the firm to define standards and expose service failures","They shift the risk of service failure from the firm to customers","They remove the need for service recovery and complaint handling"],"answer":1,"explanation":"An unconditional guarantee sets clear standards, generates feedback whenever it is invoked and pushes the firm to fix the causes of failure. It shifts risk away from customers, not towards them.","difficulty":"moderate","source":"Bank SO (Marketing)"},
  {"id":"mgmt-marketing-688","question":"A distributed-lag (Koyck) model of advertising gives a short-run sales elasticity with respect to advertising of 0.10 and a carry-over coefficient of 0.6 per period. What is the long-run advertising elasticity?","options":["0.25","0.16","0.06","0.17"],"answer":0,"explanation":"The long-run effect sums the geometric carry-over: 0.10 × (1 + 0.6 + 0.6² + …) = 0.10 ÷ (1 − 0.6) = 0.25. 0.16 adds only one period of carry-over, and 0.17 divides by 0.6 instead of by 0.4.","difficulty":"very-hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-689","question":"A shampoo's MRP of ₹118 includes 18% GST. The retailer earns 15% on its pre-tax selling price, and the distributor earns 8% on its own pre-tax selling price. What pre-tax price does the manufacturer get from the distributor?","options":["₹92.28","₹77.00","₹80.52","₹78.20"],"answer":3,"explanation":"Pre-tax retail price = 118 ÷ 1.18 = ₹100. Retailer buys at 100 × 0.85 = ₹85, and the distributor buys at 85 × 0.92 = ₹78.20. ₹92.28 forgets to strip out GST, and ₹80.52 treats the margins as markups on cost.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-690","question":"A new brand of packaged water has fixed costs of ₹6 crore a year, a price of ₹100 a case and variable cost of ₹70 a case. The category sells 4 crore cases a year. What market share does the brand need to break even?","options":["1.5%","2.1%","5.0%","20.0%"],"answer":2,"explanation":"Break-even volume = 6,00,00,000 ÷ 30 = 20 lakh cases, which is 20 lakh ÷ 4 crore = 5% of the market. Dividing fixed cost by price (1.5%) or by variable cost (2.1%) uses the wrong per-unit figure.","difficulty":"hard","source":"MBA placement (Marketing) · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-691","question":"A brand sells at ₹100 with a variable cost of ₹60. A raw-material rise lifts variable cost to ₹66, and the firm keeps the price unchanged. By roughly what percentage must unit volume rise to keep total contribution the same?","options":["10.0%","17.6%","15.0%","6.0%"],"answer":1,"explanation":"Contribution per unit falls from ₹40 to ₹34, so volume must rise by 40 ÷ 34 − 1 ≈ 17.6%. 15% divides the ₹6 rise by the old contribution, and 10% is the rise in variable cost itself.","difficulty":"hard","source":"MBA placement (Marketing) · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-692","question":"A firm sells two products in a fixed unit mix of 60% A and 40% B. A earns a contribution of ₹40 a unit and B ₹20 a unit, and fixed costs are ₹16 lakh a year. What is the break-even volume?","options":["53,334 units: 32,000 of A and 21,334 of B","50,000 units: 30,000 of A and 20,000 of B","40,000 units: 24,000 of A and 16,000 of B","80,000 units: 48,000 of A and 32,000 of B"],"answer":1,"explanation":"Weighted contribution = 0.6 × 40 + 0.4 × 20 = ₹32, so break-even = 16,00,000 ÷ 32 = 50,000 units, split 30,000 A and 20,000 B. A simple average of ₹30 ignores the mix, and dividing by ₹40 or ₹20 uses one product only.","difficulty":"hard","source":"MBA placement (Marketing) · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-693","question":"A buyer will shortlist any smartphone that is outstanding on at least one attribute she cares about, either a camera score of 9+ or a battery score of 9+, whatever its other scores. Which decision rule is she using?","options":["Conjunctive rule","Lexicographic rule","Compensatory rule","Disjunctive rule"],"answer":3,"explanation":"A disjunctive rule accepts an option that clears a high cut-off on any one attribute. A conjunctive rule needs minimum cut-offs on all attributes, and a lexicographic rule ranks on the most important attribute first, using others only to break ties.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-694","question":"A hotel's core benefit is rest, its basic product is a room with a bed, its expected product includes clean towels and working lights, and its augmented product adds free airport transfers. In Kotler's five product levels, a future smart room that adjusts lighting and temperature to each guest's habits belongs to which level?","options":["Augmented product","Expected product","Potential product","Generic product"],"answer":2,"explanation":"The potential product covers all possible future augmentations and transformations. The augmented product is what the firm offers beyond expectations today, which over time becomes the expected product.","difficulty":"moderate","source":"Bank SO (Marketing)"},
  {"id":"mgmt-marketing-695","question":"Bitner's servicescape framework groups the physical environment into three dimensions. Which set is correct?","options":["Ambient conditions; spatial layout and functionality; signs, symbols and artefacts","Tangibles; reliability; responsiveness","Lighting and colour; music and scent; staff uniforms and manners","Location; store size; parking and access"],"answer":0,"explanation":"Bitner's servicescape covers ambient conditions (temperature, noise, music, scent), spatial layout and functionality, and signs, symbols and artefacts. Tangibles, reliability and responsiveness are SERVQUAL dimensions, not servicescape.","difficulty":"very-hard","source":"UGC NET Management · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-696","question":"A hotel is fully booked for tonight. Each empty room caused by a no-show loses ₹6,000, while each guest turned away because of overbooking costs ₹3,000 in compensation. No-shows follow this distribution: 0 (10%), 1 (20%), 2 (20%), 3 (20%), 4 (30%). How many rooms should it overbook?","options":["2","4","1","3"],"answer":3,"explanation":"Critical ratio = cost of an empty room ÷ (empty-room cost + walk cost) = 6,000 ÷ 9,000 ≈ 0.67. Cumulative probabilities are 0.1, 0.3, 0.5, 0.7, 1.0, so the smallest overbooking with cumulative probability ≥ 0.67 is 3. Using 3,000 ÷ 9,000 by mistake gives 2.","difficulty":"very-hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-697","question":"An automobile maker invites pre-qualified suppliers to an online event in which they bid the price down in real time for a year's supply of seat fabric, and the lowest bid wins. What is this?","options":["A reverse auction","A Dutch auction","A sealed-bid auction","An English auction"],"answer":0,"explanation":"In a reverse auction sellers compete by lowering prices for one buyer's requirement. In an English auction buyers bid prices up, and a Dutch auction starts high and drops until a buyer accepts.","difficulty":"moderate","source":"MBA placement (Marketing)"},
  {"id":"mgmt-marketing-698","question":"A burger chain advertises 'the world's most delicious burger'. A regulator declines to treat the claim as misleading. What is the most likely reason?","options":["It is puffery: vague praise that no reasonable consumer reads as a measurable claim","It is a superlative, which is allowed once the chain proves it is the market leader","It names no rival brand, so it cannot be treated as disparaging any competitor","It is a claim about taste, and taste claims fall outside consumer-protection law"],"answer":0,"explanation":"Puffery is subjective, unmeasurable praise that a reasonable consumer would not take as fact, so it is generally permitted. The market-leader option is tempting, but sales leadership is a separate factual claim and does not prove a burger is the most delicious; taste claims stated as specific facts still need substantiation.","difficulty":"hard","source":"Bank SO (Marketing)"},
  {"id":"mgmt-marketing-699","question":"Prentice classified sales promotions as consumer franchise-building (CFB) or non-franchise-building. Which of these is generally a CFB promotion?","options":["A deep temporary price-off on the shelf","Free samples that let people experience the product","A 'buy two, get one free' deal on the pack","A trade allowance for extra retail display"],"answer":1,"explanation":"CFB promotions reinforce the brand's position and build its image along with selling, as samples, informative coupons and premiums related to the product do. Price-offs, bonus deals and trade allowances push sales without building brand understanding.","difficulty":"very-hard","source":"UGC NET Management · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-700","question":"A printer maker tells dealers they may sell its popular printers only if they also buy and stock its own brand of copier paper. What is this practice called?","options":["Exclusive dealing","Tying (a tie-in arrangement)","Full-line forcing","Resale price maintenance"],"answer":1,"explanation":"Tying makes the sale of a wanted product conditional on buying a separate product, and competition law may challenge it where the seller has market power. Exclusive dealing bars dealers from carrying rivals' brands; full-line forcing requires the whole line of the same product category.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-701","question":"A passenger's flight is delayed. Following Weiner's attribution theory, in which case is she most likely to be angry and to complain or switch airlines?","options":["She blames the airline, sees delays as recurring and thinks the airline could prevent them","She blames the weather, sees it as a one-off and thinks nobody could prevent it","She blames airport congestion, a one-off that the airline could not have controlled","She blames herself for booking a tight connection that she could have avoided"],"answer":0,"explanation":"Weiner's three dimensions are locus, stability and controllability. Dissatisfaction is strongest when the failure is attributed to the firm, seen as likely to recur and judged within the firm's control.","difficulty":"very-hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-702","question":"A user types 'buy running shoes size 9 online' into a search engine. A second types 'how to choose running shoes for flat feet', and a third types the brand name 'Nike' to reach its site. Which classification of search intent fits them, in order?","options":["Informational, transactional, navigational","Navigational, informational, transactional","Transactional, navigational, informational","Transactional, informational, navigational"],"answer":3,"explanation":"Transactional queries signal intent to buy, informational queries seek knowledge, and navigational queries aim to reach a specific site. Bidding strategy and landing pages should differ for each.","difficulty":"hard","source":"MBA placement (Marketing)"},
  {"id":"mgmt-marketing-703","question":"Pine and Gilmore classify experiences by customer participation (passive or active) and connection (absorption or immersion). A guided trekking holiday where visitors actively take part and are fully immersed in the setting belongs to which realm?","options":["Entertainment","Educational","Escapist","Esthetic"],"answer":2,"explanation":"Passive + absorption is entertainment, active + absorption is educational, passive + immersion is esthetic, and active + immersion is escapist, the realm of theme parks, adventure travel and immersive games.","difficulty":"very-hard","source":"UGC NET Management"},
  {"id":"mgmt-marketing-704","question":"A campaign costing ₹20 lakh generates ₹1.2 crore of incremental revenue at a 30% gross margin. What is its return on marketing investment (ROMI)?","options":["500%","180%","80%","600%"],"answer":2,"explanation":"ROMI = (incremental gross margin − spend) ÷ spend = (36 − 20) ÷ 20 = 80%. 500% and 600% use revenue instead of margin, and 180% forgets to subtract the spend.","difficulty":"hard","source":"MBA placement (Marketing) · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-705","question":"Jones and Sasser's study of satisfaction and loyalty found that in competitive markets, customers who rate themselves 'satisfied' (4 on a 5-point scale) are:","options":["Almost as loyal as those who are 'completely satisfied'","Far less loyal than those who are 'completely satisfied'","More loyal than completely satisfied ones, who seek novelty","No more loyal than customers who are dissatisfied"],"answer":1,"explanation":"Jones and Sasser ('Why Satisfied Customers Defect') showed a steep jump in loyalty only at complete satisfaction; merely satisfied customers defect readily in competitive markets, so firms should aim at complete satisfaction.","difficulty":"hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-706","question":"After she learns she is pregnant, a woman suddenly notices baby-product ads, pram displays and nappy promotions that she had walked past for years without registering. Which perceptual process explains this?","options":["Perceptual defence","Selective retention","Perceptual vigilance","Subliminal perception"],"answer":2,"explanation":"Perceptual vigilance is the tendency to notice stimuli relevant to current needs. Perceptual defence screens out threatening stimuli, and selective retention is remembering information that supports existing beliefs.","difficulty":"hard","source":"Bank SO (Marketing)"},
  {"id":"mgmt-marketing-707","question":"In a face-to-face survey, 70% of respondents say they read the newspaper's editorial page daily, but page-level reading measurements suggest the true figure is about 20%. Which error most likely explains the gap?","options":["Non-response bias","Sampling frame error","Social desirability bias","Interviewer cheating"],"answer":2,"explanation":"Respondents over-report behaviour that makes them look good, especially when answering a person face to face. Non-response bias comes from who does not answer, and frame error from an unrepresentative list.","difficulty":"hard","source":"UGC NET Management · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-708","question":"A television maker pays retail showroom salespeople ₹500 for every unit of its premium model they sell. What is this trade-promotion tool called?","options":["Push money (spiff)","Slotting allowance","Co-operative advertising","Buy-back allowance"],"answer":0,"explanation":"Push money (or a spiff) is a cash incentive paid to dealers' salespeople to push a particular product. Slotting allowances buy shelf space, and co-operative advertising shares the retailer's ad costs.","difficulty":"moderate","source":"Bank SO (Marketing)"},
  {"id":"mgmt-marketing-709","question":"A marketing head checks whether each product, territory and channel is making or losing money, using allocated costs from the accounts. In Kotler's four types of marketing control, which is this?","options":["Annual-plan control","Profitability control","Efficiency control","Strategic control"],"answer":1,"explanation":"Profitability control measures the profit of products, territories, segments and channels. Annual-plan control checks results against plan (sales, share), efficiency control improves the spending efficiency of sales force and ads, and strategic control reviews overall fit, as in a marketing audit.","difficulty":"very-hard","source":"UGC NET Management · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-710","question":"Consider these statements about the determinants of price elasticity of demand:\nI. Demand is usually more elastic in the long run than in the short run.\nII. Demand is usually more elastic when the item takes a small share of the buyer's budget.\nIII. Demand for a specific brand is usually more elastic than demand for the whole product category.\nWhich are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":1,"explanation":"Buyers find substitutes over time, and a brand has more close substitutes than its category, so I and III hold. II is reversed: items that take a large share of the budget have more elastic demand.","difficulty":"very-hard","source":"Bank SO (Marketing) · MBA placement (Marketing)"},
  {"id":"mgmt-marketing-711","question":"Match each pricing practice with its degree of price discrimination.\nA. A cloud firm sells each client at a price close to that client's maximum willingness to pay\nB. A telecom firm offers cheaper rates per GB on larger data packs, open to anyone\nC. A cinema charges students less than other adults\n1. First degree  2. Second degree  3. Third degree","options":["A-1, B-3, C-2","A-2, B-1, C-3","A-1, B-2, C-3","A-3, B-2, C-1"],"answer":2,"explanation":"First-degree discrimination charges each buyer his reservation price; second-degree offers a menu (quantity or version) and lets buyers self-select; third-degree charges different identifiable groups different prices.","difficulty":"very-hard","source":"MBA placement (Marketing) · UGC NET Management"},
  {"id":"mgmt-marketing-712","question":"In a month a SaaS firm adds ₹30 lakh of new MRR and ₹10 lakh of expansion MRR, while it loses ₹8 lakh to churn and ₹2 lakh to downgrades. What is its 'SaaS quick ratio'?","options":["3.75","5.0","3.0","4.0"],"answer":3,"explanation":"Quick ratio = (new + expansion MRR) ÷ (churned + contraction MRR) = 40 ÷ 10 = 4.0. 5.0 ignores downgrades and 3.75 ignores expansion.","difficulty":"hard","source":"MBA placement (Marketing)"},
  {"id":"mgmt-marketing-713","question":"A tea brand holds a 20% volume share of its category and sells at ₹600 a kg, while the category's average price is ₹500 a kg. What is its value share?","options":["24.0%","16.7%","20.0%","30.0%"],"answer":0,"explanation":"Value share = volume share × (brand price ÷ category average price) = 20% × 1.2 = 24%. Premium-priced brands have value shares above their volume shares; 16.7% divides by the price ratio instead.","difficulty":"hard","source":"MBA placement (Marketing) · Bank SO (Marketing)"},
  {"id":"mgmt-marketing-714","question":"Vargo and Lusch's service-dominant logic makes several claims about value. Which statement reflects it?","options":["Value is embedded in goods at the factory and delivered intact to the buyer","Services are a lesser form of goods, defined by their intangibility","The firm alone creates value; the customer only pays for and uses it","Value is always co-created with the customer and realised in use"],"answer":3,"explanation":"S-D logic treats service (applying competences for another's benefit) as the basis of all exchange; firms can only offer value propositions, and value is co-created and determined by the beneficiary in use.","difficulty":"very-hard","source":"UGC NET Management"},
];

export default questions;
